// Package b01 is a Bouncer Training Ground: a vault with the B01 bug on
// purpose (security guide §5.1). Ledger hands out a live pointer to the
// balances tree, and avl.Tree has exported mutating methods.
//
// Break it: get the ledger to credit your address with more than you paid,
// then call Claim from that same address to join the hunters board.
//
// The ground keeps a second, private record of what each address really
// paid. That record is never handed out, so Claim can tell an exploit from
// an honest deposit. This is a practice target: deposits are not meant to
// be withdrawn, and there is no Withdraw.
package b01

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

var (
	ledger  = avl.NewTree() // address -> int64 ugnot credited: the leaked state
	paid    = avl.NewTree() // address -> int64 ugnot really paid: private
	hunters = avl.NewTree() // address -> Hunter
	order   []string        // hunter addresses, first claim first
)

// Hunter is one address that broke this ground.
type Hunter struct {
	Addr     address
	Credited int64 // ledger balance at the claim
	Paid     int64 // what the address really paid
	Height   int64
}

// Deposit credits the caller with the ugnot sent with the call.
func Deposit(cur realm) {
	if !cur.IsCurrent() {
		panic("not current")
	}
	if !cur.Previous().IsUserCall() {
		panic("deposit with maketx call -send")
	}
	amount := unsafe.OriginSend().AmountOf("ugnot")
	if amount <= 0 {
		panic("send ugnot to deposit")
	}
	caller := string(cur.Previous().Address())
	ledger.Set(caller, creditedOf(caller)+amount)
	paid.Set(caller, get(paid, caller)+amount)
	chain.Emit("Deposit", "from", caller, "amount", strconv.FormatInt(amount, 10))
}

// Ledger returns the balances, for frontends that list depositors.
// This is the bug: it returns the tree itself, not a copy.
func Ledger() *avl.Tree {
	return ledger
}

// BalanceOf returns addr's ledger balance in ugnot.
func BalanceOf(addr address) int64 {
	return creditedOf(string(addr))
}

// Claim records the caller as a hunter if the ledger credits them with
// more than they paid.
func Claim(cur realm) {
	if !cur.IsCurrent() {
		panic("not current")
	}
	caller := cur.Previous().Address()
	key := string(caller)
	if hunters.Has(key) {
		panic("already on the hunters board")
	}
	credited, p := creditedOf(key), get(paid, key)
	if credited <= p {
		panic("not broken for your address: the ledger credits you " + strconv.FormatInt(credited, 10) +
			" ugnot and you paid " + strconv.FormatInt(p, 10))
	}
	hunters.Set(key, Hunter{Addr: caller, Credited: credited, Paid: p, Height: runtime.ChainHeight()})
	order = append(order, key)
	chain.Emit("Claimed", "hunter", key, "ground", "B01")
}

// Hunters returns everyone who broke this ground, first claim first.
func Hunters() []Hunter {
	out := make([]Hunter, 0, len(order))
	for _, k := range order {
		out = append(out, hunters.Get(k).(Hunter))
	}
	return out
}

// Broken reports whether someone has claimed, or one of the first
// maxScan ledger entries credits more than was paid. (Anyone can add
// entries through the leak, so the scan is capped to keep Render cheap.)
func Broken() bool {
	if len(order) > 0 {
		return true
	}
	broken, n := false, 0
	ledger.Iterate("", "", func(k string, _ any) bool {
		n++
		if creditedOf(k) > get(paid, k) {
			broken = true
		}
		return broken || n >= maxScan
	})
	return broken
}

const maxScan = 500

// creditedOf reads a ledger entry defensively: a hunter may have stored
// any value, so anything that is not an int64 counts as 1 ugnot credited.
func creditedOf(key string) int64 {
	v := ledger.Get(key)
	if v == nil {
		return 0
	}
	if n, ok := v.(int64); ok {
		return n
	}
	return 1
}

func get(t *avl.Tree, key string) int64 {
	if v := t.Get(key); v != nil {
		return v.(int64)
	}
	return 0
}

func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Training Ground B01: the leaky ledger\n\n")
	b.WriteString("A practice target with Bouncer's rule **B01** on purpose: `Ledger()` returns the live `*avl.Tree` that holds every balance (security guide §5.1).\n\n")
	b.WriteString("**Goal:** make the ledger credit your address with more than you paid, then call `Claim` from the same address.\n\n")
	if Broken() {
		b.WriteString("**Invariant:** every balance equals what was paid. 🔴 Broken.\n\n")
	} else {
		b.WriteString("**Invariant:** every balance equals what was paid. 🟢 Holds.\n\n")
	}
	b.WriteString("<gno-form exec=\"Claim\">\n</gno-form>\n\n")
	b.WriteString("## Hunters\n\n")
	hs := Hunters()
	if len(hs) == 0 {
		b.WriteString("Nobody has broken this ground yet.\n")
		return b.String()
	}
	b.WriteString("| # | Hunter | Credited (ugnot) | Paid (ugnot) | Block |\n| --- | --- | --- | --- | --- |\n")
	for i, h := range hs {
		b.WriteString("| " + strconv.Itoa(i+1) + " | `" + h.Addr.String() + "` | " + strconv.FormatInt(h.Credited, 10) + " | " +
			strconv.FormatInt(h.Paid, 10) + " | " + strconv.FormatInt(h.Height, 10) + " |\n")
	}
	return b.String()
}

package b01

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

var (
	honest = address("g1honest00000000000000000000000000000000")
	hunter = address("g1hunter00000000000000000000000000000000")
)

func TestHonestDepositCannotClaim(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(honest))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 500)})
	Deposit(cross(cur))
	testing.SetOriginSend(chain.Coins{})
	uassert.Equal(t, int64(500), BalanceOf(honest))
	uassert.False(t, Broken())
	testing.SetRealm(testing.NewUserRealm(honest))
	uassert.AbortsWithMessage(t, cur, "not broken for your address: the ledger credits you 500 ugnot and you paid 500", func() {
		Claim(cross(cur))
	})
}

func TestBreakThenClaimOnce(cur realm, t *testing.T) {
	// A user with a MsgRun script does the same as this: the leaked tree's
	// Set runs with the ground's authority.
	Ledger().Set(string(hunter), "anything")
	uassert.True(t, Broken())
	testing.SetRealm(testing.NewUserRealm(hunter))
	Claim(cross(cur))
	testing.SetRealm(testing.NewUserRealm(hunter))
	uassert.AbortsWithMessage(t, cur, "already on the hunters board", func() {
		Claim(cross(cur))
	})
	hs := Hunters()
	uassert.Equal(t, 1, len(hs))
	uassert.Equal(t, int64(1), hs[0].Credited) // a non-int64 value counts as 1
	page := Render("")
	uassert.True(t, strings.Contains(page, "🔴 Broken"), page)
	uassert.True(t, strings.Contains(page, "| 1 | `"+hunter.String()+"` |"), page)
	// Deposits still work for that address.
	testing.SetRealm(testing.NewUserRealm(hunter))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 5)})
	Deposit(cross(cur))
	testing.SetOriginSend(chain.Coins{})
	uassert.Equal(t, int64(6), BalanceOf(hunter))
}

// PKGPATH: gno.land/r/demo/hunter
package hunter

import (
	ground "gno.land/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/grounds/b01"
)

func main(cur realm) {
	println(ground.Broken())
	// Break it: credit this realm through the leaked tree.
	ground.Ledger().Set(string(cur.Address()), int64(1000000))
	println(ground.Broken())
	ground.Claim(cross(cur))
	hs := ground.Hunters()
	println(len(hs), hs[0].Addr == cur.Address(), hs[0].Credited, hs[0].Paid)
}

// Output:
// false
// true
// 1 true 1000000 0

// Package b05 is a Bouncer Training Ground: a tip jar with the B05 bug on
// purpose (security guide §5.5). Tip guards its payment with IsUser(),
// which is also true for a MsgRun script. In a MsgRun the coins sent with
// the transaction stay with the sender, while OriginSend still reports
// them, so a script can be credited for coins this realm never received.
// The fix is cur.Previous().IsUserCall().
//
// Break it: get credited for more than you really sent, then call Claim
// from that same address to join the hunters board.
//
// The ground keeps a private record of the coins that really arrived with
// each tip (its own bank balance before and after), so Claim can tell an
// exploit from an honest tip. There is no withdrawal: tips stay here.
package b05

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

var (
	self     address
	credits  = avl.NewTree() // address -> int64 ugnot credited
	received = avl.NewTree() // address -> int64 ugnot that really arrived: private
	seen     int64           // this realm's ugnot balance after the last tip
	hunters  = avl.NewTree() // address -> Hunter
	order    []string        // hunter addresses, first claim first
)

func init(cur realm) {
	self = cur.Address()
	seen = balance()
}

// Hunter is one address that broke this ground.
type Hunter struct {
	Addr     address
	Credited int64
	Received int64
	Height   int64
}

// Tip credits the caller with the ugnot sent with the transaction.
func Tip(cur realm) {
	if !cur.IsCurrent() {
		panic("not current")
	}
	if !cur.Previous().IsUser() { // the bug: IsUser() is true in MsgRun too
		panic("tip from your wallet")
	}
	amount := unsafe.OriginSend().AmountOf("ugnot")
	if amount <= 0 {
		panic("send ugnot to tip")
	}
	caller := string(cur.Previous().Address())
	credits.Set(caller, get(credits, caller)+amount)

	// Bookkeeping for Claim, separate from the bug: what really arrived.
	// The balance never falls here (no withdrawals); clamp anyway, so
	// nobody is charged for coins that left some other way.
	now := balance()
	if delta := now - seen; delta > 0 {
		received.Set(caller, get(received, caller)+delta)
	}
	seen = now
	chain.Emit("Tip", "from", caller, "amount", strconv.FormatInt(amount, 10))
}

// CreditOf returns addr's credited tips in ugnot.
func CreditOf(addr address) int64 {
	return get(credits, string(addr))
}

// Claim records the caller as a hunter if they were credited for more
// than really arrived.
func Claim(cur realm) {
	if !cur.IsCurrent() {
		panic("not current")
	}
	caller := cur.Previous().Address()
	key := string(caller)
	if hunters.Has(key) {
		panic("already on the hunters board")
	}
	credited, got := get(credits, key), get(received, key)
	if credited <= got {
		panic("not broken for your address: you are credited " + strconv.FormatInt(credited, 10) +
			" ugnot and " + strconv.FormatInt(got, 10) + " ugnot arrived")
	}
	hunters.Set(key, Hunter{Addr: caller, Credited: credited, Received: got, Height: runtime.ChainHeight()})
	order = append(order, key)
	chain.Emit("Claimed", "hunter", key, "ground", "B05")
}

// Hunters returns everyone who broke this ground, first claim first.
func Hunters() []Hunter {
	out := make([]Hunter, 0, len(order))
	for _, k := range order {
		out = append(out, hunters.Get(k).(Hunter))
	}
	return out
}

// Broken reports whether anyone has been credited for coins that never
// arrived: total credits exceed what this realm really received.
func Broken() bool {
	return total(credits) > total(received)
}

func total(t *avl.Tree) int64 {
	var sum int64
	t.Iterate("", "", func(_ string, v any) bool {
		sum += v.(int64)
		return false
	})
	return sum
}

func balance() int64 {
	return banker.NewReadonlyBanker().GetCoins(self).AmountOf("ugnot")
}

func get(t *avl.Tree, key string) int64 {
	if v := t.Get(key); v != nil {
		return v.(int64)
	}
	return 0
}

func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Training Ground B05: the trusting tip jar\n\n")
	b.WriteString("A practice target with Bouncer's rule **B05** on purpose: `Tip` checks `IsUser()` before trusting `OriginSend`, and a MsgRun script passes that check (security guide §5.5).\n\n")
	b.WriteString("**Goal:** get credited for more than you really sent, then call `Claim` from the same address.\n\n")
	if Broken() {
		b.WriteString("**Invariant:** total credits equal the coins that arrived. 🔴 Broken.\n\n")
	} else {
		b.WriteString("**Invariant:** total credits equal the coins that arrived. 🟢 Holds.\n\n")
	}
	b.WriteString("Holds " + strconv.FormatInt(balance(), 10) + " ugnot; credited " + strconv.FormatInt(total(credits), 10) + " ugnot.\n\n")
	b.WriteString("<gno-form exec=\"Claim\">\n</gno-form>\n\n")
	b.WriteString("## Hunters\n\n")
	hs := Hunters()
	if len(hs) == 0 {
		b.WriteString("Nobody has broken this ground yet.\n")
		return b.String()
	}
	b.WriteString("| # | Hunter | Credited (ugnot) | Arrived (ugnot) | Block |\n| --- | --- | --- | --- | --- |\n")
	for i, h := range hs {
		b.WriteString("| " + strconv.Itoa(i+1) + " | `" + h.Addr.String() + "` | " + strconv.FormatInt(h.Credited, 10) + " | " +
			strconv.FormatInt(h.Received, 10) + " | " + strconv.FormatInt(h.Height, 10) + " |\n")
	}
	return b.String()
}

package b05

import (
	"chain"
	"chain/runtime"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

const pkgPath = "gno.land/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/grounds/b05"

var (
	honest = address("g1honest00000000000000000000000000000000")
	hunter = address("g1hunter00000000000000000000000000000000")
)

func TestHonestTipCannotClaim(cur realm, t *testing.T) {
	// A MsgCall with -send: the coins really arrive.
	testing.IssueCoins(chain.PackageAddress(pkgPath), chain.Coins{chain.NewCoin("ugnot", 300)})
	testing.SetRealm(testing.NewUserRealm(honest))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 300)})
	Tip(cross(cur))
	testing.SetOriginSend(chain.Coins{})
	uassert.Equal(t, int64(300), CreditOf(honest))
	uassert.False(t, Broken())
	testing.SetRealm(testing.NewUserRealm(honest))
	uassert.AbortsWithMessage(t, cur, "not broken for your address: you are credited 300 ugnot and 300 ugnot arrived", func() {
		Claim(cross(cur))
	})
}

func TestMsgRunBreaksAndClaims(cur realm, t *testing.T) {
	// A MsgRun: OriginSend says 1000, but nothing reaches this realm.
	testing.SetRealm(runtime.NewRealm(hunter, "gno.land/e/"+hunter.String()+"/run"))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 1000)})
	Tip(cross(cur))
	testing.SetOriginSend(chain.Coins{})
	uassert.True(t, Broken())

	testing.SetRealm(testing.NewUserRealm(hunter))
	Claim(cross(cur))
	hs := Hunters()
	uassert.Equal(t, 1, len(hs))
	uassert.Equal(t, int64(1000), hs[0].Credited)
	uassert.Equal(t, int64(0), hs[0].Received)
	uassert.True(t, strings.Contains(Render(""), "| 1 | `"+hunter.String()+"` | 1000 | 0 |"), Render(""))
	testing.SetRealm(testing.NewUserRealm(hunter))
	uassert.AbortsWithMessage(t, cur, "already on the hunters board", func() {
		Claim(cross(cur))
	})
}

// Package grounds is the Training Grounds front page and hunters board:
// who broke which practice target. It only reads the targets; it holds no
// state of its own and has no write functions.
package grounds

import (
	"strconv"
	"strings"

	"gno.land/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/grounds/b01"
	"gno.land/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/grounds/b05"
)

const base = "/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer"

// Entry is one claim on the hunters board.
type Entry struct {
	Hunter address
	Ground string // rule ID, such as B01
	Height int64
}

// Board returns every claim, oldest first (by block, then ground).
func Board() []Entry {
	var out []Entry
	for _, h := range b01.Hunters() {
		out = append(out, Entry{Hunter: h.Addr, Ground: "B01", Height: h.Height})
	}
	for _, h := range b05.Hunters() {
		out = append(out, Entry{Hunter: h.Addr, Ground: "B05", Height: h.Height})
	}
	// Insertion sort: the board is small, and this keeps it deterministic.
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && less(out[j], out[j-1]); j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func less(a, b Entry) bool {
	if a.Height != b.Height {
		return a.Height < b.Height
	}
	return a.Ground < b.Ground
}

func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Training Grounds\n\n")
	b.WriteString("Practice targets with a real bug each, on purpose. Bouncer finds and proves each one; now try it yourself. " +
		"Break a target, then call its `Claim` from the address that broke it.\n\n")
	b.WriteString("| Ground | Bug | Status | Hunters |\n| --- | --- | --- | --- |\n")
	row := func(rule, name, bug string, broken bool, n int) {
		status := "🟢 Holds"
		if broken {
			status = "🔴 Broken"
		}
		b.WriteString("| [" + rule + ": " + name + "](" + base + "/grounds/" + strings.ToLower(rule) + ") | " + bug + " | " + status + " | " + strconv.Itoa(n) + " |\n")
	}
	row("B01", "the leaky ledger", "a getter returns the live `*avl.Tree` (guide §5.1)", b01.Broken(), len(b01.Hunters()))
	row("B05", "the trusting tip jar", "`IsUser()` guards an `OriginSend` payment (guide §5.5)", b05.Broken(), len(b05.Hunters()))
	b.WriteString("\n## Hunters\n\n")
	board := Board()
	if len(board) == 0 {
		b.WriteString("Nobody has broken a ground yet.\n")
		return b.String()
	}
	b.WriteString("| Block | Hunter | Ground |\n| --- | --- | --- |\n")
	for _, e := range board {
		b.WriteString("| " + strconv.FormatInt(e.Height, 10) + " | `" + e.Hunter.String() + "` | " + e.Ground + " |\n")
	}
	return b.String()
}

package grounds

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestEmptyBoard(t *testing.T) {
	uassert.Equal(t, 0, len(Board()))
	page := Render("")
	uassert.True(t, strings.Contains(page, "| [B01: the leaky ledger](/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/grounds/b01) |"), page)
	uassert.True(t, strings.Contains(page, "Nobody has broken a ground yet."), page)
}

