package wagers

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// Render shows the realm's pages on gnoweb:
//
//	""         home: how it works + all tables
//	"table/N"  a table: members, leaderboard, bets
//	"bet/N"    a bet: players, reports, votes, payouts, actions
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 2 {
		if _, err := strconv.Atoi(parts[1]); err == nil {
			switch parts[0] {
			case "table":
				if v := tables.Get(parts[1]); v != nil {
					return renderTable(v.(*Table))
				}
				return "# Table not found\n\n[Back home](" + home() + ")"
			case "bet":
				if v := bets.Get(parts[1]); v != nil {
					return renderBet(v.(*Bet))
				}
				return "# Bet not found\n\n[Back home](" + home() + ")"
			}
		}
	}
	return renderHome()
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# 🍺 Tavern Wagers\n\n")
	sb.WriteString("**Bet on anything with your friends. The money's locked upfront, neutral judges call it, and the winner gets paid automatically. No more \"I'll pay you later.\"**\n\n")
	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Open a table** and invite your friends.\n")
	sb.WriteString("2. **Make a bet** against a friend. Both players lock the same stake + a 10% honesty bond.\n")
	sb.WriteString("3. **Play** (chess, FIFA, D&D, anything).\n")
	sb.WriteString("4. **Both players report the result.** If you agree, you're paid instantly and get your bonds back.\n")
	sb.WriteString("5. **Disagree?** Everyone else at the table becomes a judge. They have no money in it, so they have no reason to lie. A strict majority decides.\n")
	sb.WriteString("6. **Lying costs you.** The player who loses the vote forfeits their bond: half to the honest player, half to the judges. Judges also split a 1% fee for showing up.\n")
	sb.WriteString("7. **No majority before the deadline?** Everyone is refunded in full.\n\n")
	sb.WriteString("The realm keeps nothing. Every coin that goes in comes back out to players and judges.\n\n")
	sb.WriteString("[➕ Open a new table](" + call("CreateTable") + ")\n\n")

	sb.WriteString("## Tables\n\n")
	if tables.Size() == 0 {
		sb.WriteString("_No tables yet. Be the first._\n")
		return sb.String()
	}
	sb.WriteString("| Table | Members | Bets | Owner |\n|---|---|---|---|\n")
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Table)
		sb.WriteString("| [" + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ") | " +
			strconv.Itoa(len(t.Members)) + " | " + strconv.Itoa(len(t.BetIDs)) + " | " + short(t.Owner) + " |\n")
		return false
	})
	return sb.String()
}

func renderTable(t *Table) string {
	var sb strings.Builder
	id := strconv.Itoa(t.ID)
	sb.WriteString("[← All tables](" + home() + ")\n\n")
	sb.WriteString("# 🍺 " + escape(t.Name) + "\n\n")
	sb.WriteString("Table #" + id + " · owner " + short(t.Owner) + " · " + strconv.Itoa(len(t.Members)) + " members\n\n")
	sb.WriteString("[🎲 New bet](" + call("CreateBet", "tableID", id) + ") · ")
	sb.WriteString("[👋 Add member (owner only)](" + call("AddMember", "tableID", id) + ")\n\n")

	// Leaderboard, sorted by net winnings.
	sb.WriteString("## 🏆 Leaderboard\n\n")
	var rows []row
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		rows = append(rows, row{m, s})
	}
	for i := 1; i < len(rows); i++ { // insertion sort, highest net first
		for j := i; j > 0 && rows[j].s.Net > rows[j-1].s.Net; j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	sb.WriteString("| # | Member | Net | W | L | D | Disputes lost | Judged |\n|---|---|---|---|---|---|---|---|\n")
	for i, r := range rows {
		liar := strconv.Itoa(r.s.DisputesLost)
		if r.s.DisputesLost > 0 {
			liar = "🚩 " + liar
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + short(r.addr) + " | " + gnot(r.s.Net, true) + " | " +
			strconv.Itoa(r.s.Wins) + " | " + strconv.Itoa(r.s.Losses) + " | " + strconv.Itoa(r.s.Draws) + " | " +
			liar + " | " + strconv.Itoa(r.s.Judged) + " |\n")
	}

	sb.WriteString("\n## 🎲 Bets\n\n")
	if len(t.BetIDs) == 0 {
		sb.WriteString("_No bets yet._\n")
		return sb.String()
	}
	sb.WriteString("| Bet | Players | Stake | Status |\n|---|---|---|---|\n")
	for i := len(t.BetIDs) - 1; i >= 0; i-- {
		b := mustBet(t.BetIDs[i])
		sb.WriteString("| [" + escape(b.Title) + "](" + page("bet/"+strconv.Itoa(b.ID)) + ") | " +
			short(b.PlayerA) + " vs " + short(b.PlayerB) + " | " + gnot(b.Stake, false) + " | " + statusBadge(b) + " |\n")
	}
	return sb.String()
}

func renderBet(b *Bet) string {
	var sb strings.Builder
	id := strconv.Itoa(b.ID)
	t := mustTable(b.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🎲 " + escape(b.Title) + "\n\n")
	sb.WriteString("**Status: " + statusBadge(b) + "**\n\n")

	sb.WriteString("| | Player A | Player B |\n|---|---|---|\n")
	sb.WriteString("| Who | " + short(b.PlayerA) + " | " + short(b.PlayerB) + " |\n")
	sb.WriteString("| Stake | " + gnot(b.Stake, false) + " | " + gnot(b.Stake, false) + " |\n")
	sb.WriteString("| Honesty bond | " + gnot(b.Bond, false) + " | " + gnot(b.Bond, false) + " |\n")
	sb.WriteString("| Reported | " + showReport(b.ReportA) + " | " + showReport(b.ReportB) + " |\n\n")
	sb.WriteString("Pot: **" + gnot(2*b.Stake, false) + "**\n\n")

	send := strconv.FormatInt(b.Stake+b.Bond, 10) + "ugnot"
	switch b.Status {
	case StatusOpen:
		sb.WriteString("### Actions\n\n")
		sb.WriteString("- Player B: [✅ Accept and lock " + gnot(b.Stake+b.Bond, false) + "](" +
			callSend("AcceptBet", send, "betID", id) + ")\n")
		sb.WriteString("- Player A: [❌ Cancel and refund](" + call("CancelBet", "betID", id) + ")\n")
	case StatusLive:
		sb.WriteString("### Report the result\n\n")
		sb.WriteString("[A won](" + call("Report", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[B won](" + call("Report", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Draw](" + call("Report", "betID", id, "result", ResultDraw) + ")\n\n")
		if (b.ReportA == "") != (b.ReportB == "") {
			when := b.FirstReportAt.Add(ReportWindow)
			sb.WriteString("_One player has reported. The other has until " + when.UTC().Format(time.RFC822) +
				" to answer, then either player can [⚖️ send it to the judges](" + call("Escalate", "betID", id) + ")._\n")
		}
	case StatusDisputed:
		sb.WriteString("### ⚖️ Judges are voting\n\n")
		sb.WriteString("Players disagree. Judges (table members with no money in this bet) decide. ")
		need := len(b.Judges)/2 + 1
		sb.WriteString("A result needs **" + strconv.Itoa(need) + " of " + strconv.Itoa(len(b.Judges)) + "** votes. ")
		sb.WriteString("Voting closes " + b.Deadline.UTC().Format(time.RFC822) + ".\n\n")
		sb.WriteString("Votes so far: A won **" + strconv.Itoa(b.countVotes(ResultA)) + "** · B won **" +
			strconv.Itoa(b.countVotes(ResultB)) + "** · Draw **" + strconv.Itoa(b.countVotes(ResultDraw)) + "**\n\n")
		sb.WriteString("Judges: [Vote A won](" + call("Vote", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[Vote B won](" + call("Vote", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Vote draw](" + call("Vote", "betID", id, "result", ResultDraw) + ")\n\n")
		sb.WriteString("_No majority by the deadline? Anyone can [refund everyone](" + call("ExpireDispute", "betID", id) + ")._\n")
	}

	if len(b.Judges) > 0 {
		sb.WriteString("\n### Judges\n\n")
		for _, j := range b.Judges {
			vote := "not voted"
			if v, ok := b.Votes.Get(j.String()).(string); ok {
				vote = showReport(v)
			}
			sb.WriteString("- " + short(j) + ": " + vote + "\n")
		}
	}

	if len(b.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, p := range b.Payouts {
			sb.WriteString("| " + short(p.To) + " | " + gnot(p.Amount, false) + " | " + p.Why + " |\n")
		}
	}
	return sb.String()
}

type row struct {
	addr address
	s    *Stats
}

// ---------------------------------------------------------------------------
// Formatting helpers

func statusBadge(b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "🟡 waiting for player B"
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		return "✅ settled: " + showReport(b.Final)
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return b.Status.String()
}

func showReport(r string) string {
	switch r {
	case ResultA:
		return "A won"
	case ResultB:
		return "B won"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64, signed bool) string {
	sign := ""
	if u < 0 {
		sign = "-"
		u = -u
	} else if signed && u > 0 {
		sign = "+"
	}
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		s += "." + strings.TrimRight(f, "0")
	}
	return sign + s + " GNOT"
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:7] + "…" + s[len(s)-4:] + "`"
}

func escape(s string) string {
	r := strings.NewReplacer("|", "\\|", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "\n", " ")
	return r.Replace(s)
}

func prefix() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func home() string           { return prefix() }
func page(sub string) string { return prefix() + ":" + sub }

// call builds a gnoweb transaction link: /r/...$help&func=Fn&k=v
func call(fn string, kv ...string) string {
	return callSend(fn, "", kv...)
}

func callSend(fn, send string, kv ...string) string {
	q := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		q.Add(kv[i], kv[i+1])
	}
	if send != "" {
		q.Add(".send", send)
	}
	link := prefix() + "$help&func=" + fn
	if enc := q.Encode(); enc != "" {
		link += "&" + enc
	}
	return link
}

// Package wagers lets friend groups ("tables") bet on anything with each other.
//
// How it works:
//   - A table is an invite-only group of friends.
//   - Two players lock the same stake into the realm before the game,
//     plus a 10% honesty bond.
//   - After the game, both players report the result. If they agree, the
//     realm pays out instantly and both bonds come back.
//   - If they disagree, every other table member becomes a judge. Judges
//     have no money in the bet, so they have no reason to lie. As soon as
//     a strict majority of judges agree, the bet settles.
//   - A player whose report loses the vote forfeits their bond. Half goes
//     to the honest player, half to the judges who voted with the majority.
//     Majority judges also split a 1% fee from the pot for showing up.
//   - If the judges can't reach a majority before the deadline, everyone
//     is refunded in full.
//
// The realm takes no cut: every coin that goes in comes back out to the
// players and judges.
package wagers

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	ResultA    = "a"    // player A won
	ResultB    = "b"    // player B won
	ResultDraw = "draw" // draw, stakes go back

	MinStake int64 = 10_000 // 0.01 GNOT

	ReportWindow = 24 * time.Hour // how long a player has to answer the other's report
	VoteWindow   = 48 * time.Hour // how long judges have to vote
)

type BetStatus int

const (
	StatusOpen      BetStatus = iota // waiting for player B to accept
	StatusLive                       // both staked, waiting for reports
	StatusDisputed                   // players disagree, judges voting
	StatusSettled                    // paid out
	StatusCancelled                  // cancelled before B accepted
	StatusRefunded                   // judges could not decide, everyone refunded
)

func (s BetStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusLive:
		return "live"
	case StatusDisputed:
		return "disputed"
	case StatusSettled:
		return "settled"
	case StatusCancelled:
		return "cancelled"
	case StatusRefunded:
		return "refunded"
	}
	return "unknown"
}

// Stats is one member's record at a table.
type Stats struct {
	Net          int64 // ugnot won minus ugnot lost
	Wins         int
	Losses       int
	Draws        int
	DisputesLost int // times this player's report lost a judges' vote
	Judged       int // times this member voted with the majority as a judge
}

type Table struct {
	ID      int
	Name    string
	Owner   address
	Members []address
	Stats   *avl.Tree // address -> *Stats
	BetIDs  []int
	Created time.Time
}

type Payout struct {
	To     address
	Amount int64
	Why    string
}

type Bet struct {
	ID      int
	TableID int
	Title   string
	PlayerA address
	PlayerB address
	Stake   int64 // per player
	Bond    int64 // per player
	Status  BetStatus

	ReportA       string
	ReportB       string
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> result string
	Deadline time.Time // voting deadline when disputed

	Final   string
	Payouts []Payout
	Created time.Time
}

var (
	tables   avl.Tree // id -> *Table
	bets     avl.Tree // id -> *Bet
	tableSeq int
	betSeq   int
)

// ---------------------------------------------------------------------------
// Tables

// CreateTable opens a new table. The caller becomes its owner and first member.
func CreateTable(cur realm, name string) int {
	caller := cur.Previous().Address()
	name = strings.TrimSpace(name)
	require(name != "", "table name required")
	require(len(name) <= 64, "table name too long (max 64)")

	tableSeq++
	t := &Table{
		ID:      tableSeq,
		Name:    name,
		Owner:   caller,
		Members: []address{caller},
		Stats:   avl.NewTree(),
		Created: time.Now(),
	}
	tables.Set(strconv.Itoa(t.ID), t)
	return t.ID
}

// AddMember invites a friend to a table. Only the table owner can do this.
func AddMember(cur realm, tableID int, member address) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can add members")
	require(member.IsValid(), "invalid address")
	require(!t.isMember(member), "already a member")
	require(len(t.Members) < 50, "table is full (max 50)")
	t.Members = append(t.Members, member)
}

// ---------------------------------------------------------------------------
// Bets

// CreateBet proposes a bet against another table member and locks your stake.
// Send exactly stake + 10% bond, e.g. stake 1000000 -> send 1100000ugnot.
// You are player A, the opponent is player B.
func CreateBet(cur realm, tableID int, title string, opponent address, stake int64) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "bet title required")
	require(len(title) <= 140, "bet title too long (max 140)")
	require(t.isMember(caller), "you are not a member of this table")
	require(t.isMember(opponent), "opponent is not a member of this table")
	require(opponent != caller, "you can't bet against yourself")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	bond := stake / 10
	requireSent(stake + bond)

	betSeq++
	b := &Bet{
		ID:      betSeq,
		TableID: tableID,
		Title:   title,
		PlayerA: caller,
		PlayerB: opponent,
		Stake:   stake,
		Bond:    bond,
		Status:  StatusOpen,
		Votes:   avl.NewTree(),
		Created: time.Now(),
	}
	bets.Set(strconv.Itoa(b.ID), b)
	t.BetIDs = append(t.BetIDs, b.ID)
	return b.ID
}

// AcceptBet is called by player B to match the stake and bond.
func AcceptBet(cur realm, betID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	require(caller == b.PlayerB, "only the challenged player can accept")
	requireSent(b.Stake + b.Bond)
	b.Status = StatusLive
}

// CancelBet lets player A take the bet back before B accepts it.
func CancelBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "only open bets can be cancelled")
	require(caller == b.PlayerA, "only the player who created the bet can cancel it")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "cancelled, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// Report is how each player says who won: "a", "b" or "draw".
// If both players report the same result, the bet pays out right away.
// If they disagree, it goes to the judges.
func Report(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	result = normalizeResult(result)

	switch caller {
	case b.PlayerA:
		require(b.ReportA == "", "you already reported")
		b.ReportA = result
	case b.PlayerB:
		require(b.ReportB == "", "you already reported")
		b.ReportB = result
	default:
		panic("only the two players can report")
	}

	if b.ReportA == "" || b.ReportB == "" {
		b.FirstReportAt = time.Now()
		return
	}

	if b.ReportA == b.ReportB {
		b.settle(b.ReportA, nil)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
		return
	}

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Escalate sends a bet to the judges when one player reported and the
// other went quiet for longer than the report window.
func Escalate(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	require(caller == b.PlayerA || caller == b.PlayerB, "only the players can escalate")
	require((b.ReportA == "") != (b.ReportB == ""), "escalate needs exactly one report")
	require(time.Now().After(b.FirstReportAt.Add(ReportWindow)), "the other player still has time to report")

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Vote is for judges of a disputed bet: "a", "b" or "draw".
// The bet settles the moment one result has a strict majority of judges.
func Vote(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(b.isJudge(caller), "you are not a judge on this bet")
	require(!b.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(b.Deadline), "voting is closed")
	result = normalizeResult(result)

	b.Votes.Set(caller.String(), result)

	if b.countVotes(result)*2 > len(b.Judges) {
		var majority []address
		for _, j := range b.Judges {
			if v, ok := b.Votes.Get(j.String()).(string); ok && v == result {
				majority = append(majority, j)
			}
		}
		b.settle(result, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// ExpireDispute refunds everyone if the judges failed to reach a majority
// before the deadline. Anyone can call it.
func ExpireDispute(cur realm, betID int) {
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(time.Now().After(b.Deadline), "voting is still open")
	b.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement logic (pure bookkeeping, no coins move here)

// openDispute snapshots the judges. It returns false if the bet had to be
// refunded instead (a table with no possible judges).
func (b *Bet) openDispute() bool {
	t := mustTable(b.TableID)
	var judges []address
	for _, m := range t.Members {
		if m != b.PlayerA && m != b.PlayerB {
			judges = append(judges, m)
		}
	}
	if len(judges) == 0 {
		b.refundAll("no judges at this table")
		return false
	}
	b.Judges = judges
	b.Status = StatusDisputed
	b.Deadline = time.Now().Add(VoteWindow)
	return true
}

func (b *Bet) refundAll(why string) {
	b.Status = StatusRefunded
	each := b.Stake + b.Bond
	b.Payouts = []Payout{
		{b.PlayerA, each, why + ", refund"},
		{b.PlayerB, each, why + ", refund"},
	}
}

// settle fills in b.Payouts for a final result and updates the leaderboard.
// majority is nil when the players agreed (no judges involved).
func (b *Bet) settle(final string, majority []address) {
	b.Status = StatusSettled
	b.Final = final
	pot := 2 * b.Stake

	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = 2 * (b.Stake / 100) // 1% of the pot, always even
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, minus the judges' fee.
	switch final {
	case ResultA:
		add(b.PlayerA, pot-fee, "won the pot")
	case ResultB:
		add(b.PlayerB, pot-fee, "won the pot")
	case ResultDraw:
		add(b.PlayerA, b.Stake-fee/2, "draw, stake back")
		add(b.PlayerB, b.Stake-fee/2, "draw, stake back")
	}

	// 2. Honesty bonds.
	forfeited := int64(0)
	var honest []address
	t := mustTable(b.TableID)
	players := []address{b.PlayerA, b.PlayerB}
	reports := []string{b.ReportA, b.ReportB}
	for i := range players {
		if !disputed || reports[i] == final {
			add(players[i], b.Bond, "bond back")
			if disputed {
				honest = append(honest, players[i])
			}
		} else {
			forfeited += b.Bond
			t.stats(players[i]).DisputesLost++
		}
	}

	// 3. Forfeited bonds: half to the honest player(s), half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liar's bond", add)
		} else {
			judgePool += forfeited
		}
	}

	// 4. Judges who voted with the majority split their pool.
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
		}
	}

	b.Payouts = payouts

	// Leaderboard: net result per person, relative to what they put in.
	deposit := b.Stake + b.Bond
	t.stats(b.PlayerA).Net += received(payouts, b.PlayerA) - deposit
	t.stats(b.PlayerB).Net += received(payouts, b.PlayerB) - deposit
	for _, j := range majority {
		t.stats(j).Net += received(payouts, j)
	}
	switch final {
	case ResultA:
		t.stats(b.PlayerA).Wins++
		t.stats(b.PlayerB).Losses++
	case ResultB:
		t.stats(b.PlayerB).Wins++
		t.stats(b.PlayerA).Losses++
	case ResultDraw:
		t.stats(b.PlayerA).Draws++
		t.stats(b.PlayerB).Draws++
	}
}

// split divides amount evenly; the remainder goes to the first recipient so
// no dust is ever stuck in the realm.
func split(to []address, amount int64, why string, add func(address, int64, string)) {
	if len(to) == 0 || amount <= 0 {
		return
	}
	n := int64(len(to))
	each := amount / n
	rest := amount - each*n
	for i, a := range to {
		amt := each
		if i == 0 {
			amt += rest
		}
		add(a, amt, why)
	}
}

func received(payouts []Payout, who address) int64 {
	total := int64(0)
	for _, p := range payouts {
		if p.To == who {
			total += p.Amount
		}
	}
	return total
}

// pay moves the coins. The banker is always created inside the exported
// crossing function, from its own cur.
func pay(bk banker.Banker, from address, payouts []Payout) {
	for _, p := range payouts {
		bk.SendCoins(from, p.To, chain.Coins{{"ugnot", p.Amount}})
	}
}

// ---------------------------------------------------------------------------
// Read-only getters

func GetTableName(tableID int) string { return mustTable(tableID).Name }
func GetBetStatus(betID int) string   { return mustBet(betID).Status.String() }
func GetBetResult(betID int) string   { return mustBet(betID).Final }

func GetNet(tableID int, who address) int64 {
	t := mustTable(tableID)
	if v := t.Stats.Get(who.String()); v != nil {
		return v.(*Stats).Net
	}
	return 0
}

// ---------------------------------------------------------------------------
// Helpers

func (t *Table) isMember(a address) bool {
	for _, m := range t.Members {
		if m == a {
			return true
		}
	}
	return false
}

func (t *Table) stats(a address) *Stats {
	if v := t.Stats.Get(a.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	t.Stats.Set(a.String(), s)
	return s
}

func (b *Bet) isJudge(a address) bool {
	for _, j := range b.Judges {
		if j == a {
			return true
		}
	}
	return false
}

func (b *Bet) countVotes(result string) int {
	n := 0
	b.Votes.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == result {
			n++
		}
		return false
	})
	return n
}

func normalizeResult(r string) string {
	r = strings.ToLower(strings.TrimSpace(r))
	require(r == ResultA || r == ResultB || r == ResultDraw, `result must be "a", "b" or "draw"`)
	return r
}

func requireSent(want int64) {
	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == "ugnot",
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
	require(sent[0].Amount == want,
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
}

func mustTable(id int) *Table {
	v := tables.Get(strconv.Itoa(id))
	if v == nil {
		panic("table not found")
	}
	return v.(*Table)
}

func mustBet(id int) *Bet {
	v := bets.Get(strconv.Itoa(id))
	if v == nil {
		panic("bet not found")
	}
	return v.(*Bet)
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

package bouncer

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

// Finding is one attested finding. The detail fields (Snippet onward) are
// filled once, after Attest, by AddDetail.
type Finding struct {
	Rule     string // B01 ...
	Severity string // critical, high, medium
	Label    string // PROVEN, NOT REPRODUCED, STATIC WARNING
	File     string
	Line     int
	Func     string // enclosing function, if known

	Detailed bool   // AddDetail has run for this finding
	Snippet  string // the vulnerable code
	Attack   string // what the exploit did, one line (PROVEN only)
	Exploit  string // the attacker source that ran (PROVEN only)
	Before   string // evidence before the attack (PROVEN only)
	After    string // evidence after the attack (PROVEN only)
}

// Attestation is a scan result posted by an attester.
type Attestation struct {
	ID             uint64
	PkgPath        string
	SourceHash     string // sha256 of the scanned source, hex
	ScannerVersion string
	RulesetHash    string // hex
	Toolchain      string // gno version the exploits ran on
	ReportHash     string // sha256 of the full JSON report, hex
	ReportURI      string // where the full report lives (ipfs:// or https://)
	Findings       []Finding
	Deps           Deps
	Score          int
	Grade          string
	Verdict        string
	Attester       address
	Height         int64
	Time           int64 // unix seconds, block time
}

// AuthorReply is an author's response to a Passport.
type AuthorReply struct {
	Author    address
	Note      string
	Successor string // pkgpath of the fixed version, if any
	Height    int64
}

// record holds everything known about one package.
type record struct {
	history []Attestation // oldest first
	replies []AuthorReply
}

const (
	maxFindings = 64
	maxHistory  = 50
	maxReplies  = 20
	maxNoteLen  = 280
	maxRecent   = 10
)

// Attest records a scan result for pkgpath. Attesters only. findings is a
// ";"-separated list of "RULE,severity,LABEL,file,line[,func]" entries (""
// for none), in the report's order. deps is the import tree (see
// parseDeps). Score, grade and verdict are computed here from the findings
// and the dependencies' statuses in this registry.
func Attest(cur realm, pkgpath, sourceHash, scannerVersion, rulesetHash, toolchain, reportHash, reportURI, findings, deps string) uint64 {
	attester := assertAttester(cur)
	if !validPkgPath(pkgpath) {
		panic("invalid package path")
	}
	for _, h := range []string{sourceHash, rulesetHash, reportHash} {
		if !isHex64(h) {
			panic("hashes must be 64 lowercase hex characters")
		}
	}
	if !isToken(scannerVersion) || !isToken(toolchain) {
		panic("invalid scanner or toolchain version")
	}
	if !validReportURI(reportURI) {
		panic("report URI must be ipfs://<cid> or an https:// URL")
	}
	fs := parseFindings(findings)
	ds := parseDeps(pkgpath, deps)

	rec := getRecord(pkgpath)
	if rec == nil {
		rec = &record{}
		records.Set(pkgpath, rec)
		if author, ok := authorOf(pkgpath); ok {
			addToAuthor(author, pkgpath)
		}
		addToFamily(pkgpath)
	} else {
		if len(rec.history) >= maxHistory {
			panic("attestation history is full for this package")
		}
		prev := rec.history[len(rec.history)-1]
		totalFindings -= len(prev.Findings)
		totalProven -= countProven(prev.Findings)
	}
	id := uint64(attestationID.Next())
	a := Attestation{
		ID:             id,
		PkgPath:        pkgpath,
		SourceHash:     sourceHash,
		ScannerVersion: scannerVersion,
		RulesetHash:    rulesetHash,
		Toolchain:      toolchain,
		ReportHash:     reportHash,
		ReportURI:      reportURI,
		Findings:       fs,
		Deps:           Deps{List: ds},
		Attester:       attester,
		Height:         runtime.ChainHeight(),
		Time:           time.Now().Unix(),
	}
	// Stored values are a snapshot; reads recompute them (see live).
	snap := live(a)
	_, _, verdict := ScoreFor(fs, Deps{})
	a.Score, a.Grade, a.Verdict = snap.Score, snap.Grade, verdict
	score, grade := snap.Score, snap.Grade
	rec.history = append(rec.history, a)
	totalFindings += len(fs)
	totalProven += countProven(fs)
	markRecent(pkgpath)
	closeRequestsFor(pkgpath)
	chain.Emit("Attested",
		"id", seqid.ID(id).String(),
		"pkgpath", pkgpath,
		"score", strconv.Itoa(score),
		"grade", grade,
		"verdict", verdict,
		"report_hash", reportHash,
		"attester", attester.String())
	return id
}

func getRecord(pkgpath string) *record {
	v := records.Get(pkgpath)
	if v == nil {
		return nil
	}
	return v.(*record)
}

func addToAuthor(author address, pkgpath string) {
	var t *avl.Tree
	if v := byAuthor.Get(string(author)); v != nil {
		t = v.(*avl.Tree)
	} else {
		t = avl.NewTree()
		byAuthor.Set(string(author), t)
	}
	t.Set(pkgpath, true)
}

func markRecent(pkgpath string) {
	next := []string{pkgpath}
	for _, p := range recent {
		if p != pkgpath && len(next) < maxRecent {
			next = append(next, p)
		}
	}
	recent = next
}

func countProven(fs []Finding) int {
	n := 0
	for _, f := range fs {
		if f.Label == LabelProven {
			n++
		}
	}
	return n
}

// parseFindings validates and decodes the findings argument.
func parseFindings(s string) []Finding {
	out := []Finding{}
	if s == "" {
		return out
	}
	entries := strings.Split(s, ";")
	if len(entries) > maxFindings {
		panic("too many findings")
	}
	for _, e := range entries {
		parts := strings.Split(e, ",")
		if len(parts) != 5 && len(parts) != 6 {
			panic("finding must be RULE,severity,LABEL,file,line[,func]: " + e)
		}
		f := Finding{Rule: parts[0], Severity: parts[1], Label: parts[2], File: parts[3]}
		if !isRuleID(f.Rule) {
			panic("invalid rule id: " + f.Rule)
		}
		switch f.Severity {
		case SeverityCritical, SeverityHigh, SeverityMedium:
		default:
			panic("invalid severity: " + f.Severity)
		}
		switch f.Label {
		case LabelProven, LabelNotReproduced, LabelStaticWarning:
		default:
			panic("invalid label: " + f.Label)
		}
		if !isGnoFile(f.File) {
			panic("invalid file name: " + f.File)
		}
		line, err := strconv.Atoi(parts[4])
		if err != nil || line < 1 || line > 1000000 {
			panic("invalid line: " + parts[4])
		}
		f.Line = line
		if len(parts) == 6 {
			if !isIdent(parts[5]) {
				panic("invalid function name: " + parts[5])
			}
			f.Func = parts[5]
		}
		out = append(out, f)
	}
	return out
}

// isIdent accepts a Go identifier, optionally a method as Type.Method.
func isIdent(s string) bool {
	if s == "" || len(s) > 64 {
		return false
	}
	for _, part := range strings.Split(s, ".") {
		if part == "" || part[0] >= '0' && part[0] <= '9' {
			return false
		}
		for _, c := range part {
			if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_') {
				return false
			}
		}
	}
	return true
}

func isRuleID(s string) bool {
	return len(s) == 3 && s[0] == 'B' && s[1] >= '0' && s[1] <= '9' && s[2] >= '0' && s[2] <= '9'
}

func isGnoFile(s string) bool {
	if len(s) > 64 || !strings.HasSuffix(s, ".gno") || len(s) == len(".gno") {
		return false
	}
	for _, c := range s {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '.' || c == '-') {
			return false
		}
	}
	return true
}

func isHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// isToken accepts short version strings such as "0.1.0" or "master.1+f0f9c70".
func isToken(s string) bool {
	if s == "" || len(s) > 64 {
		return false
	}
	for _, c := range s {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune(".+-_", c)) {
			return false
		}
	}
	return true
}

func validReportURI(s string) bool {
	if len(s) > 200 {
		return false
	}
	rest, ok := strings.CutPrefix(s, "ipfs://")
	if !ok {
		rest, ok = strings.CutPrefix(s, "https://")
	}
	if !ok || rest == "" {
		return false
	}
	for _, c := range rest {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("./-_~", c)) {
			return false
		}
	}
	return true
}

package bouncer

import (
	"strconv"

	"gno.land/p/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/bouncer/badge/v0"
)

// Badge returns a Markdown image of pkgpath's live Bouncer badge (grade,
// score and attestation date), linked to its Passport. A realm shows it by
// adding one line to its Render:
//
//	out += bouncer.Badge("gno.land/r/<address>/myrealm")
//
// The color follows the verdict, not the grade: a package with a PROVEN
// High finding is red even at grade B.
func Badge(pkgpath string) string {
	if !validPkgPath(pkgpath) {
		return ""
	}
	link := webPath() + ":realm/" + pkgpath
	a, ok := Latest(pkgpath)
	if !ok {
		return badge.Markdown("Bouncer: not scanned", badge.SVG("bouncer", "not scanned", badge.Grey), link)
	}
	msg := a.Grade + " " + strconv.Itoa(a.Score) + " · " + date(a.Time)
	return badge.Markdown("Bouncer: grade "+a.Grade+", score "+strconv.Itoa(a.Score)+", "+verdictWords(a.Verdict),
		badge.SVG("bouncer", msg, verdictColor(a.Verdict)), link)
}

func verdictColor(v string) string {
	switch v {
	case VerdictNotRecommended:
		return badge.Red
	case VerdictReview:
		return badge.Orange
	}
	return badge.Green
}

func verdictWords(v string) string {
	switch v {
	case VerdictNotRecommended:
		return "not recommended for integration"
	case VerdictReview:
		return "review before integration"
	}
	return "no known Critical or High issues"
}

// Package bouncer is Bouncer's on-chain registry: scan requests,
// attestations, disputes and author replies, plus the reads other realms use
// (Check, Score) and the Tavern pages in Render.
//
// One realm holds all state and every write, and every logic-data type is
// declared here (security guide §3A). Writes are crossing functions that
// check cur.IsCurrent() and take the caller from cur.Previous(). Reads are
// plain functions that return values or copies, never pointers into state,
// and never take callbacks.
package bouncer

import (
	"chain"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	admin     address
	attesters = avl.NewTree() // address -> true
	// selfPath is this realm's package path, for links in Render.
	selfPath string

	// Scan requests.
	requests        = avl.NewTree() // request id -> *request
	openByRequester = avl.NewTree() // address -> request id (one open each)
	openRequests    = avl.NewTree() // request id -> true, open ones only
	requestID       seqid.ID

	// Attestations.
	records       = avl.NewTree() // pkgpath -> *record
	byAuthor      = avl.NewTree() // author address -> *avl.Tree (pkgpath -> true)
	attestationID seqid.ID
	recent        []string // pkgpaths, most recently attested first

	// Disputes.
	disputes  = avl.NewTree() // dispute id -> *dispute
	disputeID seqid.ID

	// Totals over the latest attestation of each package.
	totalFindings int
	totalProven   int
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("bouncer must be deployed by a user")
	}
	// The deployer becomes admin and the first attester. Under gno test
	// the deploying user has no address; then no admin is set, which
	// locks every admin action rather than opening it.
	if deployer := prev.Address(); deployer.IsValid() {
		admin = deployer
		attesters.Set(string(admin), true)
	}
}

// ---- admin and attesters ----

func assertAdmin(cur realm) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func assertAttester(cur realm) address {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()
	if !attesters.Has(string(caller)) {
		panic("attester only")
	}
	return caller
}

// AddAttester allows addr to post attestations.
func AddAttester(cur realm, addr address) {
	assertAdmin(cur)
	if !addr.IsValid() {
		panic("invalid address")
	}
	attesters.Set(string(addr), true)
	chain.Emit("AttesterAdded", "address", addr.String())
}

// RemoveAttester revokes addr. Its past attestations stay on record.
func RemoveAttester(cur realm, addr address) {
	assertAdmin(cur)
	if _, removed := attesters.Remove(string(addr)); !removed {
		panic("not an attester")
	}
	chain.Emit("AttesterRemoved", "address", addr.String())
}

// TransferAdmin hands the admin role to next.
func TransferAdmin(cur realm, next address) {
	assertAdmin(cur)
	if !next.IsValid() {
		panic("invalid address")
	}
	prev := admin
	admin = next
	chain.Emit("AdminTransferred", "from", prev.String(), "to", next.String())
}

// Admin returns the admin address.
func Admin() address { return admin }

// IsAttester reports whether addr may post attestations.
func IsAttester(addr address) bool { return attesters.Has(string(addr)) }

// Attesters returns the attester allowlist, sorted.
func Attesters() []address {
	out := make([]address, 0, attesters.Size())
	attesters.Iterate("", "", func(k string, _ any) bool {
		out = append(out, address(k))
		return false
	})
	return out
}

// ---- package paths ----

const maxPkgPathLen = 200

// validPkgPath accepts gno.land/r/... and gno.land/p/... paths of at least
// a namespace and a name, made of lowercase letters, digits and underscores.
func validPkgPath(p string) bool {
	if len(p) > maxPkgPathLen {
		return false
	}
	rest, ok := strings.CutPrefix(p, "gno.land/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	if len(segs) < 3 || (segs[0] != "r" && segs[0] != "p") {
		return false
	}
	for _, s := range segs[1:] {
		if s == "" {
			return false
		}
		for _, c := range s {
			if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_') {
				return false
			}
		}
	}
	return true
}

// authorOf returns the address that owns an address-namespace path
// (gno.land/r/<address>/... or gno.land/p/<address>/...). Only that address
// can deploy there, so authorship is verified by the path alone. Other
// namespaces have no verified author.
func authorOf(pkgpath string) (address, bool) {
	segs := strings.Split(pkgpath, "/")
	if len(segs) < 4 {
		return "", false
	}
	a := address(segs[2])
	if !a.IsValid() {
		return "", false
	}
	return a, true
}

package bouncer

import "strings"

// Dependency trust (CLAUDE.md §4, §8). The attester sends the package's
// import tree as a list of paths, each marked direct or indirect; the
// realm never trusts a status from outside. Each dependency's status is
// read from this registry whenever the attestation is read, so a
// dependency attested later updates its importers' score, badge and
// Check() without a re-scan:
//
//   - verified: attested, and its latest verdict has no Critical or High issue
//   - at-risk: attested, and its latest verdict has a Critical or High issue
//   - unverified: not attested here yet (never shown as a vulnerability)

// Dependency statuses.
const (
	DepVerified   = "verified"
	DepAtRisk     = "at-risk"
	DepUnverified = "unverified"
)

const maxDeps = 200

// Dep is one dependency of an attested package. Status is filled in when
// the attestation is read.
type Dep struct {
	Path   string
	Direct bool
	Status string
}

// DepStatus returns the trust status of pkgpath as a dependency.
func DepStatus(pkgpath string) string {
	rec := getRecord(pkgpath)
	if rec == nil {
		return DepUnverified
	}
	if rec.history[len(rec.history)-1].Verdict == VerdictClear {
		return DepVerified
	}
	return DepAtRisk
}

// parseDeps decodes Attest's deps argument: ";"-separated "d,<pkgpath>"
// (direct) or "i,<pkgpath>" (indirect) entries, "" for none.
func parseDeps(pkgpath, s string) []Dep {
	out := []Dep{}
	if s == "" {
		return out
	}
	seen := map[string]bool{}
	for _, e := range strings.Split(s, ";") {
		kind, path, ok := strings.Cut(e, ",")
		if !ok || (kind != "d" && kind != "i") || !validPkgPath(path) {
			panic("invalid dependency entry")
		}
		if path == pkgpath || seen[path] {
			panic("duplicate or self dependency")
		}
		seen[path] = true
		out = append(out, Dep{Path: path, Direct: kind == "d"})
		if len(out) > maxDeps {
			panic("too many dependencies")
		}
	}
	return out
}

// live returns a copy of a with dependency statuses, counts, score and
// grade as they stand now. The verdict depends on the findings only.
func live(a Attestation) Attestation {
	a = copyAttestation(a)
	d := Deps{List: make([]Dep, len(a.Deps.List))}
	for i, dep := range a.Deps.List {
		dep.Status = DepStatus(dep.Path)
		d.List[i] = dep
		switch {
		case dep.Status == DepAtRisk && dep.Direct:
			d.DirectAtRisk++
		case dep.Status == DepAtRisk:
			d.IndirectAtRisk++
		case dep.Status == DepUnverified:
			d.Unverified++
		}
	}
	a.Deps = d
	a.Score, a.Grade, _ = ScoreFor(a.Findings, d)
	return a
}

package bouncer

import (
	"chain"
	"strconv"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/seqid/v0"
)

// Size limits for finding details. The full report (ReportURI) has
// everything; the Passport shows what fits here.
const (
	maxSnippetLen  = 1500
	maxAttackLen   = 200
	maxExploitLen  = 6000
	maxEvidenceLen = 1500
	// maxDetailBytes caps the detail text of one attestation.
	maxDetailBytes = 32000
)

// AddDetail attaches the vulnerable snippet and, for a PROVEN finding, the
// exploit and its evidence to finding index of attestation id. Only the
// attester who posted the attestation may call it, once per finding: the
// details are as permanent as the attestation itself.
func AddDetail(cur realm, pkgpath string, id uint64, index int, snippet, attack, exploit, before, after string) {
	caller := assertAttester(cur)
	rec := getRecord(pkgpath)
	if rec == nil {
		panic("no attestation for this package")
	}
	ai := -1
	for i := range rec.history {
		if rec.history[i].ID == id {
			ai = i
			break
		}
	}
	if ai < 0 {
		panic("no such attestation for this package")
	}
	a := &rec.history[ai]
	if a.Attester != caller {
		panic("only the attestation's own attester can add details")
	}
	if index < 0 || index >= len(a.Findings) {
		panic("finding index out of range")
	}
	f := &a.Findings[index]
	if f.Detailed {
		panic("details already added for this finding")
	}
	checkText("snippet", snippet, maxSnippetLen)
	checkText("attack", attack, maxAttackLen)
	checkText("exploit", exploit, maxExploitLen)
	checkText("before", before, maxEvidenceLen)
	checkText("after", after, maxEvidenceLen)
	if strings.ContainsAny(attack, "\n\r") {
		panic("attack must be one line")
	}
	proofLen := len(attack) + len(exploit) + len(before) + len(after)
	if f.Label != LabelProven && proofLen > 0 {
		panic("only PROVEN findings carry an exploit and evidence")
	}
	if detailBytes(a.Findings)+len(snippet)+proofLen > maxDetailBytes {
		panic("detail limit reached for this attestation; see the full report")
	}
	f.Detailed = true
	f.Snippet = snippet
	f.Attack = attack
	f.Exploit = exploit
	f.Before = before
	f.After = after
	chain.Emit("DetailAdded",
		"id", seqid.ID(id).String(),
		"pkgpath", pkgpath,
		"index", strconv.Itoa(index))
}

func detailBytes(fs []Finding) int {
	n := 0
	for _, f := range fs {
		n += len(f.Snippet) + len(f.Attack) + len(f.Exploit) + len(f.Before) + len(f.After)
	}
	return n
}

// checkText rejects text that is too long, not UTF-8, or carries NUL or
// other control characters besides tab and newline.
func checkText(name, s string, max int) {
	if len(s) > max {
		panic(name + " is too long (max " + strconv.Itoa(max) + " bytes)")
	}
	if !utf8.ValidString(s) {
		panic(name + " must be valid UTF-8")
	}
	for _, c := range s {
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			panic(name + " contains a control character")
		}
	}
}

package bouncer

import (
	"chain"
	"chain/runtime"

	"gno.land/p/nt/seqid/v0"
)

// DisputeRecord is a challenge to an attestation, backed by a different report.
type DisputeRecord struct {
	ID            uint64
	PkgPath       string
	AttestationID uint64 // the attestation disputed (the latest at filing time)
	ReportHash    string // the disputer's report
	Note          string
	Filer         address
	Height        int64
	Resolved      bool
	Resolution    string
}

type dispute struct {
	d DisputeRecord
}

func disputeKey(id uint64) string { return seqid.ID(id).String() }

// Dispute files a challenge against the latest attestation of pkgpath,
// backed by a report with a different hash. One open dispute per filer
// per package.
func Dispute(cur realm, pkgpath, reportHash, note string) uint64 {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	filer := cur.Previous().Address()
	rec := getRecord(pkgpath)
	if rec == nil {
		panic("no attestation to dispute")
	}
	latest := rec.history[len(rec.history)-1]
	if !isHex64(reportHash) {
		panic("report hash must be 64 lowercase hex characters")
	}
	if reportHash == latest.ReportHash {
		panic("a dispute needs a report that differs from the attested one")
	}
	if note == "" || len(note) > maxNoteLen {
		panic("note must be 1 to 280 bytes")
	}
	if hasOpenDispute(pkgpath, filer) {
		panic("you already have an open dispute on this package")
	}
	id := uint64(disputeID.Next())
	disputes.Set(disputeKey(id), &dispute{d: DisputeRecord{
		ID:            id,
		PkgPath:       pkgpath,
		AttestationID: latest.ID,
		ReportHash:    reportHash,
		Note:          note,
		Filer:         filer,
		Height:        runtime.ChainHeight(),
	}})
	chain.Emit("Disputed", "id", disputeKey(id), "pkgpath", pkgpath, "filer", filer.String(), "report_hash", reportHash)
	return id
}

// ResolveDispute closes a dispute with a resolution note. Admin or an
// attester.
func ResolveDispute(cur realm, id uint64, resolution string) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()
	if caller != admin && !attesters.Has(string(caller)) {
		panic("admin or attester only")
	}
	if resolution == "" || len(resolution) > maxNoteLen {
		panic("resolution must be 1 to 280 bytes")
	}
	v := disputes.Get(disputeKey(id))
	if v == nil {
		panic("no such dispute")
	}
	d := v.(*dispute)
	if d.d.Resolved {
		panic("dispute already resolved")
	}
	d.d.Resolved = true
	d.d.Resolution = resolution
	chain.Emit("DisputeResolved", "id", disputeKey(id), "pkgpath", d.d.PkgPath)
}

func hasOpenDispute(pkgpath string, filer address) bool {
	found := false
	disputes.Iterate("", "", func(_ string, v any) bool {
		d := v.(*dispute).d
		if d.PkgPath == pkgpath && !d.Resolved && (filer == "" || d.Filer == filer) {
			found = true
		}
		return found
	})
	return found
}

// DisputesFor returns copies of every dispute on pkgpath, oldest first.
func DisputesFor(pkgpath string) []DisputeRecord {
	out := []DisputeRecord{}
	disputes.Iterate("", "", func(_ string, v any) bool {
		if d := v.(*dispute).d; d.PkgPath == pkgpath {
			out = append(out, d)
		}
		return false
	})
	return out
}

// Reply lets the author of an address-namespace package answer its
// Passport and, optionally, name the fixed version (successor) in the same
// namespace.
func Reply(cur realm, pkgpath, note, successor string) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()
	author, ok := authorOf(pkgpath)
	if !ok {
		panic("only address-namespace packages have a verified author")
	}
	if caller != author {
		panic("author only")
	}
	rec := getRecord(pkgpath)
	if rec == nil {
		panic("no attestation to reply to")
	}
	if note == "" || len(note) > maxNoteLen {
		panic("note must be 1 to 280 bytes")
	}
	if successor != "" {
		if !validPkgPath(successor) || successor == pkgpath {
			panic("invalid successor path")
		}
		if sa, ok := authorOf(successor); !ok || sa != author {
			panic("the successor must be in the same address namespace")
		}
	}
	if len(rec.replies) >= maxReplies {
		panic("reply limit reached for this package")
	}
	rec.replies = append(rec.replies, AuthorReply{Author: caller, Note: note, Successor: successor, Height: runtime.ChainHeight()})
	chain.Emit("Replied", "pkgpath", pkgpath, "author", caller.String(), "successor", successor)
}

package bouncer

// Guidance is the fix guidance for one rule. It is written once per rule,
// so every Passport says the same thing and it costs nothing per finding.
type Guidance struct {
	Title   string // short name of the bug class
	Guide   string // security guide sections
	Meaning string // what the finding means
	Danger  string // why it is dangerous
	Fix     string // what to change
	Example string // the fixed code, Gno
	Why     string // why the fix works
}

// RuleGuidance returns the guidance for rule, and false for a rule this
// realm has no guidance for yet.
func RuleGuidance(rule string) (Guidance, bool) {
	switch rule {
	case "B01":
		return Guidance{
			Title:   "Getter returns a pointer into state",
			Guide:   "§5.1, §5.1a",
			Meaning: "An exported function hands out a pointer to the realm's own state, and the pointed-to type has an exported method that changes it.",
			Danger:  "Readonly taint stops another realm writing fields through the pointer, but not calling methods on it. Any realm can call the mutating method, and the write commits with this realm's authority: balances, owners and counters change with no check at all.",
			Fix:     "Return copies or plain values, never a pointer into package state. Keep mutating methods unexported and reach them only through crossing functions that check the caller.",
			Example: "type Entry struct {\n\tAddr    address\n\tBalance int64\n}\n\n// Balances returns a copy of the ledger.\nfunc Balances() []Entry {\n\tout := []Entry{}\n\tledger.Iterate(\"\", \"\", func(k string, v any) bool {\n\t\tout = append(out, Entry{address(k), v.(int64)})\n\t\treturn false\n\t})\n\treturn out\n}",
			Why:     "A copy has no path back into the realm's storage, so nothing a caller does to it can reach the real state.",
		}, true
	case "B05":
		return Guidance{
			Title:   "IsUser() guards an OriginSend payment",
			Guide:   "§5.5",
			Meaning: "A payment is credited from `OriginSend()` behind an `IsUser()` check.",
			Danger:  "`IsUser()` is also true for a `maketx run` script. In that case the coins in `OriginSend()` go to the script's own realm, not to this one, so the caller is credited for money this realm never received and can withdraw other users' funds.",
			Fix:     "Accept payments only from a direct call: check `cur.Previous().IsUserCall()` before reading `OriginSend()`.",
			Example: "func Deposit(cur realm) {\n\tif !cur.IsCurrent() {\n\t\tpanic(\"not current\")\n\t}\n\tif !cur.Previous().IsUserCall() {\n\t\tpanic(\"deposit with maketx call\")\n\t}\n\tamount := unsafe.OriginSend().AmountOf(\"ugnot\")\n\t// credit amount\n}",
			Why:     "`IsUserCall()` is true only for a direct `maketx call`, where the sent coins are guaranteed to land at this realm before it runs.",
		}, true
	case "B03":
		return Guidance{
			Title:   "Caller-supplied callback runs with the realm's authority",
			Guide:   "§3C, §5.3",
			Meaning: "The realm calls a function value its caller passed in, and hands it a map, slice, pointer or other reference.",
			Danger:  "A top-level function from a /p/ package does not switch realms when called, so inside this call it runs as this realm and can write whatever it is handed, such as the live balances map.",
			Fix:     "Do not call caller-supplied functions. If you must, type the callback with a type declared in this realm, which /p/ code cannot name, and hand it a copy.",
			Example: "type Entry struct {\n\tPlayer string\n\tPoints int64\n}\n\nfunc Report(cur realm, format func(rows []Entry) string) string {\n\tif !cur.IsCurrent() {\n\t\tpanic(\"not current\")\n\t}\n\treturn format(copyRows())\n}",
			Why:     "A /p/ package cannot import a realm, so it cannot supply a func([]Entry); a function from another realm, or a closure, runs under its own realm and cannot write this realm's data.",
		}, true
	case "B09":
		return Guidance{
			Title:   "External Teller used without IsCanonicalTeller",
			Guide:   "§5.4",
			Meaning: "The realm calls a GRC20 Teller that a caller passed in, without checking it.",
			Danger:  "A fake Teller can report transfers that never happened.",
			Fix:     "Check `grc20.IsCanonicalTeller(t)` before using a Teller from a caller, or look the token up yourself.",
			Example: "",
			Why:     "A canonical Teller is the token's own, so its transfers are real.",
		}, true
	}
	return Guidance{}, false
}

package bouncer

import "gno.land/p/nt/avl/v0"

// Reads for other realms and for clients. All are plain (non-crossing)
// functions that return values or fresh copies: no pointer into state ever
// leaves this realm, and no caller-supplied function is ever invoked.

// copyAttestation returns a deep copy (the Findings slice is copied too).
func copyAttestation(a Attestation) Attestation {
	fs := make([]Finding, len(a.Findings))
	copy(fs, a.Findings)
	a.Findings = fs
	ds := make([]Dep, len(a.Deps.List))
	copy(ds, a.Deps.List)
	a.Deps.List = ds
	return a
}

// Latest returns the newest attestation for pkgpath.
func Latest(pkgpath string) (Attestation, bool) {
	rec := getRecord(pkgpath)
	if rec == nil {
		return Attestation{}, false
	}
	return live(rec.history[len(rec.history)-1]), true
}

// History returns every attestation for pkgpath, oldest first, with scores
// that use the current dependency statuses (like Latest).
func History(pkgpath string) []Attestation {
	rec := getRecord(pkgpath)
	out := []Attestation{}
	if rec == nil {
		return out
	}
	for _, a := range rec.history {
		out = append(out, live(a))
	}
	return out
}

// Replies returns the author's replies on pkgpath, oldest first.
func Replies(pkgpath string) []AuthorReply {
	rec := getRecord(pkgpath)
	out := []AuthorReply{}
	if rec != nil {
		out = append(out, rec.replies...)
	}
	return out
}

// Score returns the latest score for pkgpath.
func Score(pkgpath string) (int, bool) {
	a, ok := Latest(pkgpath)
	return a.Score, ok
}

// ByAuthor returns the attested packages in addr's namespace, sorted.
func ByAuthor(addr address) []string {
	out := []string{}
	v := byAuthor.Get(string(addr))
	if v == nil {
		return out
	}
	v.(*avl.Tree).Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// Policy is an integration policy for Check. No policy accepts a red
// verdict: a PROVEN Critical or High finding fails every policy, and there
// is no option to allow it. The zero value is the most conservative: no
// PROVEN findings at all, no open disputes, any score.
type Policy struct {
	MinScore int
	// AllowProvenMedium permits PROVEN medium findings (which do not make
	// the verdict red).
	AllowProvenMedium bool
	// RequireVerifiedDeps forbids at-risk and unverified dependencies.
	RequireVerifiedDeps bool
	AllowOpenDisputes   bool
}

// Strict: score 90 or more, no PROVEN findings, every dependency verified,
// no open disputes.
func Strict() Policy {
	return Policy{MinScore: 90, RequireVerifiedDeps: true}
}

// Standard: score 75 or more and no PROVEN Critical or High finding.
// Open disputes are tolerated.
func Standard() Policy {
	return Policy{MinScore: 75, AllowProvenMedium: true, AllowOpenDisputes: true}
}

// Custom starts a policy at minScore that is otherwise as strict as the
// zero value; loosen it with the With methods:
//
//	bouncer.Custom(60).WithProvenMedium().WithOpenDisputes()
//
// Other realms must build policies this way: the VM refuses to allocate a
// Bouncer type in a foreign realm, so a bouncer.Policy{...} literal written
// in another realm panics.
func Custom(minScore int) Policy { return Policy{MinScore: minScore} }

// WithProvenMedium allows PROVEN medium findings.
func (p Policy) WithProvenMedium() Policy { p.AllowProvenMedium = true; return p }

// WithVerifiedDeps requires every dependency to be verified.
func (p Policy) WithVerifiedDeps() Policy { p.RequireVerifiedDeps = true; return p }

// WithOpenDisputes allows open disputes.
func (p Policy) WithOpenDisputes() Policy { p.AllowOpenDisputes = true; return p }

// Check reports whether the latest attestation of pkgpath satisfies p.
// An unattested package never passes.
func Check(pkgpath string, p Policy) bool {
	a, ok := Latest(pkgpath)
	if !ok || !allows(p, a.Score, a.Findings, a.Deps) {
		return false
	}
	if !p.AllowOpenDisputes && hasOpenDispute(pkgpath, "") {
		return false
	}
	return true
}

// allows is the policy decision on a score, findings and dependency counts
// (disputes aside). bouncer gate's Go copy (internal/score) must decide the
// same; TestMatchesRealm checks it.
func allows(p Policy, score int, fs []Finding, d Deps) bool {
	if verdictOf(fs) == VerdictNotRecommended {
		return false // a red verdict never passes
	}
	if score < p.MinScore {
		return false
	}
	for _, f := range fs {
		if f.Label == LabelProven && !p.AllowProvenMedium {
			return false // only medium can be PROVEN here
		}
	}
	if p.RequireVerifiedDeps && (d.DirectAtRisk > 0 || d.IndirectAtRisk > 0 || d.Unverified > 0) {
		return false
	}
	return true
}

package bouncer

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Render serves the Tavern pages:
//
//	""                 Noticeboard
//	"realm/<pkgpath>"  Passport
//	"hunters"          link to the Training Grounds hunters board
func Render(path string) string {
	if pkgpath, ok := strings.CutPrefix(path, "realm/"); ok {
		return renderPassport(pkgpath)
	}
	if path == "" {
		return renderNoticeboard()
	}
	if path == "hunters" {
		return "# Hunters\n\nThe hunters board lives with the Training Grounds, which this registry does not import: " +
			"a deliberately vulnerable target must never count as one of Bouncer's own dependencies.\n\n" +
			"[Open the hunters board](" + groundsWebPath() + ")\n"
	}
	return "# Not found\n\n[Back to the noticeboard](" + webPath() + ")\n"
}

// groundsWebPath is the Training Grounds' gnoweb path: "grounds" next to
// this realm's /vN, in the same namespace.
func groundsWebPath() string {
	p := webPath()
	return p[:strings.LastIndex(p, "/")] + "/grounds"
}

// webPath is this realm's gnoweb URL path ("/r/...").
func webPath() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

// passportLink links to pkgpath's Passport. pkgpath is a validated path
// (lowercase letters, digits, underscores and slashes), so it is URL-safe.
func passportLink(pkgpath string) string {
	return "[" + sanitize.InlineCode(pkgpath) + "](" + webPath() + ":realm/" + pkgpath + ")"
}

func verdictText(v string) string {
	switch v {
	case VerdictNotRecommended:
		return "🔴 Not recommended for integration"
	case VerdictReview:
		return "🟠 Review before integration"
	}
	return "🟢 No known Critical or High issues"
}

func date(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02")
}

func renderNoticeboard() string {
	var b strings.Builder
	b.WriteString("# Bouncer\n\n**No exploit, no claim.** Bouncer checks Gno realms against the Gno security guide, proves serious bugs with a working attacker realm, and records the verdict here.\n\n")
	b.WriteString("| Passports | Findings | PROVEN | Open requests |\n| --- | --- | --- | --- |\n")
	b.WriteString("| " + strconv.Itoa(records.Size()) + " | " + strconv.Itoa(totalFindings) + " | " + strconv.Itoa(totalProven) + " | " + strconv.Itoa(openByRequester.Size()) + " |\n\n")

	b.WriteString("## Recent Passports\n\n")
	if len(recent) == 0 {
		b.WriteString("No packages attested yet.\n\n")
	} else {
		b.WriteString("| Package | Score | Grade | Verdict |\n| --- | --- | --- | --- |\n")
		for _, p := range recent {
			a, _ := Latest(p)
			b.WriteString("| " + passportLink(p) + " | " + strconv.Itoa(a.Score) + " | " + a.Grade + " | " + verdictText(a.Verdict) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Training Grounds\n\nPractice targets with a real bug each. Break one, claim it, and land on the [hunters board](" + groundsWebPath() + ").\n\n")
	b.WriteString("## Request a scan\n\nOne open request per address. The scanner bot picks it up, scans and proves, then posts the result.\n\n")
	b.WriteString("<gno-form exec=\"RequestScan\">\n<gno-input name=\"pkgpath\" placeholder=\"gno.land/r/<address>/myrealm\" />\n</gno-form>\n\n")
	b.WriteString("_" + Disclaimer + "_\n")
	return b.String()
}

func renderPassport(pkgpath string) string {
	if !validPkgPath(pkgpath) {
		return "# Not found\n\nThat is not a valid package path.\n"
	}
	rec := getRecord(pkgpath)
	var b strings.Builder
	b.WriteString("# Passport: " + sanitize.InlineCode(pkgpath) + "\n\n")
	if rec == nil {
		b.WriteString("Bouncer has not attested this package yet. [Request a scan](" + webPath() + ").\n")
		return b.String()
	}
	a, _ := Latest(pkgpath)

	b.WriteString("## " + strconv.Itoa(a.Score) + " / 100 · Grade " + a.Grade + " · " + verdictText(a.Verdict) + "\n\n")
	b.WriteString(Badge(pkgpath) + "\n\n")
	b.WriteString("_" + Disclaimer + "_\n\n")
	if successor := latestSuccessor(rec); successor != "" {
		b.WriteString("The author points to a newer version: " + passportLink(successor) + "\n\n")
	}

	b.WriteString("## Findings\n\n")
	if len(a.Findings) == 0 {
		b.WriteString("No findings with the current rules.\n\n")
	} else {
		b.WriteString("| # | Rule | Severity | Label | Location |\n| --- | --- | --- | --- | --- |\n")
		for i, f := range a.Findings {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + f.Rule + " | " + f.Severity + " | **" + f.Label + "** | " + sanitize.InlineCode(location(f)) + " |\n")
		}
		b.WriteString("\n")
		for i, f := range a.Findings {
			renderFinding(&b, i+1, f)
		}
	}

	b.WriteString("## Attestation\n\n| | |\n| --- | --- |\n")
	row := func(k, v string) { b.WriteString("| " + k + " | " + v + " |\n") }
	row("Attested", date(a.Time)+" (block "+strconv.FormatInt(a.Height, 10)+")")
	row("Attester", sanitize.InlineCode(a.Attester.String()))
	row("Source hash", sanitize.InlineCode(a.SourceHash))
	row("Scanner", sanitize.InlineCode(a.ScannerVersion)+", rule set "+sanitize.InlineCode(a.RulesetHash[:12]))
	row("Gno toolchain", sanitize.InlineCode(a.Toolchain))
	if u := reportURL(a.ReportURI); u != "" {
		row("Full report", "[report]("+u+"), hash "+sanitize.InlineCode(a.ReportHash[:12]))
	}
	b.WriteString("\n")
	renderDeps(&b, a.Deps)

	if len(rec.replies) > 0 {
		b.WriteString("## Author replies\n\n")
		for _, r := range rec.replies {
			b.WriteString("- " + sanitize.InlineText(r.Note))
			if r.Successor != "" {
				b.WriteString(" (fixed version: " + passportLink(r.Successor) + ")")
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	if ds := DisputesFor(pkgpath); len(ds) > 0 {
		b.WriteString("## Disputes\n\n| Filer | Report | Note | Status |\n| --- | --- | --- | --- |\n")
		for _, d := range ds {
			status := "open"
			if d.Resolved {
				status = "resolved: " + sanitize.TableCell(d.Resolution)
			}
			b.WriteString("| " + sanitize.InlineCode(d.Filer.String()) + " | " + sanitize.InlineCode(d.ReportHash[:12]) + " | " + sanitize.TableCell(d.Note) + " | " + status + " |\n")
		}
		b.WriteString("\n")
	}

	renderVersions(&b, pkgpath)

	b.WriteString("## Badge\n\nShow this live badge on your realm's page by adding one line to its `Render`:\n\n")
	b.WriteString(sanitize.LanguageCodeBlock("go", "out += bouncer.Badge(\""+pkgpath+"\") // import \""+selfPath+"\"") + "\n\n")

	if len(rec.history) > 1 {
		b.WriteString("## Scans of this version\n\n| Date | Score | Grade | Findings | Change |\n| --- | --- | --- | --- | --- |\n")
		for i := len(rec.history) - 1; i >= 0; i-- {
			h := live(rec.history[i])
			change := "first scan"
			if i > 0 {
				change = diffFindings(rec.history[i-1].Findings, h.Findings)
			}
			b.WriteString("| " + date(h.Time) + " | " + strconv.Itoa(h.Score) + " | " + h.Grade + " | " + strconv.Itoa(len(h.Findings)) + " | " + change + " |\n")
		}
	}
	return b.String()
}

// location is "file:line in Func".
func location(f Finding) string {
	loc := f.File + ":" + strconv.Itoa(f.Line)
	if f.Func != "" {
		loc += " in " + f.Func + "()"
	}
	return loc
}

// renderFinding writes one finding: what it means, why it is dangerous, the
// vulnerable code, the fix and why it works, and the exploit if PROVEN.
func renderFinding(b *strings.Builder, n int, f Finding) {
	g, known := RuleGuidance(f.Rule)
	title := g.Title
	if !known {
		title = "see the full report"
	}
	b.WriteString("### " + strconv.Itoa(n) + ". " + f.Rule + ": " + title + "\n\n")
	b.WriteString("**" + f.Label + "** · " + f.Severity + " · " + sanitize.InlineCode(location(f)))
	if g.Guide != "" {
		b.WriteString(" · security guide " + g.Guide)
	}
	b.WriteString("\n\n")
	if known {
		b.WriteString("**What it means.** " + g.Meaning + "\n\n")
		b.WriteString("**Why it is dangerous.** " + g.Danger + "\n\n")
	}
	if f.Snippet != "" {
		b.WriteString("**Vulnerable code** (" + sanitize.InlineCode(f.File) + "):\n\n" + sanitize.LanguageCodeBlock("go", f.Snippet) + "\n\n")
	}
	if known {
		b.WriteString("**Fix.** " + g.Fix + "\n\n")
		if g.Example != "" {
			b.WriteString(sanitize.LanguageCodeBlock("go", g.Example) + "\n\n")
		}
		b.WriteString("**Why it works.** " + g.Why + "\n\n")
	}
	switch f.Label {
	case LabelProven:
		b.WriteString("**Proof.** Bouncer wrote an attacker realm and ran it against this exact source")
		if f.Attack != "" {
			b.WriteString(": " + sanitize.InlineText(f.Attack))
		}
		b.WriteString(".\n\n")
		if f.Exploit != "" {
			b.WriteString("Attacker realm (lines that print Bouncer's evidence markers are left out; the full report has the exact source):\n\n" + sanitize.LanguageCodeBlock("go", f.Exploit) + "\n\n")
		}
		if f.Before != "" || f.After != "" {
			b.WriteString("Only the lines that changed are shown; `...` marks lines left out. The full report has the complete output.\n\n")
			b.WriteString("<gno-columns>\n\n**Before the attack**\n\n" + sanitize.CodeBlock(f.Before) +
				"\n\n<gno-columns-sep />\n\n**After the attack**\n\n" + sanitize.CodeBlock(f.After) + "\n\n</gno-columns>\n\n")
		}
	case LabelNotReproduced:
		b.WriteString("**Not reproduced.** Bouncer's generated exploit did not land. This stays a warning: it is not evidence that the code is safe.\n\n")
	default:
		b.WriteString("**Static warning.** The pattern matched, and Bouncer has no exploit generator for this rule yet.\n\n")
	}
}

// renderVersions lists every attested version of the package, newest first,
// with what changed from the version before it.
func renderVersions(b *strings.Builder, pkgpath string) {
	vs := Versions(pkgpath)
	if len(vs) < 2 {
		return
	}
	b.WriteString("## Versions\n\nPackages on Gno cannot be overwritten, so each fix ships at a new path. Latest scan of each version:\n\n")
	b.WriteString("| Version | Score | Grade | Verdict | Change from the version before |\n| --- | --- | --- | --- | --- |\n")
	for i := len(vs) - 1; i >= 0; i-- {
		cur := getRecord(vs[i]).history
		a := live(cur[len(cur)-1])
		change := "first version scanned"
		if i > 0 {
			prev := getRecord(vs[i-1]).history
			change = diffFindings(prev[len(prev)-1].Findings, a.Findings)
		}
		name := passportLink(vs[i])
		if vs[i] == pkgpath {
			name = "**" + name + "** (this page)"
		}
		b.WriteString("| " + name + " | " + strconv.Itoa(a.Score) + " | " + a.Grade + " | " + verdictText(a.Verdict) + " | " + change + " |\n")
	}
	b.WriteString("\n")
}

// latestSuccessor returns the newest successor an author named.
func latestSuccessor(rec *record) string {
	for i := len(rec.replies) - 1; i >= 0; i-- {
		if rec.replies[i].Successor != "" {
			return rec.replies[i].Successor
		}
	}
	return ""
}

// diffFindings describes which rules disappeared or appeared between two
// scans. A rule that was PROVEN and is gone is "resolved"; a warning that is
// gone is only "no longer detected", since a missing warning proves nothing.
func diffFindings(prev, next []Finding) string {
	had, has := map[string]bool{}, map[string]bool{}
	proven := map[string]bool{}
	for _, f := range prev {
		had[f.Rule] = true
		if f.Label == LabelProven {
			proven[f.Rule] = true
		}
	}
	for _, f := range next {
		has[f.Rule] = true
	}
	var parts []string
	done := map[string]bool{}
	for _, f := range prev {
		if has[f.Rule] || done[f.Rule] {
			continue
		}
		done[f.Rule] = true
		if proven[f.Rule] {
			parts = append(parts, f.Rule+" resolved")
		} else {
			parts = append(parts, f.Rule+" no longer detected")
		}
	}
	for _, f := range next {
		if had[f.Rule] || done[f.Rule] {
			continue
		}
		done[f.Rule] = true
		parts = append(parts, f.Rule+" new")
	}
	if len(parts) == 0 {
		return "no rule changes"
	}
	return strings.Join(parts, ", ")
}

// reportURL turns a stored report URI into a safe link target. IPFS URIs
// go through the IPFS gateway gnoweb itself uses, since links need https.
func reportURL(uri string) string {
	if cid, ok := strings.CutPrefix(uri, "ipfs://"); ok {
		uri = "https://ipfs.filebase.io/ipfs/" + cid
	}
	return sanitize.URL(uri)
}

// renderDeps shows dependency trust as it stands now, direct first.
func renderDeps(b *strings.Builder, d Deps) {
	b.WriteString("## Dependencies\n\n")
	if len(d.List) == 0 {
		b.WriteString("No `gno.land` imports.\n\n")
		return
	}
	b.WriteString(strconv.Itoa(d.DirectAtRisk) + " direct at risk, " + strconv.Itoa(d.IndirectAtRisk) + " indirect at risk, " +
		strconv.Itoa(d.Unverified) + " unverified. A dependency at risk does not mean this package is exploitable; " +
		"an unverified one has not been scanned yet, which is not a finding.\n\n")
	b.WriteString("| Dependency | Import | Status |\n| --- | --- | --- |\n")
	for _, direct := range []bool{true, false} {
		for _, dep := range d.List {
			if dep.Direct != direct {
				continue
			}
			kind := "indirect"
			if direct {
				kind = "direct"
			}
			b.WriteString("| " + passportLink(dep.Path) + " | " + kind + " | " + depStatusText(dep.Status) + " |\n")
		}
	}
	b.WriteString("\n")
}

func depStatusText(s string) string {
	switch s {
	case DepVerified:
		return "🟢 Verified"
	case DepAtRisk:
		return "🔴 At risk"
	}
	return "⚪ Unverified"
}

package bouncer

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/seqid/v0"
)

// Request is a scan request, as returned by reads.
type Request struct {
	ID        uint64
	PkgPath   string
	Requester address
	Height    int64
	// Status is "open", "attested", "cancelled" or "closed".
	Status string
	// Note explains a closed request.
	Note string
}

type request struct {
	r Request
}

func requestKey(id uint64) string { return seqid.ID(id).String() }

// RequestScan asks the scanner bot to scan pkgpath. Each address may have
// one open request at a time.
func RequestScan(cur realm, pkgpath string) uint64 {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	if !validPkgPath(pkgpath) {
		panic("invalid package path")
	}
	caller := cur.Previous().Address()
	if openByRequester.Has(string(caller)) {
		panic("you already have an open scan request")
	}
	id := uint64(requestID.Next())
	requests.Set(requestKey(id), &request{r: Request{
		ID:        id,
		PkgPath:   pkgpath,
		Requester: caller,
		Height:    runtime.ChainHeight(),
		Status:    "open",
	}})
	openByRequester.Set(string(caller), id)
	openRequests.Set(requestKey(id), true)
	chain.Emit("ScanRequested", "id", requestKey(id), "pkgpath", pkgpath, "requester", caller.String())
	return id
}

// CancelRequest withdraws the caller's open request.
func CancelRequest(cur realm) {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()
	v := openByRequester.Get(string(caller))
	if v == nil {
		panic("no open scan request")
	}
	finishRequest(v.(uint64), "cancelled", "")
}

// CloseRequest lets an attester close a request it cannot serve, such as a
// package that does not exist.
func CloseRequest(cur realm, id uint64, note string) {
	assertAttester(cur)
	if len(note) > maxNoteLen {
		panic("note too long")
	}
	v := requests.Get(requestKey(id))
	if v == nil || v.(*request).r.Status != "open" {
		panic("no open request with that id")
	}
	finishRequest(id, "closed", note)
}

func finishRequest(id uint64, status, note string) {
	rq := requests.Get(requestKey(id)).(*request)
	rq.r.Status = status
	rq.r.Note = note
	openByRequester.Remove(string(rq.r.Requester))
	openRequests.Remove(requestKey(id))
	chain.Emit("ScanRequestFinished", "id", requestKey(id), "pkgpath", rq.r.PkgPath, "status", status)
}

// closeRequestsFor marks every open request for pkgpath as attested.
func closeRequestsFor(pkgpath string) {
	var ids []uint64
	openRequests.Iterate("", "", func(k string, _ any) bool {
		r := requests.Get(k).(*request).r
		if r.PkgPath == pkgpath {
			ids = append(ids, r.ID)
		}
		return false
	})
	for _, id := range ids {
		finishRequest(id, "attested", "")
	}
}

// GetRequest returns a copy of request id.
func GetRequest(id uint64) (Request, bool) {
	v := requests.Get(requestKey(id))
	if v == nil {
		return Request{}, false
	}
	return v.(*request).r, true
}

// OpenRequests returns up to limit open requests, oldest first, for the
// scanner bot.
func OpenRequests(limit int) []Request {
	out := []Request{}
	if limit <= 0 {
		return out
	}
	// seqid keys sort in ID order.
	openRequests.Iterate("", "", func(k string, _ any) bool {
		out = append(out, requests.Get(k).(*request).r)
		return len(out) >= limit
	})
	return out
}

// OpenRequestsText is OpenRequests for the scanner bot, as plain text: one
// "id pkgpath" line per open request, oldest first. Package paths never
// contain spaces or newlines.
func OpenRequestsText(limit int) string {
	var b strings.Builder
	for _, r := range OpenRequests(limit) {
		b.WriteString(strconv.FormatUint(r.ID, 10) + " " + r.PkgPath + "\n")
	}
	return b.String()
}

// LatestHashes returns "<source hash> <rule-set hash> <scanner version>" of
// pkgpath's latest attestation, or "" if there is none, so the bot can skip
// code it already scanned with the same rules and prover.
func LatestHashes(pkgpath string) string {
	a, ok := Latest(pkgpath)
	if !ok {
		return ""
	}
	return a.SourceHash + " " + a.RulesetHash + " " + a.ScannerVersion
}

// APIVersion is the registry's interface version, so the bot can tell what
// Attest takes. 2: Attest takes the dependency list (deps.gno);
// LatestHashes includes the scanner version.
func APIVersion() int { return 2 }

package bouncer

// The public, deterministic scoring formula (CLAUDE.md §8). The realm
// computes score, grade and verdict itself from the attested findings and
// dependency counts, so an attestation can never carry a score that
// contradicts its own findings.

// Labels, exactly as the prover writes them.
const (
	LabelProven        = "PROVEN"
	LabelNotReproduced = "NOT REPRODUCED"
	LabelStaticWarning = "STATIC WARNING"
)

// Severities.
const (
	SeverityCritical = "critical"
	SeverityHigh     = "high"
	SeverityMedium   = "medium"
)

// Verdicts.
const (
	VerdictNotRecommended = "not-recommended" // any PROVEN Critical or High
	VerdictReview         = "review"          // any Critical or High warning
	VerdictClear          = "clear"           // no known Critical or High issues
)

// Disclaimer is shown on every Passport.
const Disclaimer = "A high score means Bouncer found no issues with its current rules. It is not a guarantee of safety."

// Deps is an attestation's dependency trust: the list as attested, and the
// counts that the score uses. Counts and statuses are computed when the
// attestation is read (see live).
type Deps struct {
	DirectAtRisk   int
	IndirectAtRisk int
	Unverified     int
	List           []Dep
}

// computeScore applies the formula: start at 100, deduct, floor at 0.
func computeScore(fs []Finding, d Deps) int {
	score := 100
	for _, f := range fs {
		proven := f.Label == LabelProven
		switch {
		case proven && f.Severity == SeverityCritical:
			score -= 40
		case proven && f.Severity == SeverityHigh:
			score -= 25
		case f.Severity == SeverityCritical:
			score -= 15
		case f.Severity == SeverityHigh:
			score -= 10
		default: // medium, proven or not
			score -= 5
		}
	}
	score -= 10 * d.DirectAtRisk
	score -= 5 * d.IndirectAtRisk
	unverified := 2 * d.Unverified
	if unverified > 10 {
		unverified = 10
	}
	score -= unverified
	if score < 0 {
		score = 0
	}
	return score
}

func gradeOf(score int) string {
	switch {
	case score >= 90:
		return "A"
	case score >= 75:
		return "B"
	case score >= 60:
		return "C"
	case score >= 40:
		return "D"
	}
	return "F"
}

func verdictOf(fs []Finding) string {
	verdict := VerdictClear
	for _, f := range fs {
		if f.Severity != SeverityCritical && f.Severity != SeverityHigh {
			continue
		}
		if f.Label == LabelProven {
			return VerdictNotRecommended
		}
		verdict = VerdictReview
	}
	return verdict
}

// ScoreFor exposes the formula, so anyone can check an attestation or score
// a report before attesting it.
func ScoreFor(fs []Finding, d Deps) (score int, grade, verdict string) {
	score = computeScore(fs, d)
	return score, gradeOf(score), verdictOf(fs)
}

package bouncer

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Versions group the attested paths of one package: gno.land/r/x/vault/v1,
// .../v2 and so on. Packages on Gno cannot be overwritten, so a fix ships
// at a new /vN path, and the Passport shows every version side by side.

var families = avl.NewTree() // base path -> *avl.Tree (zero-padded N -> pkgpath)

// familyOf splits ".../name/vN" into its base and N.
func familyOf(pkgpath string) (base string, n int, ok bool) {
	i := strings.LastIndex(pkgpath, "/")
	if i < 0 {
		return "", 0, false
	}
	last := pkgpath[i+1:]
	if len(last) < 2 || len(last) > 7 || last[0] != 'v' {
		return "", 0, false
	}
	n, err := strconv.Atoi(last[1:])
	if err != nil || n < 0 || last[1:] != strconv.Itoa(n) {
		return "", 0, false
	}
	base = pkgpath[:i]
	if strings.Count(base, "/") < 2 { // need gno.land/r/<ns>/...
		return "", 0, false
	}
	return base, n, true
}

func versionKey(n int) string {
	s := strconv.Itoa(n)
	return strings.Repeat("0", 6-len(s)) + s
}

func addToFamily(pkgpath string) {
	base, n, ok := familyOf(pkgpath)
	if !ok {
		return
	}
	var t *avl.Tree
	if v := families.Get(base); v != nil {
		t = v.(*avl.Tree)
	} else {
		t = avl.NewTree()
		families.Set(base, t)
	}
	t.Set(versionKey(n), pkgpath)
}

// Versions returns every attested version of pkgpath's package, oldest
// first. A path without a /vN suffix is its own only version.
func Versions(pkgpath string) []string {
	out := []string{}
	base, _, ok := familyOf(pkgpath)
	if !ok {
		if getRecord(pkgpath) != nil {
			out = append(out, pkgpath)
		}
		return out
	}
	v := families.Get(base)
	if v == nil {
		return out
	}
	v.(*avl.Tree).Iterate("", "", func(_ string, p any) bool {
		out = append(out, p.(string))
		return false
	})
	return out
}

