// Render shows the realm's pages on gnoweb:
//
//	""         home: how it works + all tables
//	"table/N"  a table: members, leaderboard, bets
//	"bet/N"    a bet: players, reports, votes, payouts, actions
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 2 {
		if _, err := strconv.Atoi(parts[1]); err == nil {
			switch parts[0] {
			case "table":
				if v := tables.Get(parts[1]); v != nil {
					return renderTable(v.(*Table))
				}
				return "# Table not found\n\n[Back home](" + home() + ")"
			case "bet":
				if v := bets.Get(parts[1]); v != nil {
					return renderBet(v.(*Bet))
				}
				return "# Bet not found\n\n[Back home](" + home() + ")"
			case "pool":
				if v := pools.Get(parts[1]); v != nil {
					return renderPool(v.(*Pool))
				}
				return "# Group bet not found\n\n[Back home](" + home() + ")"
			}
		}
	}
	return renderHome()
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# 🍺 Tavern Wagers\n\n")
	sb.WriteString("**Bet on anything with your friends. The money's locked upfront, neutral judges call it, and the winner gets paid automatically. No more \"I'll pay you later.\"**\n\n")
	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Open a table** and invite your friends.\n")
	sb.WriteString("2. **Make a bet** against a friend. Both players lock the same stake + a 10% honesty bond.\n")
	sb.WriteString("3. **Play** (chess, FIFA, D&D, anything).\n")
	sb.WriteString("4. **Both players report the result.** If you agree, you're paid instantly and get your bonds back.\n")
	sb.WriteString("5. **Disagree?** Everyone else at the table becomes a judge. They have no money in it, so they have no reason to lie. A strict majority decides.\n")
	sb.WriteString("6. **Lying costs you.** The player who loses the vote forfeits their bond: half to the honest player, half to the judges. Judges also split a 1% fee for showing up.\n")
	sb.WriteString("7. **No majority before the deadline?** Everyone is refunded in full.\n\n")
	sb.WriteString("The realm keeps nothing. Every coin that goes in comes back out to players and judges.\n\n")
	sb.WriteString("[➕ Open a new table](" + call("CreateTable") + ")\n\n")

	sb.WriteString(count(tables.Size(), "table") + " · " + count(bets.Size(), "bet") + " · " +
		count(totalSettled, "settled bet") + " · **" + gnot(totalLocked, false) + "** locked all time\n\n")

	sb.WriteString("## Tables\n\n")
	if tables.Size() == 0 {
		sb.WriteString("_No tables yet. Be the first._\n")
		return sb.String()
	}
	sb.WriteString("| Table | Members | Bets | Owner |\n|---|---|---|---|\n")
	shown := 0
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		shown++
		if shown > 30 {
			return true // newest 30 only
		}
		t := v.(*Table)
		sb.WriteString("| [" + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ") | " +
			strconv.Itoa(len(t.Members)) + " | " + strconv.Itoa(len(t.BetIDs)) + " | " + who(t, t.Owner) + " |\n")
		return false
	})
	return sb.String()
}

func renderTable(t *Table) string {
	var sb strings.Builder
	id := strconv.Itoa(t.ID)
	sb.WriteString("[← All tables](" + home() + ")\n\n")
	sb.WriteString("# 🍺 " + escape(t.Name) + "\n\n")
	sb.WriteString("Table #" + id + " · owner " + who(t, t.Owner) + " · " + strconv.Itoa(len(t.Members)) + " members\n\n")
	sb.WriteString("[🎲 New 1v1 bet](" + call("CreateBet", "tableID", id) + ") · ")
	sb.WriteString("[🃏 New group bet](" + call("CreatePool", "tableID", id, "payout", "100", "acceptFewJudges", "false") + ") · ")
	sb.WriteString("[👋 Add member (owner only)](" + call("AddMember", "tableID", id) + ") · ")
	sb.WriteString("[✏️ Change your nickname](" + call("SetNickname", "tableID", id) + ")\n\n")

	// Leaderboard, sorted by net winnings.
	sb.WriteString("## 🏆 Leaderboard\n\n")
	var rows []row
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		rows = append(rows, row{m, s})
	}
	for i := 1; i < len(rows); i++ { // insertion sort, highest net first
		for j := i; j > 0 && rows[j].s.Net > rows[j-1].s.Net; j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	sb.WriteString("| # | Member | Net | W | L | D | Disputes lost | Judged | |\n|---|---|---|---|---|---|---|---|---|\n")
	for i, r := range rows {
		liar := strconv.Itoa(r.s.DisputesLost)
		if r.s.DisputesLost > 0 {
			liar = "🚩 " + liar
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + who(t, r.addr) + " | " + gnot(r.s.Net, true) + " | " +
			strconv.Itoa(r.s.Wins) + " | " + strconv.Itoa(r.s.Losses) + " | " + strconv.Itoa(r.s.Draws) + " | " +
			liar + " | " + strconv.Itoa(r.s.Judged) + " | [🎲 Challenge](" + challenge(t, r.addr) + ") |\n")
	}

	if len(t.PoolIDs) > 0 {
		sb.WriteString("\n## 🃏 Group bets\n\n| Game | Players | Stake | Status |\n|---|---|---|---|\n")
		for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
			p := mustPool(t.PoolIDs[i])
			sb.WriteString("| [" + escape(p.Title) + "](" + page("pool/"+strconv.Itoa(p.ID)) + ") | " +
				strconv.Itoa(len(p.Players)) + " | " + gnot(p.Stake, false) + " | " + poolBadge(t, p) + " |\n")
		}
	}

	sb.WriteString("\n## 🎲 Bets\n\n")
	if len(t.BetIDs) == 0 {
		sb.WriteString("_No bets yet._\n")
		return sb.String()
	}
	sb.WriteString("| Bet | Players | Stake | Status |\n|---|---|---|---|\n")
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- { // newest 30
		b := mustBet(t.BetIDs[i])
		sb.WriteString("| [" + escape(b.Title) + "](" + page("bet/"+strconv.Itoa(b.ID)) + ") | " +
			who(t, b.PlayerA) + " vs " + who(t, b.PlayerB) + " | " + gnot(b.Stake, false) + " | " + statusBadge(t, b) + " |\n")
	}
	return sb.String()
}

func renderBet(b *Bet) string {
	var sb strings.Builder
	id := strconv.Itoa(b.ID)
	t := mustTable(b.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🎲 " + escape(b.Title) + "\n\n")
	sb.WriteString("**Status: " + statusBadge(t, b) + "**\n\n")
	if hint := nextStep(t, b); hint != "" {
		sb.WriteString("> 👉 " + hint + "\n\n")
	}

	sb.WriteString("| | Player A | Player B |\n|---|---|---|\n")
	sb.WriteString("| Who | " + who(t, b.PlayerA) + " | " + who(t, b.PlayerB) + " |\n")
	sb.WriteString("| Stake | " + gnot(b.Stake, false) + " | " + gnot(b.Stake, false) + " |\n")
	sb.WriteString("| Honesty bond | " + gnot(b.Bond, false) + " | " + gnot(b.Bond, false) + " |\n")
	sb.WriteString("| Reported | " + result(t, b, b.ReportA) + " | " + result(t, b, b.ReportB) + " |\n\n")
	sb.WriteString("Pot: **" + gnot(2*b.Stake, false) + "**\n\n")
	aw, bw, dr := headToHead(t, b.PlayerA, b.PlayerB)
	if aw+bw+dr > 0 {
		sb.WriteString("Head to head at this table: " + plain(t, b.PlayerA) + " **" + strconv.Itoa(aw) + "** · " +
			plain(t, b.PlayerB) + " **" + strconv.Itoa(bw) + "** · draws **" + strconv.Itoa(dr) + "**\n\n")
	}
	if b.Status == StatusSettled || b.Status == StatusRefunded {
		loser := b.PlayerA
		if b.Final == ResultA {
			loser = b.PlayerB
		}
		other := b.PlayerB
		if loser == b.PlayerB {
			other = b.PlayerA
		}
		sb.WriteString("[🔁 Run it back](" + callSend("CreateBet", strconv.FormatInt(b.Stake+b.Bond, 10)+"ugnot", "tableID", strconv.Itoa(t.ID),
			"title", rematchTitle(b.Title), "opponentName", nameOrAddr(t, other),
			"stake", strconv.FormatInt(b.Stake, 10)) + ") _(for " + plain(t, loser) + ")_\n\n")
	}

	send := strconv.FormatInt(b.Stake+b.Bond, 10) + "ugnot"
	switch b.Status {
	case StatusOpen:
		sb.WriteString("### Actions\n\n")
		sb.WriteString("- Player B: [✅ Accept and lock " + gnot(b.Stake+b.Bond, false) + "](" +
			callSend("AcceptBet", send, "betID", id) + ")\n")
		sb.WriteString("- Player A: [❌ Cancel and refund](" + call("CancelBet", "betID", id) + ")\n")
	case StatusLive:
		sb.WriteString("### Report the result\n\n")
		sb.WriteString("[" + plain(t, b.PlayerA) + " won](" + call("Report", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[" + plain(t, b.PlayerB) + " won](" + call("Report", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Draw](" + call("Report", "betID", id, "result", ResultDraw) + ")\n\n")
		if (b.ReportA == "") != (b.ReportB == "") {
			when := b.FirstReportAt.Add(ReportWindow)
			sb.WriteString("_One player has reported. The other has until " + when.UTC().Format(time.RFC822) +
				" to answer, then either player can [⚖️ send it to the judges](" + call("Escalate", "betID", id) + ")._\n")
		}
	case StatusDisputed:
		sb.WriteString("### ⚖️ Judges are voting\n\n")
		sb.WriteString("Players disagree. Judges (table members with no money in this bet) decide. ")
		need := len(b.Judges)/2 + 1
		sb.WriteString("A result needs **" + strconv.Itoa(need) + " of " + strconv.Itoa(len(b.Judges)) + "** votes. ")
		sb.WriteString("Voting closes " + b.Deadline.UTC().Format(time.RFC822) + ".\n\n")
		sb.WriteString("Votes so far: " + plain(t, b.PlayerA) + " won **" + strconv.Itoa(b.countVotes(ResultA)) + "** · " + plain(t, b.PlayerB) + " won **" +
			strconv.Itoa(b.countVotes(ResultB)) + "** · Draw **" + strconv.Itoa(b.countVotes(ResultDraw)) + "**\n\n")
		sb.WriteString("Judges: [Vote " + plain(t, b.PlayerA) + " won](" + call("Vote", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[Vote " + plain(t, b.PlayerB) + " won](" + call("Vote", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Vote draw](" + call("Vote", "betID", id, "result", ResultDraw) + ")\n\n")
		sb.WriteString("_No majority by the deadline? Anyone can [refund everyone](" + call("ExpireDispute", "betID", id) + ")._\n")
	}

	if b.Status == StatusOpen {
		preview := t.judgesFor(b.PlayerA, b.PlayerB)
		sb.WriteString("\n### ⚖️ Judges if accepted\n\n")
		if len(preview) == 0 {
			sb.WriteString("_Nobody else is at this table, so a disagreement would be refunded._\n")
		}
		for _, j := range preview {
			sb.WriteString("- " + who(t, j) + "\n")
		}
	}

	if len(b.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_Fixed when the bet was accepted. Only used if the players disagree._\n\n")
		for _, j := range b.Judges {
			vote := "not voted"
			if v, ok := b.Votes.Get(j.String()).(string); ok {
				vote = result(t, b, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}

	if len(b.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, p := range b.Payouts {
			sb.WriteString("| " + who(t, p.To) + " | " + gnot(p.Amount, false) + " | " + p.Why + " |\n")
		}
	}
	return sb.String()
}

type row struct {
	addr address
	s    *Stats
}

func renderPool(p *Pool) string {
	var sb strings.Builder
	id := strconv.Itoa(p.ID)
	t := mustTable(p.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🃏 " + escape(p.Title) + "\n\n")
	sb.WriteString("**Status: " + poolBadge(t, p) + "**\n\n")
	if p.FewJudges {
		sb.WriteString("> ⚠️ This game was started with fewer than 3 judges. If players disagree, very few people decide the result. Play with people you trust.\n\n")
	}
	n := int64(len(p.Players))
	sb.WriteString("Stake **" + gnot(p.Stake, false) + "** each · bond " + gnot(p.Bond, false) + " each · pot **" + gnot(n*p.Stake, false) + "**\n\n")

	sb.WriteString("Payout: ")
	for i, sh := range p.Shares {
		if i > 0 {
			sb.WriteString(" · ")
		}
		sb.WriteString(placeName(i) + " " + strconv.FormatInt(sh, 10) + "%")
	}
	sb.WriteString("\n\n## Players\n\n| Player | Joined | Reported |\n|---|---|---|\n")
	for _, a := range p.Players {
		joined := "⏳"
		if p.Joined.Has(a.String()) {
			joined = "✅"
		}
		rep := "—"
		if v, ok := p.Reports.Get(a.String()).(string); ok {
			rep = rankingText(t, p, v)
		}
		sb.WriteString("| " + who(t, a) + " | " + joined + " | " + rep + " |\n")
	}

	switch p.Status {
	case StatusOpen:
		sb.WriteString("\n[✅ Join and lock " + gnot(p.Stake+p.Bond, false) + "](" +
			callSend("JoinPool", strconv.FormatInt(p.Stake+p.Bond, 10)+"ugnot", "poolID", id) + ") · ")
		sb.WriteString("[❌ Cancel (creator)](" + call("CancelPool", "poolID", id) + ")\n")
	case StatusLive:
		sb.WriteString("\nPlayers: [📝 Report the finishing order](" + call("ReportPool", "poolID", id) + ") ")
		sb.WriteString("_(" + strconv.Itoa(len(p.Shares)) + " name(s), best first, e.g. `" + exampleRanking(t, p) + "`)_\n")
	case StatusDisputed:
		sb.WriteString("\n### ⚖️ Judges are voting\n\nPlayers disagree. Judges: [vote the order](" + call("VotePool", "poolID", id) + ") · ")
		sb.WriteString("voting closes " + p.Deadline.UTC().Format(time.RFC822) + ".\n")
	}

	if len(p.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_The table members who didn't play. Only used if players disagree._\n\n")
		for _, j := range p.Judges {
			vote := "not voted"
			if v, ok := p.Votes.Get(j.String()).(string); ok {
				vote = rankingText(t, p, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}
	if len(p.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, x := range p.Payouts {
			sb.WriteString("| " + who(t, x.To) + " | " + gnot(x.Amount, false) + " | " + x.Why + " |\n")
		}
	}
	return sb.String()
}

func rankingText(t *Table, p *Pool, r string) string {
	var parts []string
	for i, a := range p.rankingAddrs(r) {
		parts = append(parts, placeName(i)+" "+plain(t, a))
	}
	return strings.Join(parts, ", ")
}

func exampleRanking(t *Table, p *Pool) string {
	var names []string
	for i := 0; i < len(p.Shares) && i < len(p.Players); i++ {
		names = append(names, nameOrAddr(t, p.Players[i]))
	}
	return strings.Join(names, ",")
}

func poolBadge(t *Table, p *Pool) string {
	switch p.Status {
	case StatusOpen:
		return "🟡 " + strconv.Itoa(p.Joined.Size()) + "/" + strconv.Itoa(len(p.Players)) + " joined"
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		order := p.rankingAddrs(p.Final)
		if len(order) > 0 {
			return "✅ " + plain(t, order[0]) + " won"
		}
		return "✅ settled"
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return p.Status.String()
}

// nextStep tells visitors what the bet is waiting for.
func nextStep(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "Waiting for " + plain(t, b.PlayerB) + " to accept and lock " + gnot(b.Stake+b.Bond, false) + "."
	case StatusLive:
		switch {
		case b.ReportA == "" && b.ReportB == "":
			return "Game on! After the game, both " + plain(t, b.PlayerA) + " and " + plain(t, b.PlayerB) + " report the result."
		case b.ReportA == "":
			return "Waiting for " + plain(t, b.PlayerA) + " to report."
		default:
			return "Waiting for " + plain(t, b.PlayerB) + " to report."
		}
	case StatusDisputed:
		return "The players disagree. Judges, it's your call."
	}
	return ""
}

// headToHead counts settled results between two players at a table,
// from a's point of view: a's wins, b's wins, draws.
func headToHead(t *Table, a, b address) (int, int, int) {
	aw, bw, dr := 0, 0, 0
	for _, id := range t.BetIDs {
		x := mustBet(id)
		if x.Status != StatusSettled {
			continue
		}
		var winner address
		switch x.Final {
		case ResultA:
			winner = x.PlayerA
		case ResultB:
			winner = x.PlayerB
		}
		pair := (x.PlayerA == a && x.PlayerB == b) || (x.PlayerA == b && x.PlayerB == a)
		if !pair {
			continue
		}
		switch winner {
		case a:
			aw++
		case b:
			bw++
		default:
			dr++
		}
	}
	return aw, bw, dr
}

func rematchTitle(title string) string {
	if !strings.HasPrefix(title, "Rematch: ") {
		title = "Rematch: " + title
	}
	if len(title) > 140 {
		title = title[:140]
	}
	return title
}

func nameOrAddr(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return n
	}
	return a.String()
}

func count(n int, word string) string {
	if n == 1 {
		return "**1** " + word
	}
	return "**" + strconv.Itoa(n) + "** " + word + "s"
}

// challenge links to CreateBet with the table and opponent filled in.
func challenge(t *Table, a address) string {
	return call("CreateBet", "tableID", strconv.Itoa(t.ID), "opponentName", nameOrAddr(t, a))
}

// ---------------------------------------------------------------------------
// Formatting helpers

func statusBadge(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "🟡 waiting for " + plain(t, b.PlayerB)
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		return "✅ settled: " + result(t, b, b.Final)
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return b.Status.String()
}

// result describes a reported/voted result using the players' nicknames.
func result(t *Table, b *Bet, r string) string {
	switch r {
	case ResultA:
		return plain(t, b.PlayerA) + " won"
	case ResultB:
		return plain(t, b.PlayerB) + " won"
	}
	return showReport(r)
}

// plain is a nickname (or short address) without markdown, for link text.
func plain(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return escape(n)
	}
	s := a.String()
	return s[:7] + "…" + s[len(s)-4:]
}

func showReport(r string) string {
	switch r {
	case ResultA:
		return "A won"
	case ResultB:
		return "B won"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64, signed bool) string {
	sign := ""
	if u < 0 {
		sign = "-"
		u = -u
	} else if signed && u > 0 {
		sign = "+"
	}
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		s += "." + strings.TrimRight(f, "0")
	}
	return sign + s + " GNOT"
}

// who shows a member's nickname at a table, falling back to a short address.
func who(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return "**" + escape(n) + "**"
	}
	return short(a)
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:7] + "…" + s[len(s)-4:] + "`"
}

func escape(s string) string {
	r := strings.NewReplacer("|", "\\|", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "\n", " ")
	return r.Replace(s)
}

func prefix() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func home() string           { return prefix() }
func page(sub string) string { return prefix() + ":" + sub }

// call builds a gnoweb transaction link: /r/...$help&func=Fn&k=v
func call(fn string, kv ...string) string {
	return callSend(fn, "", kv...)
}

func callSend(fn, send string, kv ...string) string {
	q := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		q.Add(kv[i], kv[i+1])
	}
	if send != "" {
		q.Add(".send", send)
	}
	link := prefix() + "$help&func=" + fn
	if enc := q.Encode(); enc != "" {
		link += "&" + enc
	}
	return link
}

// Package tavernwagers lets friend groups ("tables") bet on anything with each other.
//
// How it works:
//   - A table is an invite-only group of friends.
//   - Two players lock the same stake into the realm before the game,
//     plus a 10% honesty bond.
//   - After the game, both players report the result. If they agree, the
//     realm pays out instantly and both bonds come back.
//   - If they disagree, every other table member becomes a judge. Judges
//     have no money in the bet, so they have no reason to lie. As soon as
//     a strict majority of judges agree, the bet settles.
//   - A player whose report loses the vote forfeits their bond. Half goes
//     to the honest player, half to the judges who voted with the majority.
//     Majority judges also split a 1% fee from the pot for showing up.
//   - If the judges can't reach a majority before the deadline, everyone
//     is refunded in full.
//
// The realm takes no cut: every coin that goes in comes back out to the
// players and judges.
package tavernwagers

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	ResultA    = "a"    // player A won
	ResultB    = "b"    // player B won
	ResultDraw = "draw" // draw, stakes go back

	MinStake int64 = 10_000 // 0.01 GNOT

	ReportWindow = 24 * time.Hour // how long a player has to answer the other's report
	VoteWindow   = 48 * time.Hour // how long judges have to vote
)

type BetStatus int

const (
	StatusOpen      BetStatus = iota // waiting for player B to accept
	StatusLive                       // both staked, waiting for reports
	StatusDisputed                   // players disagree, judges voting
	StatusSettled                    // paid out
	StatusCancelled                  // cancelled before B accepted
	StatusRefunded                   // judges could not decide, everyone refunded
)

func (s BetStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusLive:
		return "live"
	case StatusDisputed:
		return "disputed"
	case StatusSettled:
		return "settled"
	case StatusCancelled:
		return "cancelled"
	case StatusRefunded:
		return "refunded"
	}
	return "unknown"
}

// Stats is one member's record at a table.
type Stats struct {
	Net          int64 // ugnot won minus ugnot lost
	Wins         int
	Losses       int
	Draws        int
	DisputesLost int // times this player's report lost a judges' vote
	Judged       int // times this member voted with the majority as a judge
}

type Table struct {
	ID      int
	Name    string
	Owner   address
	Members []address
	Stats   *avl.Tree // address -> *Stats
	Names   *avl.Tree // address -> nickname
	BetIDs  []int
	PoolIDs []int
	Created time.Time
}

type Payout struct {
	To     address
	Amount int64
	Why    string
}

type Bet struct {
	ID      int
	TableID int
	Title   string
	PlayerA address
	PlayerB address
	Stake   int64 // per player
	Bond    int64 // per player
	Status  BetStatus

	ReportA       string
	ReportB       string
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> result string
	Deadline time.Time // voting deadline when disputed

	Final   string
	Payouts []Payout
	Created time.Time
}

var (
	tables   avl.Tree // id -> *Table
	bets     avl.Tree // id -> *Bet
	tableSeq int
	betSeq   int

	totalLocked  int64 // ugnot locked in accepted bets, all time
	totalSettled int   // bets settled (paid out to a winner or draw)
)

// ---------------------------------------------------------------------------
// Tables

// CreateTable opens a new table. The caller becomes its owner and first
// member, shown under the given nickname.
func CreateTable(cur realm, name string, nickname string) int {
	caller := cur.Previous().Address()
	name = strings.TrimSpace(name)
	require(name != "", "table name required")
	require(len(name) <= 64, "table name too long (max 64)")
	require(printable(name), "table name has invalid characters")

	tableSeq++
	t := &Table{
		ID:      tableSeq,
		Name:    name,
		Owner:   caller,
		Members: []address{caller},
		Stats:   avl.NewTree(),
		Names:   avl.NewTree(),
		Created: time.Now(),
	}
	t.setName(caller, nickname)
	tables.Set(strconv.Itoa(t.ID), t)
	return t.ID
}

// AddMember invites a friend to a table under a nickname. Only the table
// owner can do this. Members can change their own nickname later.
func AddMember(cur realm, tableID int, member address, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can add members")
	require(member.IsValid(), "invalid address")
	require(!t.isMember(member), "already a member")
	require(len(t.Members) < 50, "table is full (max 50)")
	t.setName(member, nickname) // validate the nickname before changing anything
	t.Members = append(t.Members, member)
}

// SetNickname changes how you appear at a table.
func SetNickname(cur realm, tableID int, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(t.isMember(caller), "you are not a member of this table")
	t.setName(caller, nickname)
}

// ---------------------------------------------------------------------------
// Bets

// CreateBet proposes a bet against another table member and locks your stake.
// opponent is their nickname at the table (or their g1... address).
// Send exactly stake + 10% bond, e.g. stake 1000000 -> send 1100000ugnot.
// You are player A, the opponent is player B. The judges are fixed when
// the bet is accepted: every other member of the table at that moment.
func CreateBet(cur realm, tableID int, title string, opponentName string, stake int64) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "bet title required")
	require(len(title) <= 140, "bet title too long (max 140)")
	require(printable(title), "bet title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	opponent := t.resolve(opponentName)
	require(opponent != caller, "you can't bet against yourself")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	bond := stake / 10
	requireSent(stake + bond)

	betSeq++
	b := &Bet{
		ID:      betSeq,
		TableID: tableID,
		Title:   title,
		PlayerA: caller,
		PlayerB: opponent,
		Stake:   stake,
		Bond:    bond,
		Status:  StatusOpen,
		Votes:   avl.NewTree(),
		Created: time.Now(),
	}
	bets.Set(strconv.Itoa(b.ID), b)
	t.BetIDs = append(t.BetIDs, b.ID)
	return b.ID
}

// AcceptBet is called by player B to match the stake and bond.
func AcceptBet(cur realm, betID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	require(caller == b.PlayerB, "only the challenged player can accept")
	requireSent(b.Stake + b.Bond)
	b.Status = StatusLive
	b.Judges = mustTable(b.TableID).judgesFor(b.PlayerA, b.PlayerB)
	totalLocked += 2 * (b.Stake + b.Bond)
}

// CancelBet lets player A take the bet back before B accepts it.
func CancelBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "only open bets can be cancelled")
	require(caller == b.PlayerA, "only the player who created the bet can cancel it")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "cancelled, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// Report is how each player says who won: "a", "b" or "draw".
// If both players report the same result, the bet pays out right away.
// If they disagree, it goes to the judges.
func Report(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	result = normalizeResult(result)

	switch caller {
	case b.PlayerA:
		require(b.ReportA == "", "you already reported")
		b.ReportA = result
	case b.PlayerB:
		require(b.ReportB == "", "you already reported")
		b.ReportB = result
	default:
		panic("only the two players can report")
	}

	if b.ReportA == "" || b.ReportB == "" {
		b.FirstReportAt = time.Now()
		return
	}

	if b.ReportA == b.ReportB {
		b.settle(b.ReportA, nil)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
		return
	}

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Escalate sends a bet to the judges when one player reported and the
// other went quiet for longer than the report window.
func Escalate(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	require(caller == b.PlayerA || caller == b.PlayerB, "only the players can escalate")
	require((b.ReportA == "") != (b.ReportB == ""), "escalate needs exactly one report")
	require(time.Now().After(b.FirstReportAt.Add(ReportWindow)), "the other player still has time to report")

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Vote is for judges of a disputed bet: "a", "b" or "draw".
// The bet settles the moment one result has a strict majority of judges.
func Vote(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(b.isJudge(caller), "you are not a judge on this bet")
	require(!b.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(b.Deadline), "voting is closed")
	result = normalizeResult(result)

	b.Votes.Set(caller.String(), result)

	if b.countVotes(result)*2 > len(b.Judges) {
		var majority []address
		for _, j := range b.Judges {
			if v, ok := b.Votes.Get(j.String()).(string); ok && v == result {
				majority = append(majority, j)
			}
		}
		b.settle(result, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// ExpireDispute refunds everyone if the judges failed to reach a majority
// before the deadline. Anyone can call it.
func ExpireDispute(cur realm, betID int) {
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(time.Now().After(b.Deadline), "voting is still open")
	b.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement logic (pure bookkeeping, no coins move here)

// openDispute snapshots the judges. It returns false if the bet had to be
// refunded instead (a table with no possible judges).
func (b *Bet) openDispute() bool {
	if len(b.Judges) == 0 {
		b.refundAll("no judges at this table")
		return false
	}
	b.Status = StatusDisputed
	b.Deadline = time.Now().Add(VoteWindow)
	return true
}

func (b *Bet) refundAll(why string) {
	b.Status = StatusRefunded
	each := b.Stake + b.Bond
	b.Payouts = []Payout{
		{b.PlayerA, each, why + ", refund"},
		{b.PlayerB, each, why + ", refund"},
	}
}

// settle fills in b.Payouts for a final result and updates the leaderboard.
// majority is nil when the players agreed (no judges involved).
func (b *Bet) settle(final string, majority []address) {
	b.Status = StatusSettled
	totalSettled++
	b.Final = final
	pot := 2 * b.Stake

	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = 2 * (b.Stake / 100) // 1% of the pot, always even
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, minus the judges' fee.
	switch final {
	case ResultA:
		add(b.PlayerA, pot-fee, "won the pot")
	case ResultB:
		add(b.PlayerB, pot-fee, "won the pot")
	case ResultDraw:
		add(b.PlayerA, b.Stake-fee/2, "draw, stake back")
		add(b.PlayerB, b.Stake-fee/2, "draw, stake back")
	}

	// 2. Honesty bonds.
	forfeited := int64(0)
	var honest []address
	t := mustTable(b.TableID)
	players := []address{b.PlayerA, b.PlayerB}
	reports := []string{b.ReportA, b.ReportB}
	for i := range players {
		if !disputed || reports[i] == final {
			add(players[i], b.Bond, "bond back")
			if disputed {
				honest = append(honest, players[i])
			}
		} else {
			forfeited += b.Bond
			t.stats(players[i]).DisputesLost++
		}
	}

	// 3. Forfeited bonds: half to the honest player(s), half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liar's bond", add)
		} else {
			judgePool += forfeited
		}
	}

	// 4. Judges who voted with the majority split their pool.
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
		}
	}

	b.Payouts = payouts

	// Leaderboard: net result per person, relative to what they put in.
	deposit := b.Stake + b.Bond
	t.stats(b.PlayerA).Net += received(payouts, b.PlayerA) - deposit
	t.stats(b.PlayerB).Net += received(payouts, b.PlayerB) - deposit
	for _, j := range majority {
		t.stats(j).Net += received(payouts, j)
	}
	switch final {
	case ResultA:
		t.stats(b.PlayerA).Wins++
		t.stats(b.PlayerB).Losses++
	case ResultB:
		t.stats(b.PlayerB).Wins++
		t.stats(b.PlayerA).Losses++
	case ResultDraw:
		t.stats(b.PlayerA).Draws++
		t.stats(b.PlayerB).Draws++
	}
}

// split divides amount evenly; the remainder goes to the first recipient so
// no dust is ever stuck in the realm.
func split(to []address, amount int64, why string, add func(address, int64, string)) {
	if len(to) == 0 || amount <= 0 {
		return
	}
	n := int64(len(to))
	each := amount / n
	rest := amount - each*n
	for i, a := range to {
		amt := each
		if i == 0 {
			amt += rest
		}
		add(a, amt, why)
	}
}

func received(payouts []Payout, who address) int64 {
	total := int64(0)
	for _, p := range payouts {
		if p.To == who {
			total += p.Amount
		}
	}
	return total
}

// pay moves the coins. The banker is always created inside the exported
// crossing function, from its own cur.
func pay(bk banker.Banker, from address, payouts []Payout) {
	for _, p := range payouts {
		bk.SendCoins(from, p.To, chain.Coins{{"ugnot", p.Amount}})
	}
}

// ---------------------------------------------------------------------------
// Read-only getters

func GetTableName(tableID int) string { return mustTable(tableID).Name }
func GetBetStatus(betID int) string   { return mustBet(betID).Status.String() }
func GetBetResult(betID int) string   { return mustBet(betID).Final }

func GetNet(tableID int, who address) int64 {
	t := mustTable(tableID)
	if v := t.Stats.Get(who.String()); v != nil {
		return v.(*Stats).Net
	}
	return 0
}

// ---------------------------------------------------------------------------
// Helpers

func (t *Table) isMember(a address) bool {
	for _, m := range t.Members {
		if m == a {
			return true
		}
	}
	return false
}

// setName validates and stores a nickname (unique per table). An empty
// nickname clears it, and the address is shown instead.
func (t *Table) setName(a address, nickname string) {
	nickname = strings.TrimSpace(nickname)
	if nickname == "" {
		t.Names.Remove(a.String())
		return
	}
	require(len(nickname) <= 24, "nickname too long (max 24)")
	for _, r := range nickname {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.'
		require(ok, "nickname can only use letters, numbers, spaces, - _ .")
	}
	lower := strings.ToLower(nickname)
	t.Names.Iterate("", "", func(k string, v any) bool {
		require(k == a.String() || strings.ToLower(v.(string)) != lower, "nickname already taken at this table")
		return false
	})
	t.Names.Set(a.String(), nickname)
}

// Nick returns a member's nickname, or "" if they have none.
func (t *Table) Nick(a address) string {
	if v := t.Names.Get(a.String()); v != nil {
		return v.(string)
	}
	return ""
}

// judgesFor lists every member except the two players.
func (t *Table) judgesFor(a, b address) []address {
	var judges []address
	for _, m := range t.Members {
		if m != a && m != b {
			judges = append(judges, m)
		}
	}
	return judges
}

// resolve finds a member by nickname (case-insensitive) or g1 address.
func (t *Table) resolve(who string) address {
	who = strings.TrimSpace(who)
	if strings.HasPrefix(who, "g1") {
		if a := address(who); a.IsValid() {
			require(t.isMember(a), "opponent is not a member of this table")
			return a
		}
	}
	lower := strings.ToLower(who)
	var found address
	t.Names.Iterate("", "", func(k string, v any) bool {
		if strings.ToLower(v.(string)) == lower {
			found = address(k)
			return true
		}
		return false
	})
	require(found != "" && t.isMember(found), "opponent is not a member of this table")
	return found
}

func (t *Table) stats(a address) *Stats {
	if v := t.Stats.Get(a.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	t.Stats.Set(a.String(), s)
	return s
}

func (b *Bet) isJudge(a address) bool {
	for _, j := range b.Judges {
		if j == a {
			return true
		}
	}
	return false
}

func (b *Bet) countVotes(result string) int {
	n := 0
	b.Votes.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == result {
			n++
		}
		return false
	})
	return n
}

// printable rejects control characters (newlines, tabs, etc.).
func printable(s string) bool {
	for _, r := range s {
		if r < 32 || r == 127 {
			return false
		}
	}
	return true
}

func normalizeResult(r string) string {
	r = strings.ToLower(strings.TrimSpace(r))
	require(r == ResultA || r == ResultB || r == ResultDraw, `result must be "a", "b" or "draw"`)
	return r
}

func requireSent(want int64) {
	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == "ugnot",
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
	require(sent[0].Amount == want,
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
}

func mustTable(id int) *Table {
	v := tables.Get(strconv.Itoa(id))
	if v == nil {
		panic("table not found")
	}
	return v.(*Table)
}

func mustBet(id int) *Bet {
	v := bets.Get(strconv.Itoa(id))
	if v == nil {
		panic("bet not found")
	}
	return v.(*Bet)
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

package tavernwagers

import (
	"strconv"
	"strings"
)

// Read-only JSON views for the web app (query them with vm/qeval).

// TablesJSON lists the newest 30 tables.
func TablesJSON() string {
	var items []string
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		items = append(items, tableSummary(v.(*Table)))
		return len(items) >= 30
	})
	return "[" + strings.Join(items, ",") + "]"
}

// MyTablesJSON lists the tables an address belongs to.
func MyTablesJSON(who address) string {
	var items []string
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Table)
		if t.isMember(who) {
			items = append(items, tableSummary(t))
		}
		return len(items) >= 50
	})
	return "[" + strings.Join(items, ",") + "]"
}

// TableJSON returns a table with its members, stats and newest 30 bets.
func TableJSON(tableID int) string {
	t := mustTable(tableID)
	var members []string
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		members = append(members, obj(
			"address", q(m.String()),
			"nick", q(t.Nick(m)),
			"net", i64(s.Net),
			"wins", itoa(s.Wins),
			"losses", itoa(s.Losses),
			"draws", itoa(s.Draws),
			"disputesLost", itoa(s.DisputesLost),
			"judged", itoa(s.Judged),
		))
	}
	var betList []string
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- {
		betList = append(betList, betJSON(mustBet(t.BetIDs[i])))
	}
	var poolList []string
	for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
		poolList = append(poolList, poolJSON(mustPool(t.PoolIDs[i])))
	}
	return obj(
		"id", itoa(t.ID),
		"name", q(t.Name),
		"owner", q(t.Owner.String()),
		"members", "["+strings.Join(members, ",")+"]",
		"bets", "["+strings.Join(betList, ",")+"]",
		"pools", "["+strings.Join(poolList, ",")+"]",
	)
}

// BetJSON returns one bet with reports, judges, votes and payouts.
func BetJSON(betID int) string {
	return betJSON(mustBet(betID))
}

// PoolJSON returns one group bet.
func PoolJSON(poolID int) string {
	return poolJSON(mustPool(poolID))
}

func poolJSON(p *Pool) string {
	var players []string
	for _, a := range p.Players {
		rep, _ := p.Reports.Get(a.String()).(string)
		players = append(players, obj(
			"address", q(a.String()),
			"joined", boolStr(p.Joined.Has(a.String())),
			"report", q(rep),
		))
	}
	var judges []string
	for _, j := range p.Judges {
		vote, _ := p.Votes.Get(j.String()).(string)
		judges = append(judges, obj("address", q(j.String()), "vote", q(vote)))
	}
	var shares []string
	for _, sh := range p.Shares {
		shares = append(shares, i64(sh))
	}
	var payouts []string
	for _, x := range p.Payouts {
		payouts = append(payouts, obj("to", q(x.To.String()), "amount", i64(x.Amount), "why", q(x.Why)))
	}
	deadline := ""
	if p.Status == StatusDisputed {
		deadline = p.Deadline.UTC().Format("2006-01-02T15:04:05Z")
	}
	firstReport := ""
	if !p.FirstReportAt.IsZero() {
		firstReport = p.FirstReportAt.UTC().Format("2006-01-02T15:04:05Z")
	}
	return obj(
		"id", itoa(p.ID),
		"kind", q("pool"),
		"tableId", itoa(p.TableID),
		"title", q(p.Title),
		"creator", q(p.Creator.String()),
		"stake", i64(p.Stake),
		"bond", i64(p.Bond),
		"shares", "["+strings.Join(shares, ",")+"]",
		"status", q(p.Status.String()),
		"players", "["+strings.Join(players, ",")+"]",
		"judges", "["+strings.Join(judges, ",")+"]",
		"final", q(p.Final),
		"fewJudges", boolStr(p.FewJudges),
		"deadline", q(deadline),
		"firstReportAt", q(firstReport),
		"payouts", "["+strings.Join(payouts, ",")+"]",
	)
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func tableSummary(t *Table) string {
	return obj(
		"id", itoa(t.ID),
		"name", q(t.Name),
		"owner", q(t.Owner.String()),
		"ownerNick", q(t.Nick(t.Owner)),
		"members", itoa(len(t.Members)),
		"bets", itoa(len(t.BetIDs)+len(t.PoolIDs)),
	)
}

func betJSON(b *Bet) string {
	var judges []string
	for _, j := range b.Judges {
		vote := ""
		if v, ok := b.Votes.Get(j.String()).(string); ok {
			vote = v
		}
		judges = append(judges, obj("address", q(j.String()), "vote", q(vote)))
	}
	var payouts []string
	for _, p := range b.Payouts {
		payouts = append(payouts, obj("to", q(p.To.String()), "amount", i64(p.Amount), "why", q(p.Why)))
	}
	deadline := ""
	if b.Status == StatusDisputed {
		deadline = b.Deadline.UTC().Format("2006-01-02T15:04:05Z")
	}
	firstReport := ""
	if !b.FirstReportAt.IsZero() {
		firstReport = b.FirstReportAt.UTC().Format("2006-01-02T15:04:05Z")
	}
	return obj(
		"id", itoa(b.ID),
		"tableId", itoa(b.TableID),
		"title", q(b.Title),
		"playerA", q(b.PlayerA.String()),
		"playerB", q(b.PlayerB.String()),
		"stake", i64(b.Stake),
		"bond", i64(b.Bond),
		"status", q(b.Status.String()),
		"reportA", q(b.ReportA),
		"reportB", q(b.ReportB),
		"final", q(b.Final),
		"judges", "["+strings.Join(judges, ",")+"]",
		"deadline", q(deadline),
		"firstReportAt", q(firstReport),
		"payouts", "["+strings.Join(payouts, ",")+"]",
	)
}

// obj builds a JSON object from key, raw-value pairs.
func obj(kv ...string) string {
	var parts []string
	for i := 0; i+1 < len(kv); i += 2 {
		parts = append(parts, q(kv[i])+":"+kv[i+1])
	}
	return "{" + strings.Join(parts, ",") + "}"
}

// q quotes a string as JSON. Inputs never contain control characters
// (titles and names are validated), so strconv.Quote is JSON-safe here.
func q(s string) string { return strconv.Quote(s) }

func itoa(n int) string  { return strconv.Itoa(n) }
func i64(n int64) string  { return strconv.FormatInt(n, 10) }

package tavernwagers

import (
	"chain/banker"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Group bets ("pools") are for games with more than two players: a poker
// night, a FIFA tournament, a pub quiz. Every player locks the same stake
// plus a 10% bond. The pot is paid out by finishing position, using shares
// chosen up front: "100" is winner-takes-all, "60,30,10" pays the top three.
//
// Nobody deals the result. Every player reports the finishing order; if
// they all agree, the pot pays out instantly. If anyone disagrees, the
// table members who did NOT play judge it, exactly like a 1v1 bet. Any
// player whose report loses the vote forfeits their bond.

const (
	MaxPoolPlayers = 20
	MinJudges      = 3 // recommended minimum judge panel for a group bet
)

type Pool struct {
	ID      int
	TableID int
	Title   string
	Creator address
	Players []address // invited players, creator first
	Joined  *avl.Tree // address -> true once their stake is locked
	Stake   int64
	Bond    int64
	Shares  []int64 // percent of the pot by finishing position, sums to 100
	Status  BetStatus

	Reports       *avl.Tree // address -> canonical ranking
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> canonical ranking
	Deadline time.Time

	FewJudges bool // created with fewer than MinJudges possible judges

	Final   string // canonical ranking: comma-separated addresses, 1st first
	Payouts []Payout
	Created time.Time
}

var (
	pools   avl.Tree // id -> *Pool
	poolSeq int
)

// CreatePool opens a group bet and locks your stake. players is a
// comma-separated list of the OTHER players' nicknames (or addresses).
// payout is the split of the pot by finishing position in percent:
// "100" (winner takes all) or e.g. "60,30,10". Send stake + 10% bond.
//
// Disputes are decided by the table members who are NOT playing. We want at
// least MinJudges of them, so no one or two people hold all the power. A
// table can still play with fewer (everyone wants in on poker night) by
// setting acceptFewJudges, which is shown as a warning on the game.
func CreatePool(cur realm, tableID int, title string, players string, stake int64, payout string, acceptFewJudges bool) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "title required")
	require(len(title) <= 140, "title too long (max 140)")
	require(printable(title), "title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	list := []address{caller}
	for _, name := range strings.Split(players, ",") {
		if strings.TrimSpace(name) == "" {
			continue
		}
		a := t.resolve(name)
		require(!containsAddr(list, a), "a player is listed twice")
		list = append(list, a)
	}
	require(len(list) >= 3, "a group bet needs at least 3 players (use a 1v1 bet for 2)")
	require(len(list) <= MaxPoolPlayers, "too many players (max 20)")

	shares := parseShares(payout)
	require(len(shares) < len(list), "more paid places than players minus one")

	judgesNow := len(t.Members) - len(list)
	require(judgesNow >= MinJudges || acceptFewJudges,
		"only "+strconv.Itoa(judgesNow)+" table member(s) left to judge disputes (we recommend "+strconv.Itoa(MinJudges)+
			"): leave some people out to judge, or set acceptFewJudges to play anyway")

	bond := stake / 10
	requireSent(stake + bond)

	poolSeq++
	p := &Pool{
		ID:      poolSeq,
		TableID: tableID,
		Title:   title,
		Creator: caller,
		Players: list,
		Joined:  avl.NewTree(),
		Stake:   stake,
		Bond:    bond,
		Shares:  shares,
		Status:  StatusOpen,
		Reports: avl.NewTree(),
		Votes:   avl.NewTree(),
		Created: time.Now(),

		FewJudges: judgesNow < MinJudges,
	}
	p.Joined.Set(caller.String(), true)
	pools.Set(strconv.Itoa(p.ID), p)
	t.PoolIDs = append(t.PoolIDs, p.ID)
	return p.ID
}

// JoinPool locks your stake + bond. The game goes live once every invited
// player has joined; the judges are fixed at that moment.
func JoinPool(cur realm, poolID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusOpen, "this group bet is not open")
	require(containsAddr(p.Players, caller), "you are not invited to this group bet")
	require(!p.Joined.Has(caller.String()), "you already joined")
	requireSent(p.Stake + p.Bond)
	p.Joined.Set(caller.String(), true)

	if p.Joined.Size() == len(p.Players) {
		p.Status = StatusLive
		t := mustTable(p.TableID)
		var judges []address
		for _, m := range t.Members {
			if !containsAddr(p.Players, m) {
				judges = append(judges, m)
			}
		}
		p.Judges = judges
		totalLocked += int64(len(p.Players)) * (p.Stake + p.Bond)
	}
}

// CancelPool lets the creator call it off before everyone joined.
// Everyone who already joined is refunded in full.
func CancelPool(cur realm, poolID int) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusOpen, "only open group bets can be cancelled")
	require(caller == p.Creator, "only the creator can cancel")
	p.Status = StatusCancelled
	for _, a := range p.Players {
		if p.Joined.Has(a.String()) {
			p.Payouts = append(p.Payouts, Payout{a, p.Stake + p.Bond, "cancelled, refund"})
		}
	}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// ReportPool is how each player reports the finishing order of the paid
// places, as comma-separated nicknames: "Alice,Bob" for 1st and 2nd.
// When every player has reported the same order, the pot pays out.
func ReportPool(cur realm, poolID int, ranking string) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusLive, "this group bet is not waiting for reports")
	require(containsAddr(p.Players, caller), "only players can report")
	require(!p.Reports.Has(caller.String()), "you already reported")
	r := p.canonical(ranking)
	p.Reports.Set(caller.String(), r)

	if p.Reports.Size() == 1 {
		p.FirstReportAt = time.Now()
	}
	if p.Reports.Size() < len(p.Players) {
		return
	}
	if p.allReportsAgree() {
		p.settle(r, nil)
	} else {
		p.openDispute()
	}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// EscalatePool sends the group bet to the judges when some players went
// quiet for longer than the report window.
func EscalatePool(cur realm, poolID int) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusLive, "this group bet is not waiting for reports")
	require(containsAddr(p.Players, caller), "only players can escalate")
	require(p.Reports.Size() > 0, "nobody has reported yet")
	require(time.Now().After(p.FirstReportAt.Add(ReportWindow)), "players still have time to report")
	p.openDispute()
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// VotePool is for judges of a disputed group bet. The order with a strict
// majority of judges wins.
func VotePool(cur realm, poolID int, ranking string) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusDisputed, "this group bet is not in dispute")
	require(containsAddr(p.Judges, caller), "you are not a judge on this group bet")
	require(!p.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(p.Deadline), "voting is closed")
	r := p.canonical(ranking)
	p.Votes.Set(caller.String(), r)

	if countValue(p.Votes, r)*2 > len(p.Judges) {
		var majority []address
		for _, j := range p.Judges {
			if v, ok := p.Votes.Get(j.String()).(string); ok && v == r {
				majority = append(majority, j)
			}
		}
		p.settle(r, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
	}
}

// ExpirePool refunds everyone if the judges missed the deadline.
func ExpirePool(cur realm, poolID int) {
	p := mustPool(poolID)
	require(p.Status == StatusDisputed, "this group bet is not in dispute")
	require(time.Now().After(p.Deadline), "voting is still open")
	p.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement (bookkeeping only)

func (p *Pool) openDispute() {
	if len(p.Judges) == 0 {
		p.refundAll("no judges at this table")
		return
	}
	p.Status = StatusDisputed
	p.Deadline = time.Now().Add(VoteWindow)
}

func (p *Pool) refundAll(why string) {
	p.Status = StatusRefunded
	p.Payouts = nil
	for _, a := range p.Players {
		p.Payouts = append(p.Payouts, Payout{a, p.Stake + p.Bond, why + ", refund"})
	}
}

func (p *Pool) settle(final string, majority []address) {
	p.Status = StatusSettled
	p.Final = final
	totalSettled++
	t := mustTable(p.TableID)
	n := int64(len(p.Players))
	pot := n * p.Stake
	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = pot / 100
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, by finishing position. Rounding dust goes to 1st place.
	order := p.rankingAddrs(final)
	prize := pot - fee
	rest := int64(0)
	for i := 1; i < len(order); i++ {
		rest += prize * p.Shares[i] / 100
	}
	for i, a := range order {
		amt := prize * p.Shares[i] / 100
		if i == 0 {
			amt = prize - rest
		}
		add(a, amt, placeName(i)+" place")
	}

	// 2. Bonds.
	forfeited := int64(0)
	var honest []address
	for _, a := range p.Players {
		rep, _ := p.Reports.Get(a.String()).(string)
		if !disputed || rep == final {
			add(a, p.Bond, "bond back")
			if disputed {
				honest = append(honest, a)
			}
		} else {
			forfeited += p.Bond
			t.stats(a).DisputesLost++
		}
	}

	// 3. Forfeited bonds: half to honest players, half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liars' bonds", add)
		} else {
			judgePool += forfeited
		}
	}
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
			t.stats(j).Net += received(payouts, j)
		}
	}
	p.Payouts = payouts

	// Leaderboard.
	deposit := p.Stake + p.Bond
	for _, a := range p.Players {
		s := t.stats(a)
		s.Net += received(payouts, a) - deposit
		if len(order) > 0 && a == order[0] {
			s.Wins++
		} else if !containsAddr(order, a) {
			s.Losses++
		}
	}
}

// ---------------------------------------------------------------------------
// Rankings

// canonical turns "Alice, bob" into "g1...,g1..." with exactly as many
// entries as there are paid places, all distinct players.
func (p *Pool) canonical(ranking string) string {
	t := mustTable(p.TableID)
	var out []string
	var seen []address
	for _, name := range strings.Split(ranking, ",") {
		if strings.TrimSpace(name) == "" {
			continue
		}
		a := t.resolve(name)
		require(containsAddr(p.Players, a), "everyone in the ranking must be a player")
		require(!containsAddr(seen, a), "a player is ranked twice")
		seen = append(seen, a)
		out = append(out, a.String())
	}
	require(len(out) == len(p.Shares), "rank exactly "+strconv.Itoa(len(p.Shares))+" player(s), best first")
	return strings.Join(out, ",")
}

func (p *Pool) rankingAddrs(r string) []address {
	var out []address
	for _, s := range strings.Split(r, ",") {
		if s != "" {
			out = append(out, address(s))
		}
	}
	return out
}

func (p *Pool) allReportsAgree() bool {
	first := ""
	agree := true
	p.Reports.Iterate("", "", func(_ string, v any) bool {
		if first == "" {
			first = v.(string)
		} else if v.(string) != first {
			agree = false
			return true
		}
		return false
	})
	return agree
}

func parseShares(payout string) []int64 {
	payout = strings.TrimSpace(payout)
	if payout == "" {
		payout = "100"
	}
	var shares []int64
	total := int64(0)
	for _, s := range strings.Split(payout, ",") {
		n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
		require(err == nil && n > 0, `payout must be percentages like "100" or "60,30,10"`)
		shares = append(shares, n)
		total += n
	}
	require(total == 100, "payout percentages must add up to 100")
	for i := 1; i < len(shares); i++ {
		require(shares[i] <= shares[i-1], "payout must not grow for lower places")
	}
	return shares
}

func placeName(i int) string {
	switch i {
	case 0:
		return "1st"
	case 1:
		return "2nd"
	case 2:
		return "3rd"
	}
	return strconv.Itoa(i+1) + "th"
}

func containsAddr(list []address, a address) bool {
	for _, x := range list {
		if x == a {
			return true
		}
	}
	return false
}

func countValue(tree *avl.Tree, want string) int {
	n := 0
	tree.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == want {
			n++
		}
		return false
	})
	return n
}

func mustPool(id int) *Pool {
	v := pools.Get(strconv.Itoa(id))
	if v == nil {
		panic("group bet not found")
	}
	return v.(*Pool)
}

// GetPoolStatus returns a group bet's status.
func GetPoolStatus(poolID int) string { return mustPool(poolID).Status.String() }

package tavernwagers

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// Render shows the realm's pages on gnoweb:
//
//	""         home: how it works + all tables
//	"table/N"  a table: members, leaderboard, bets
//	"bet/N"    a bet: players, reports, votes, payouts, actions
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 2 {
		if _, err := strconv.Atoi(parts[1]); err == nil {
			switch parts[0] {
			case "table":
				if v := tables.Get(parts[1]); v != nil {
					return renderTable(v.(*Table))
				}
				return "# Table not found\n\n[Back home](" + home() + ")"
			case "bet":
				if v := bets.Get(parts[1]); v != nil {
					return renderBet(v.(*Bet))
				}
				return "# Bet not found\n\n[Back home](" + home() + ")"
			case "pool":
				if v := pools.Get(parts[1]); v != nil {
					return renderPool(v.(*Pool))
				}
				return "# Group bet not found\n\n[Back home](" + home() + ")"
			}
		}
	}
	return renderHome()
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# 🍺 Tavern Wagers\n\n")
	sb.WriteString("**Bet on anything with your friends. The money's locked upfront, neutral judges call it, and the winner gets paid automatically. No more \"I'll pay you later.\"**\n\n")
	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Open a table** and invite your friends.\n")
	sb.WriteString("2. **Make a bet** against a friend. Both players lock the same stake + a 10% honesty bond.\n")
	sb.WriteString("3. **Play** (chess, FIFA, D&D, anything).\n")
	sb.WriteString("4. **Both players report the result.** If you agree, you're paid instantly and get your bonds back.\n")
	sb.WriteString("5. **Disagree?** Everyone else at the table becomes a judge. They have no money in it, so they have no reason to lie. A strict majority decides.\n")
	sb.WriteString("6. **Lying costs you.** The player who loses the vote forfeits their bond: half to the honest player, half to the judges. Judges also split a 1% fee for showing up.\n")
	sb.WriteString("7. **No majority before the deadline?** Everyone is refunded in full.\n\n")
	sb.WriteString("The realm keeps nothing. Every coin that goes in comes back out to players and judges.\n\n")
	sb.WriteString("[➕ Open a new table](" + call("CreateTable") + ")\n\n")

	sb.WriteString(count(tables.Size(), "table") + " · " + count(bets.Size(), "bet") + " · " +
		count(totalSettled, "settled bet") + " · **" + gnot(totalLocked, false) + "** locked all time\n\n")

	sb.WriteString("## Tables\n\n")
	if tables.Size() == 0 {
		sb.WriteString("_No tables yet. Be the first._\n")
		return sb.String()
	}
	sb.WriteString("| Table | Members | Bets | Owner |\n|---|---|---|---|\n")
	shown := 0
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		shown++
		if shown > 30 {
			return true // newest 30 only
		}
		t := v.(*Table)
		sb.WriteString("| [" + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ") | " +
			strconv.Itoa(len(t.Members)) + " | " + strconv.Itoa(len(t.BetIDs)) + " | " + who(t, t.Owner) + " |\n")
		return false
	})
	return sb.String()
}

func renderTable(t *Table) string {
	var sb strings.Builder
	id := strconv.Itoa(t.ID)
	sb.WriteString("[← All tables](" + home() + ")\n\n")
	sb.WriteString("# 🍺 " + escape(t.Name) + "\n\n")
	sb.WriteString("Table #" + id + " · owner " + who(t, t.Owner) + " · " + strconv.Itoa(len(t.Members)) + " members\n\n")
	sb.WriteString("[🎲 New 1v1 bet](" + call("CreateBet", "tableID", id) + ") · ")
	sb.WriteString("[🃏 New group bet](" + call("CreatePool", "tableID", id, "payout", "100", "acceptFewJudges", "false") + ") · ")
	sb.WriteString("[👋 Add member (owner only)](" + call("AddMember", "tableID", id) + ") · ")
	sb.WriteString("[✏️ Change your nickname](" + call("SetNickname", "tableID", id) + ")\n\n")

	// Leaderboard, sorted by net winnings.
	sb.WriteString("## 🏆 Leaderboard\n\n")
	var rows []row
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		rows = append(rows, row{m, s})
	}
	for i := 1; i < len(rows); i++ { // insertion sort, highest net first
		for j := i; j > 0 && rows[j].s.Net > rows[j-1].s.Net; j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	sb.WriteString("| # | Member | Net | W | L | D | Disputes lost | Judged | |\n|---|---|---|---|---|---|---|---|---|\n")
	for i, r := range rows {
		liar := strconv.Itoa(r.s.DisputesLost)
		if r.s.DisputesLost > 0 {
			liar = "🚩 " + liar
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + who(t, r.addr) + " | " + gnot(r.s.Net, true) + " | " +
			strconv.Itoa(r.s.Wins) + " | " + strconv.Itoa(r.s.Losses) + " | " + strconv.Itoa(r.s.Draws) + " | " +
			liar + " | " + strconv.Itoa(r.s.Judged) + " | [🎲 Challenge](" + challenge(t, r.addr) + ") |\n")
	}

	if len(t.PoolIDs) > 0 {
		sb.WriteString("\n## 🃏 Group bets\n\n| Game | Players | Stake | Status |\n|---|---|---|---|\n")
		for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
			p := mustPool(t.PoolIDs[i])
			sb.WriteString("| [" + escape(p.Title) + "](" + page("pool/"+strconv.Itoa(p.ID)) + ") | " +
				strconv.Itoa(len(p.Players)) + " | " + gnot(p.Stake, false) + " | " + poolBadge(t, p) + " |\n")
		}
	}

	sb.WriteString("\n## 🎲 Bets\n\n")
	if len(t.BetIDs) == 0 {
		sb.WriteString("_No bets yet._\n")
		return sb.String()
	}
	sb.WriteString("| Bet | Players | Stake | Status |\n|---|---|---|---|\n")
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- { // newest 30
		b := mustBet(t.BetIDs[i])
		sb.WriteString("| [" + escape(b.Title) + "](" + page("bet/"+strconv.Itoa(b.ID)) + ") | " +
			who(t, b.PlayerA) + " vs " + who(t, b.PlayerB) + " | " + gnot(b.Stake, false) + " | " + statusBadge(t, b) + " |\n")
	}
	return sb.String()
}

func renderBet(b *Bet) string {
	var sb strings.Builder
	id := strconv.Itoa(b.ID)
	t := mustTable(b.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🎲 " + escape(b.Title) + "\n\n")
	sb.WriteString("**Status: " + statusBadge(t, b) + "**\n\n")
	if hint := nextStep(t, b); hint != "" {
		sb.WriteString("> 👉 " + hint + "\n\n")
	}

	sb.WriteString("| | Player A | Player B |\n|---|---|---|\n")
	sb.WriteString("| Who | " + who(t, b.PlayerA) + " | " + who(t, b.PlayerB) + " |\n")
	sb.WriteString("| Stake | " + gnot(b.Stake, false) + " | " + gnot(b.Stake, false) + " |\n")
	sb.WriteString("| Honesty bond | " + gnot(b.Bond, false) + " | " + gnot(b.Bond, false) + " |\n")
	sb.WriteString("| Reported | " + result(t, b, b.ReportA) + " | " + result(t, b, b.ReportB) + " |\n\n")
	sb.WriteString("Pot: **" + gnot(2*b.Stake, false) + "**\n\n")
	aw, bw, dr := headToHead(t, b.PlayerA, b.PlayerB)
	if aw+bw+dr > 0 {
		sb.WriteString("Head to head at this table: " + plain(t, b.PlayerA) + " **" + strconv.Itoa(aw) + "** · " +
			plain(t, b.PlayerB) + " **" + strconv.Itoa(bw) + "** · draws **" + strconv.Itoa(dr) + "**\n\n")
	}
	if b.Status == StatusSettled || b.Status == StatusRefunded {
		loser := b.PlayerA
		if b.Final == ResultA {
			loser = b.PlayerB
		}
		other := b.PlayerB
		if loser == b.PlayerB {
			other = b.PlayerA
		}
		sb.WriteString("[🔁 Run it back](" + callSend("CreateBet", strconv.FormatInt(b.Stake+b.Bond, 10)+"ugnot", "tableID", strconv.Itoa(t.ID),
			"title", rematchTitle(b.Title), "opponentName", nameOrAddr(t, other),
			"stake", strconv.FormatInt(b.Stake, 10)) + ") _(for " + plain(t, loser) + ")_\n\n")
	}

	send := strconv.FormatInt(b.Stake+b.Bond, 10) + "ugnot"
	switch b.Status {
	case StatusOpen:
		sb.WriteString("### Actions\n\n")
		sb.WriteString("- Player B: [✅ Accept and lock " + gnot(b.Stake+b.Bond, false) + "](" +
			callSend("AcceptBet", send, "betID", id) + ")\n")
		sb.WriteString("- Player A: [❌ Cancel and refund](" + call("CancelBet", "betID", id) + ")\n")
	case StatusLive:
		sb.WriteString("### Report the result\n\n")
		sb.WriteString("[" + plain(t, b.PlayerA) + " won](" + call("Report", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[" + plain(t, b.PlayerB) + " won](" + call("Report", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Draw](" + call("Report", "betID", id, "result", ResultDraw) + ")\n\n")
		if (b.ReportA == "") != (b.ReportB == "") {
			when := b.FirstReportAt.Add(ReportWindow)
			sb.WriteString("_One player has reported. The other has until " + when.UTC().Format(time.RFC822) +
				" to answer, then either player can [⚖️ send it to the judges](" + call("Escalate", "betID", id) + ")._\n")
		}
	case StatusDisputed:
		sb.WriteString("### ⚖️ Judges are voting\n\n")
		sb.WriteString("Players disagree. Judges (table members with no money in this bet) decide. ")
		need := len(b.Judges)/2 + 1
		sb.WriteString("A result needs **" + strconv.Itoa(need) + " of " + strconv.Itoa(len(b.Judges)) + "** votes. ")
		sb.WriteString("Voting closes " + b.Deadline.UTC().Format(time.RFC822) + ".\n\n")
		sb.WriteString("Votes so far: " + plain(t, b.PlayerA) + " won **" + strconv.Itoa(b.countVotes(ResultA)) + "** · " + plain(t, b.PlayerB) + " won **" +
			strconv.Itoa(b.countVotes(ResultB)) + "** · Draw **" + strconv.Itoa(b.countVotes(ResultDraw)) + "**\n\n")
		sb.WriteString("Judges: [Vote " + plain(t, b.PlayerA) + " won](" + call("Vote", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[Vote " + plain(t, b.PlayerB) + " won](" + call("Vote", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Vote draw](" + call("Vote", "betID", id, "result", ResultDraw) + ")\n\n")
		sb.WriteString("_No majority by the deadline? Anyone can [refund everyone](" + call("ExpireDispute", "betID", id) + ")._\n")
	}

	if b.Status == StatusOpen {
		preview := t.judgesFor(b.PlayerA, b.PlayerB)
		sb.WriteString("\n### ⚖️ Judges if accepted\n\n")
		if len(preview) == 0 {
			sb.WriteString("_Nobody else is at this table, so a disagreement would be refunded._\n")
		}
		for _, j := range preview {
			sb.WriteString("- " + who(t, j) + "\n")
		}
	}

	if len(b.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_Fixed when the bet was accepted. Only used if the players disagree._\n\n")
		for _, j := range b.Judges {
			vote := "not voted"
			if v, ok := b.Votes.Get(j.String()).(string); ok {
				vote = result(t, b, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}

	if len(b.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, p := range b.Payouts {
			sb.WriteString("| " + who(t, p.To) + " | " + gnot(p.Amount, false) + " | " + p.Why + " |\n")
		}
	}
	return sb.String()
}

type row struct {
	addr address
	s    *Stats
}

func renderPool(p *Pool) string {
	var sb strings.Builder
	id := strconv.Itoa(p.ID)
	t := mustTable(p.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🃏 " + escape(p.Title) + "\n\n")
	sb.WriteString("**Status: " + poolBadge(t, p) + "**\n\n")
	if p.FewJudges {
		sb.WriteString("> ⚠️ This game was started with fewer than 3 judges. If players disagree, very few people decide the result. Play with people you trust.\n\n")
	}
	n := int64(len(p.Players))
	sb.WriteString("Stake **" + gnot(p.Stake, false) + "** each · bond " + gnot(p.Bond, false) + " each · pot **" + gnot(n*p.Stake, false) + "**\n\n")

	sb.WriteString("Payout: ")
	for i, sh := range p.Shares {
		if i > 0 {
			sb.WriteString(" · ")
		}
		sb.WriteString(placeName(i) + " " + strconv.FormatInt(sh, 10) + "%")
	}
	sb.WriteString("\n\n## Players\n\n| Player | Joined | Reported |\n|---|---|---|\n")
	for _, a := range p.Players {
		joined := "⏳"
		if p.Joined.Has(a.String()) {
			joined = "✅"
		}
		rep := "—"
		if v, ok := p.Reports.Get(a.String()).(string); ok {
			rep = rankingText(t, p, v)
		}
		sb.WriteString("| " + who(t, a) + " | " + joined + " | " + rep + " |\n")
	}

	switch p.Status {
	case StatusOpen:
		sb.WriteString("\n[✅ Join and lock " + gnot(p.Stake+p.Bond, false) + "](" +
			callSend("JoinPool", strconv.FormatInt(p.Stake+p.Bond, 10)+"ugnot", "poolID", id) + ") · ")
		sb.WriteString("[❌ Cancel (creator)](" + call("CancelPool", "poolID", id) + ")\n")
	case StatusLive:
		sb.WriteString("\nPlayers: [📝 Report the finishing order](" + call("ReportPool", "poolID", id) + ") ")
		sb.WriteString("_(" + strconv.Itoa(len(p.Shares)) + " name(s), best first, e.g. `" + exampleRanking(t, p) + "`)_\n")
	case StatusDisputed:
		sb.WriteString("\n### ⚖️ Judges are voting\n\nPlayers disagree. Judges: [vote the order](" + call("VotePool", "poolID", id) + ") · ")
		sb.WriteString("voting closes " + p.Deadline.UTC().Format(time.RFC822) + ".\n")
	}

	if len(p.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_The table members who didn't play. Only used if players disagree._\n\n")
		for _, j := range p.Judges {
			vote := "not voted"
			if v, ok := p.Votes.Get(j.String()).(string); ok {
				vote = rankingText(t, p, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}
	if len(p.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, x := range p.Payouts {
			sb.WriteString("| " + who(t, x.To) + " | " + gnot(x.Amount, false) + " | " + x.Why + " |\n")
		}
	}
	return sb.String()
}

func rankingText(t *Table, p *Pool, r string) string {
	var parts []string
	for i, a := range p.rankingAddrs(r) {
		parts = append(parts, placeName(i)+" "+plain(t, a))
	}
	return strings.Join(parts, ", ")
}

func exampleRanking(t *Table, p *Pool) string {
	var names []string
	for i := 0; i < len(p.Shares) && i < len(p.Players); i++ {
		names = append(names, nameOrAddr(t, p.Players[i]))
	}
	return strings.Join(names, ",")
}

func poolBadge(t *Table, p *Pool) string {
	switch p.Status {
	case StatusOpen:
		return "🟡 " + strconv.Itoa(p.Joined.Size()) + "/" + strconv.Itoa(len(p.Players)) + " joined"
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		order := p.rankingAddrs(p.Final)
		if len(order) > 0 {
			return "✅ " + plain(t, order[0]) + " won"
		}
		return "✅ settled"
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return p.Status.String()
}

// nextStep tells visitors what the bet is waiting for.
func nextStep(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "Waiting for " + plain(t, b.PlayerB) + " to accept and lock " + gnot(b.Stake+b.Bond, false) + "."
	case StatusLive:
		switch {
		case b.ReportA == "" && b.ReportB == "":
			return "Game on! After the game, both " + plain(t, b.PlayerA) + " and " + plain(t, b.PlayerB) + " report the result."
		case b.ReportA == "":
			return "Waiting for " + plain(t, b.PlayerA) + " to report."
		default:
			return "Waiting for " + plain(t, b.PlayerB) + " to report."
		}
	case StatusDisputed:
		return "The players disagree. Judges, it's your call."
	}
	return ""
}

// headToHead counts settled results between two players at a table,
// from a's point of view: a's wins, b's wins, draws.
func headToHead(t *Table, a, b address) (int, int, int) {
	aw, bw, dr := 0, 0, 0
	for _, id := range t.BetIDs {
		x := mustBet(id)
		if x.Status != StatusSettled {
			continue
		}
		var winner address
		switch x.Final {
		case ResultA:
			winner = x.PlayerA
		case ResultB:
			winner = x.PlayerB
		}
		pair := (x.PlayerA == a && x.PlayerB == b) || (x.PlayerA == b && x.PlayerB == a)
		if !pair {
			continue
		}
		switch winner {
		case a:
			aw++
		case b:
			bw++
		default:
			dr++
		}
	}
	return aw, bw, dr
}

func rematchTitle(title string) string {
	if !strings.HasPrefix(title, "Rematch: ") {
		title = "Rematch: " + title
	}
	if len(title) > 140 {
		title = title[:140]
	}
	return title
}

func nameOrAddr(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return n
	}
	return a.String()
}

func count(n int, word string) string {
	if n == 1 {
		return "**1** " + word
	}
	return "**" + strconv.Itoa(n) + "** " + word + "s"
}

// challenge links to CreateBet with the table and opponent filled in.
func challenge(t *Table, a address) string {
	return call("CreateBet", "tableID", strconv.Itoa(t.ID), "opponentName", nameOrAddr(t, a))
}

// ---------------------------------------------------------------------------
// Formatting helpers

func statusBadge(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "🟡 waiting for " + plain(t, b.PlayerB)
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		return "✅ settled: " + result(t, b, b.Final)
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return b.Status.String()
}

// result describes a reported/voted result using the players' nicknames.
func result(t *Table, b *Bet, r string) string {
	switch r {
	case ResultA:
		return plain(t, b.PlayerA) + " won"
	case ResultB:
		return plain(t, b.PlayerB) + " won"
	}
	return showReport(r)
}

// plain is a nickname (or short address) without markdown, for link text.
func plain(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return escape(n)
	}
	s := a.String()
	return s[:7] + "…" + s[len(s)-4:]
}

func showReport(r string) string {
	switch r {
	case ResultA:
		return "A won"
	case ResultB:
		return "B won"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64, signed bool) string {
	sign := ""
	if u < 0 {
		sign = "-"
		u = -u
	} else if signed && u > 0 {
		sign = "+"
	}
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		s += "." + strings.TrimRight(f, "0")
	}
	return sign + s + " GNOT"
}

// who shows a member's nickname at a table, falling back to a short address.
func who(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return "**" + escape(n) + "**"
	}
	return short(a)
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:7] + "…" + s[len(s)-4:] + "`"
}

func escape(s string) string {
	r := strings.NewReplacer("|", "\\|", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "\n", " ")
	return r.Replace(s)
}

func prefix() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func home() string           { return prefix() }
func page(sub string) string { return prefix() + ":" + sub }

// call builds a gnoweb transaction link: /r/...$help&func=Fn&k=v
func call(fn string, kv ...string) string {
	return callSend(fn, "", kv...)
}

func callSend(fn, send string, kv ...string) string {
	q := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		q.Add(kv[i], kv[i+1])
	}
	if send != "" {
		q.Add(".send", send)
	}
	link := prefix() + "$help&func=" + fn
	if enc := q.Encode(); enc != "" {
		link += "&" + enc
	}
	return link
}

// Package tavernwagers lets friend groups ("tables") bet on anything with each other.
//
// How it works:
//   - A table is an invite-only group of friends.
//   - Two players lock the same stake into the realm before the game,
//     plus a 10% honesty bond.
//   - After the game, both players report the result. If they agree, the
//     realm pays out instantly and both bonds come back.
//   - If they disagree, every other table member becomes a judge. Judges
//     have no money in the bet, so they have no reason to lie. As soon as
//     a strict majority of judges agree, the bet settles.
//   - A player whose report loses the vote forfeits their bond. Half goes
//     to the honest player, half to the judges who voted with the majority.
//     Majority judges also split a 1% fee from the pot for showing up.
//   - If the judges can't reach a majority before the deadline, everyone
//     is refunded in full.
//
// The realm takes no cut: every coin that goes in comes back out to the
// players and judges.
package tavernwagers

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	ResultA    = "a"    // player A won
	ResultB    = "b"    // player B won
	ResultDraw = "draw" // draw, stakes go back

	MinStake int64 = 10_000 // 0.01 GNOT

	ReportWindow = 24 * time.Hour // how long a player has to answer the other's report
	VoteWindow   = 48 * time.Hour // how long judges have to vote
)

type BetStatus int

const (
	StatusOpen      BetStatus = iota // waiting for player B to accept
	StatusLive                       // both staked, waiting for reports
	StatusDisputed                   // players disagree, judges voting
	StatusSettled                    // paid out
	StatusCancelled                  // cancelled before B accepted
	StatusRefunded                   // judges could not decide, everyone refunded
)

func (s BetStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusLive:
		return "live"
	case StatusDisputed:
		return "disputed"
	case StatusSettled:
		return "settled"
	case StatusCancelled:
		return "cancelled"
	case StatusRefunded:
		return "refunded"
	}
	return "unknown"
}

// Stats is one member's record at a table.
type Stats struct {
	Net          int64 // ugnot won minus ugnot lost
	Wins         int
	Losses       int
	Draws        int
	DisputesLost int // times this player's report lost a judges' vote
	Judged       int // times this member voted with the majority as a judge
}

type Table struct {
	ID      int
	Name    string
	Owner   address
	Members []address
	Stats   *avl.Tree // address -> *Stats
	Names   *avl.Tree // address -> nickname
	BetIDs  []int
	PoolIDs []int
	Created time.Time
}

type Payout struct {
	To     address
	Amount int64
	Why    string
}

type Bet struct {
	ID      int
	TableID int
	Title   string
	PlayerA address
	PlayerB address
	Stake   int64 // per player
	Bond    int64 // per player
	Status  BetStatus

	ReportA       string
	ReportB       string
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> result string
	Deadline time.Time // voting deadline when disputed

	Final   string
	Payouts []Payout
	Created time.Time
}

var (
	tables   avl.Tree // id -> *Table
	bets     avl.Tree // id -> *Bet
	tableSeq int
	betSeq   int

	totalLocked  int64 // ugnot locked in accepted bets, all time
	totalSettled int   // bets settled (paid out to a winner or draw)
)

// ---------------------------------------------------------------------------
// Tables

// CreateTable opens a new table. The caller becomes its owner and first
// member, shown under the given nickname.
func CreateTable(cur realm, name string, nickname string) int {
	caller := cur.Previous().Address()
	name = strings.TrimSpace(name)
	require(name != "", "table name required")
	require(len(name) <= 64, "table name too long (max 64)")
	require(printable(name), "table name has invalid characters")

	tableSeq++
	t := &Table{
		ID:      tableSeq,
		Name:    name,
		Owner:   caller,
		Members: []address{caller},
		Stats:   avl.NewTree(),
		Names:   avl.NewTree(),
		Created: time.Now(),
	}
	t.setName(caller, nickname)
	tables.Set(strconv.Itoa(t.ID), t)
	return t.ID
}

// AddMember invites a friend to a table under a nickname. Only the table
// owner can do this. Members can change their own nickname later.
func AddMember(cur realm, tableID int, member address, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can add members")
	require(member.IsValid(), "invalid address")
	require(!t.isMember(member), "already a member")
	require(len(t.Members) < 50, "table is full (max 50)")
	t.setName(member, nickname) // validate the nickname before changing anything
	t.Members = append(t.Members, member)
}

// SetNickname changes how you appear at a table.
func SetNickname(cur realm, tableID int, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(t.isMember(caller), "you are not a member of this table")
	t.setName(caller, nickname)
}

// ---------------------------------------------------------------------------
// Bets

// CreateBet proposes a bet against another table member and locks your stake.
// opponent is their nickname at the table (or their g1... address).
// Send exactly stake + 10% bond, e.g. stake 1000000 -> send 1100000ugnot.
// You are player A, the opponent is player B. The judges are fixed when
// the bet is accepted: every other member of the table at that moment.
func CreateBet(cur realm, tableID int, title string, opponentName string, stake int64) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "bet title required")
	require(len(title) <= 140, "bet title too long (max 140)")
	require(printable(title), "bet title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	opponent := t.resolve(opponentName)
	require(opponent != caller, "you can't bet against yourself")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	bond := stake / 10
	requireSent(stake + bond)

	betSeq++
	b := &Bet{
		ID:      betSeq,
		TableID: tableID,
		Title:   title,
		PlayerA: caller,
		PlayerB: opponent,
		Stake:   stake,
		Bond:    bond,
		Status:  StatusOpen,
		Votes:   avl.NewTree(),
		Created: time.Now(),
	}
	bets.Set(strconv.Itoa(b.ID), b)
	t.BetIDs = append(t.BetIDs, b.ID)
	return b.ID
}

// AcceptBet is called by player B to match the stake and bond.
func AcceptBet(cur realm, betID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	require(caller == b.PlayerB, "only the challenged player can accept")
	requireSent(b.Stake + b.Bond)
	b.Status = StatusLive
	b.Judges = mustTable(b.TableID).judgesFor(b.PlayerA, b.PlayerB)
	totalLocked += 2 * (b.Stake + b.Bond)
}

// CancelBet lets player A take the bet back before B accepts it.
func CancelBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "only open bets can be cancelled")
	require(caller == b.PlayerA, "only the player who created the bet can cancel it")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "cancelled, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// Report is how each player says who won: "a", "b" or "draw".
// If both players report the same result, the bet pays out right away.
// If they disagree, it goes to the judges.
func Report(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	result = normalizeResult(result)

	switch caller {
	case b.PlayerA:
		require(b.ReportA == "", "you already reported")
		b.ReportA = result
	case b.PlayerB:
		require(b.ReportB == "", "you already reported")
		b.ReportB = result
	default:
		panic("only the two players can report")
	}

	if b.ReportA == "" || b.ReportB == "" {
		b.FirstReportAt = time.Now()
		return
	}

	if b.ReportA == b.ReportB {
		b.settle(b.ReportA, nil)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
		return
	}

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Escalate sends a bet to the judges when one player reported and the
// other went quiet for longer than the report window.
func Escalate(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	require(caller == b.PlayerA || caller == b.PlayerB, "only the players can escalate")
	require((b.ReportA == "") != (b.ReportB == ""), "escalate needs exactly one report")
	require(time.Now().After(b.FirstReportAt.Add(ReportWindow)), "the other player still has time to report")

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Vote is for judges of a disputed bet: "a", "b" or "draw".
// The bet settles the moment one result has a strict majority of judges.
func Vote(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(b.isJudge(caller), "you are not a judge on this bet")
	require(!b.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(b.Deadline), "voting is closed")
	result = normalizeResult(result)

	b.Votes.Set(caller.String(), result)

	if b.countVotes(result)*2 > len(b.Judges) {
		var majority []address
		for _, j := range b.Judges {
			if v, ok := b.Votes.Get(j.String()).(string); ok && v == result {
				majority = append(majority, j)
			}
		}
		b.settle(result, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// ExpireDispute refunds everyone if the judges failed to reach a majority
// before the deadline. Anyone can call it.
func ExpireDispute(cur realm, betID int) {
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(time.Now().After(b.Deadline), "voting is still open")
	b.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement logic (pure bookkeeping, no coins move here)

// openDispute snapshots the judges. It returns false if the bet had to be
// refunded instead (a table with no possible judges).
func (b *Bet) openDispute() bool {
	if len(b.Judges) == 0 {
		b.refundAll("no judges at this table")
		return false
	}
	b.Status = StatusDisputed
	b.Deadline = time.Now().Add(VoteWindow)
	return true
}

func (b *Bet) refundAll(why string) {
	b.Status = StatusRefunded
	each := b.Stake + b.Bond
	b.Payouts = []Payout{
		{b.PlayerA, each, why + ", refund"},
		{b.PlayerB, each, why + ", refund"},
	}
}

// settle fills in b.Payouts for a final result and updates the leaderboard.
// majority is nil when the players agreed (no judges involved).
func (b *Bet) settle(final string, majority []address) {
	b.Status = StatusSettled
	totalSettled++
	b.Final = final
	pot := 2 * b.Stake

	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = 2 * (b.Stake / 100) // 1% of the pot, always even
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, minus the judges' fee.
	switch final {
	case ResultA:
		add(b.PlayerA, pot-fee, "won the pot")
	case ResultB:
		add(b.PlayerB, pot-fee, "won the pot")
	case ResultDraw:
		add(b.PlayerA, b.Stake-fee/2, "draw, stake back")
		add(b.PlayerB, b.Stake-fee/2, "draw, stake back")
	}

	// 2. Honesty bonds.
	forfeited := int64(0)
	var honest []address
	t := mustTable(b.TableID)
	players := []address{b.PlayerA, b.PlayerB}
	reports := []string{b.ReportA, b.ReportB}
	for i := range players {
		if !disputed || reports[i] == final {
			add(players[i], b.Bond, "bond back")
			if disputed {
				honest = append(honest, players[i])
			}
		} else {
			forfeited += b.Bond
			t.stats(players[i]).DisputesLost++
		}
	}

	// 3. Forfeited bonds: half to the honest player(s), half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liar's bond", add)
		} else {
			judgePool += forfeited
		}
	}

	// 4. Judges who voted with the majority split their pool.
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
		}
	}

	b.Payouts = payouts

	// Leaderboard: net result per person, relative to what they put in.
	deposit := b.Stake + b.Bond
	t.stats(b.PlayerA).Net += received(payouts, b.PlayerA) - deposit
	t.stats(b.PlayerB).Net += received(payouts, b.PlayerB) - deposit
	for _, j := range majority {
		t.stats(j).Net += received(payouts, j)
	}
	switch final {
	case ResultA:
		t.stats(b.PlayerA).Wins++
		t.stats(b.PlayerB).Losses++
	case ResultB:
		t.stats(b.PlayerB).Wins++
		t.stats(b.PlayerA).Losses++
	case ResultDraw:
		t.stats(b.PlayerA).Draws++
		t.stats(b.PlayerB).Draws++
	}
}

// split divides amount evenly; the remainder goes to the first recipient so
// no dust is ever stuck in the realm.
func split(to []address, amount int64, why string, add func(address, int64, string)) {
	if len(to) == 0 || amount <= 0 {
		return
	}
	n := int64(len(to))
	each := amount / n
	rest := amount - each*n
	for i, a := range to {
		amt := each
		if i == 0 {
			amt += rest
		}
		add(a, amt, why)
	}
}

func received(payouts []Payout, who address) int64 {
	total := int64(0)
	for _, p := range payouts {
		if p.To == who {
			total += p.Amount
		}
	}
	return total
}

// pay moves the coins. The banker is always created inside the exported
// crossing function, from its own cur.
func pay(bk banker.Banker, from address, payouts []Payout) {
	for _, p := range payouts {
		bk.SendCoins(from, p.To, chain.Coins{{"ugnot", p.Amount}})
	}
}

// ---------------------------------------------------------------------------
// Read-only getters

func GetTableName(tableID int) string { return mustTable(tableID).Name }
func GetBetStatus(betID int) string   { return mustBet(betID).Status.String() }
func GetBetResult(betID int) string   { return mustBet(betID).Final }

func GetNet(tableID int, who address) int64 {
	t := mustTable(tableID)
	if v := t.Stats.Get(who.String()); v != nil {
		return v.(*Stats).Net
	}
	return 0
}

// ---------------------------------------------------------------------------
// Helpers

func (t *Table) isMember(a address) bool {
	for _, m := range t.Members {
		if m == a {
			return true
		}
	}
	return false
}

// setName validates and stores a nickname (unique per table). An empty
// nickname clears it, and the address is shown instead.
func (t *Table) setName(a address, nickname string) {
	nickname = strings.TrimSpace(nickname)
	if nickname == "" {
		t.Names.Remove(a.String())
		return
	}
	require(len(nickname) <= 24, "nickname too long (max 24)")
	for _, r := range nickname {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.'
		require(ok, "nickname can only use letters, numbers, spaces, - _ .")
	}
	lower := strings.ToLower(nickname)
	t.Names.Iterate("", "", func(k string, v any) bool {
		require(k == a.String() || strings.ToLower(v.(string)) != lower, "nickname already taken at this table")
		return false
	})
	t.Names.Set(a.String(), nickname)
}

// Nick returns a member's nickname, or "" if they have none.
func (t *Table) Nick(a address) string {
	if v := t.Names.Get(a.String()); v != nil {
		return v.(string)
	}
	return ""
}

// judgesFor lists every member except the two players.
func (t *Table) judgesFor(a, b address) []address {
	var judges []address
	for _, m := range t.Members {
		if m != a && m != b {
			judges = append(judges, m)
		}
	}
	return judges
}

// resolve finds a member by nickname (case-insensitive) or g1 address.
func (t *Table) resolve(who string) address {
	who = strings.TrimSpace(who)
	if strings.HasPrefix(who, "g1") {
		if a := address(who); a.IsValid() {
			require(t.isMember(a), "opponent is not a member of this table")
			return a
		}
	}
	lower := strings.ToLower(who)
	var found address
	t.Names.Iterate("", "", func(k string, v any) bool {
		if strings.ToLower(v.(string)) == lower {
			found = address(k)
			return true
		}
		return false
	})
	require(found != "" && t.isMember(found), "opponent is not a member of this table")
	return found
}

func (t *Table) stats(a address) *Stats {
	if v := t.Stats.Get(a.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	t.Stats.Set(a.String(), s)
	return s
}

func (b *Bet) isJudge(a address) bool {
	for _, j := range b.Judges {
		if j == a {
			return true
		}
	}
	return false
}

func (b *Bet) countVotes(result string) int {
	n := 0
	b.Votes.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == result {
			n++
		}
		return false
	})
	return n
}

// printable rejects control characters (newlines, tabs, etc.).
func printable(s string) bool {
	for _, r := range s {
		if r < 32 || r == 127 {
			return false
		}
	}
	return true
}

func normalizeResult(r string) string {
	r = strings.ToLower(strings.TrimSpace(r))
	require(r == ResultA || r == ResultB || r == ResultDraw, `result must be "a", "b" or "draw"`)
	return r
}

func requireSent(want int64) {
	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == "ugnot",
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
	require(sent[0].Amount == want,
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
}

func mustTable(id int) *Table {
	v := tables.Get(strconv.Itoa(id))
	if v == nil {
		panic("table not found")
	}
	return v.(*Table)
}

func mustBet(id int) *Bet {
	v := bets.Get(strconv.Itoa(id))
	if v == nil {
		panic("bet not found")
	}
	return v.(*Bet)
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

package tavernwagers

import (
	"strconv"
	"strings"
)

// Read-only JSON views for the web app (query them with vm/qeval).

// TablesJSON lists the newest 30 tables.
func TablesJSON() string {
	var items []string
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		items = append(items, tableSummary(v.(*Table)))
		return len(items) >= 30
	})
	return "[" + strings.Join(items, ",") + "]"
}

// StatsJSON returns all-time numbers for the home page.
func StatsJSON() string {
	return obj(
		"tables", itoa(tables.Size()),
		"bets", itoa(bets.Size()+pools.Size()),
		"settled", itoa(totalSettled),
		"locked", i64(totalLocked),
		"liarsCaught", itoa(liarsCaught),
		"biggestPot", i64(biggestPot),
		"judgesPaid", i64(judgesPaid),
	)
}

// MyTablesJSON lists the tables an address belongs to.
func MyTablesJSON(who address) string {
	var items []string
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Table)
		if t.isMember(who) {
			items = append(items, tableSummary(t))
		}
		return len(items) >= 50
	})
	return "[" + strings.Join(items, ",") + "]"
}

// TableJSON returns a table with its members, stats and newest 30 bets.
func TableJSON(tableID int) string {
	t := mustTable(tableID)
	var members []string
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		members = append(members, obj(
			"address", q(m.String()),
			"nick", q(t.Nick(m)),
			"net", i64(s.Net),
			"wins", itoa(s.Wins),
			"losses", itoa(s.Losses),
			"draws", itoa(s.Draws),
			"disputesLost", itoa(s.DisputesLost),
			"judged", itoa(s.Judged),
		))
	}
	var betList []string
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- {
		betList = append(betList, betJSON(mustBet(t.BetIDs[i])))
	}
	var poolList []string
	for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
		poolList = append(poolList, poolJSON(mustPool(t.PoolIDs[i])))
	}
	return obj(
		"id", itoa(t.ID),
		"name", q(t.Name),
		"owner", q(t.Owner.String()),
		"members", "["+strings.Join(members, ",")+"]",
		"bets", "["+strings.Join(betList, ",")+"]",
		"pools", "["+strings.Join(poolList, ",")+"]",
	)
}

// BetJSON returns one bet with reports, judges, votes and payouts.
func BetJSON(betID int) string {
	return betJSON(mustBet(betID))
}

// PoolJSON returns one group bet.
func PoolJSON(poolID int) string {
	return poolJSON(mustPool(poolID))
}

func poolJSON(p *Pool) string {
	var players []string
	for _, a := range p.Players {
		rep, _ := p.Reports.Get(a.String()).(string)
		players = append(players, obj(
			"address", q(a.String()),
			"joined", boolStr(p.Joined.Has(a.String())),
			"report", q(rep),
		))
	}
	var judges []string
	for _, j := range p.Judges {
		vote, _ := p.Votes.Get(j.String()).(string)
		judges = append(judges, obj("address", q(j.String()), "vote", q(vote)))
	}
	var shares []string
	for _, sh := range p.Shares {
		shares = append(shares, i64(sh))
	}
	var payouts []string
	for _, x := range p.Payouts {
		payouts = append(payouts, obj("to", q(x.To.String()), "amount", i64(x.Amount), "why", q(x.Why)))
	}
	deadline := ""
	if p.Status == StatusDisputed {
		deadline = p.Deadline.UTC().Format("2006-01-02T15:04:05Z")
	}
	firstReport := ""
	if !p.FirstReportAt.IsZero() {
		firstReport = p.FirstReportAt.UTC().Format("2006-01-02T15:04:05Z")
	}
	return obj(
		"id", itoa(p.ID),
		"kind", q("pool"),
		"tableId", itoa(p.TableID),
		"title", q(p.Title),
		"creator", q(p.Creator.String()),
		"stake", i64(p.Stake),
		"bond", i64(p.Bond),
		"shares", "["+strings.Join(shares, ",")+"]",
		"status", q(p.Status.String()),
		"players", "["+strings.Join(players, ",")+"]",
		"judges", "["+strings.Join(judges, ",")+"]",
		"final", q(p.Final),
		"fewJudges", boolStr(p.FewJudges),
		"deadline", q(deadline),
		"firstReportAt", q(firstReport),
		"payouts", "["+strings.Join(payouts, ",")+"]",
	)
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func tableSummary(t *Table) string {
	return obj(
		"id", itoa(t.ID),
		"name", q(t.Name),
		"owner", q(t.Owner.String()),
		"ownerNick", q(t.Nick(t.Owner)),
		"members", itoa(len(t.Members)),
		"bets", itoa(len(t.BetIDs)+len(t.PoolIDs)),
	)
}

func betJSON(b *Bet) string {
	var judges []string
	for _, j := range b.Judges {
		vote := ""
		if v, ok := b.Votes.Get(j.String()).(string); ok {
			vote = v
		}
		judges = append(judges, obj("address", q(j.String()), "vote", q(vote)))
	}
	var payouts []string
	for _, p := range b.Payouts {
		payouts = append(payouts, obj("to", q(p.To.String()), "amount", i64(p.Amount), "why", q(p.Why)))
	}
	deadline := ""
	if b.Status == StatusDisputed {
		deadline = b.Deadline.UTC().Format("2006-01-02T15:04:05Z")
	}
	firstReport := ""
	if !b.FirstReportAt.IsZero() {
		firstReport = b.FirstReportAt.UTC().Format("2006-01-02T15:04:05Z")
	}
	return obj(
		"id", itoa(b.ID),
		"tableId", itoa(b.TableID),
		"title", q(b.Title),
		"playerA", q(b.PlayerA.String()),
		"playerB", q(b.PlayerB.String()),
		"stake", i64(b.Stake),
		"bond", i64(b.Bond),
		"status", q(b.Status.String()),
		"reportA", q(b.ReportA),
		"reportB", q(b.ReportB),
		"final", q(b.Final),
		"judges", "["+strings.Join(judges, ",")+"]",
		"deadline", q(deadline),
		"firstReportAt", q(firstReport),
		"payouts", "["+strings.Join(payouts, ",")+"]",
	)
}

// obj builds a JSON object from key, raw-value pairs.
func obj(kv ...string) string {
	var parts []string
	for i := 0; i+1 < len(kv); i += 2 {
		parts = append(parts, q(kv[i])+":"+kv[i+1])
	}
	return "{" + strings.Join(parts, ",") + "}"
}

// q quotes a string as JSON. Inputs never contain control characters
// (titles and names are validated), so strconv.Quote is JSON-safe here.
func q(s string) string { return strconv.Quote(s) }

func itoa(n int) string  { return strconv.Itoa(n) }
func i64(n int64) string  { return strconv.FormatInt(n, 10) }

package tavernwagers

import (
	"chain/banker"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Group bets ("pools") are for games with more than two players: a poker
// night, a FIFA tournament, a pub quiz. Every player locks the same stake
// plus a 10% bond. The pot is paid out by finishing position, using shares
// chosen up front: "100" is winner-takes-all, "60,30,10" pays the top three.
//
// Nobody deals the result. Every player reports the finishing order; if
// they all agree, the pot pays out instantly. If anyone disagrees, the
// table members who did NOT play judge it, exactly like a 1v1 bet. Any
// player whose report loses the vote forfeits their bond.

const (
	MaxPoolPlayers = 20
	MinJudges      = 3 // recommended minimum judge panel for a group bet
)

type Pool struct {
	ID      int
	TableID int
	Title   string
	Creator address
	Players []address // invited players, creator first
	Joined  *avl.Tree // address -> true once their stake is locked
	Stake   int64
	Bond    int64
	Shares  []int64 // percent of the pot by finishing position, sums to 100
	Status  BetStatus

	Reports       *avl.Tree // address -> canonical ranking
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> canonical ranking
	Deadline time.Time

	FewJudges bool // created with fewer than MinJudges possible judges

	Final   string // canonical ranking: comma-separated addresses, 1st first
	Payouts []Payout
	Created time.Time
}

var (
	pools   avl.Tree // id -> *Pool
	poolSeq int
)

// CreatePool opens a group bet and locks your stake. players is a
// comma-separated list of the OTHER players' nicknames (or addresses).
// payout is the split of the pot by finishing position in percent:
// "100" (winner takes all) or e.g. "60,30,10". Send stake + 10% bond.
//
// Disputes are decided by the table members who are NOT playing. We want at
// least MinJudges of them, so no one or two people hold all the power. A
// table can still play with fewer (everyone wants in on poker night) by
// setting acceptFewJudges, which is shown as a warning on the game.
func CreatePool(cur realm, tableID int, title string, players string, stake int64, payout string, acceptFewJudges bool) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "title required")
	require(len(title) <= 140, "title too long (max 140)")
	require(printable(title), "title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	list := []address{caller}
	for _, name := range strings.Split(players, ",") {
		if strings.TrimSpace(name) == "" {
			continue
		}
		a := t.resolve(name)
		require(!containsAddr(list, a), "a player is listed twice")
		list = append(list, a)
	}
	require(len(list) >= 3, "a group bet needs at least 3 players (use a 1v1 bet for 2)")
	require(len(list) <= MaxPoolPlayers, "too many players (max 20)")

	shares := parseShares(payout)
	require(len(shares) < len(list), "more paid places than players minus one")

	judgesNow := len(t.Members) - len(list)
	require(judgesNow >= MinJudges || acceptFewJudges,
		"only "+strconv.Itoa(judgesNow)+" table member(s) left to judge disputes (we recommend "+strconv.Itoa(MinJudges)+
			"): leave some people out to judge, or set acceptFewJudges to play anyway")

	bond := stake / 10
	requireSent(stake + bond)

	poolSeq++
	p := &Pool{
		ID:      poolSeq,
		TableID: tableID,
		Title:   title,
		Creator: caller,
		Players: list,
		Joined:  avl.NewTree(),
		Stake:   stake,
		Bond:    bond,
		Shares:  shares,
		Status:  StatusOpen,
		Reports: avl.NewTree(),
		Votes:   avl.NewTree(),
		Created: time.Now(),

		FewJudges: judgesNow < MinJudges,
	}
	p.Joined.Set(caller.String(), true)
	pools.Set(strconv.Itoa(p.ID), p)
	t.PoolIDs = append(t.PoolIDs, p.ID)
	return p.ID
}

// JoinPool locks your stake + bond. The game goes live once every invited
// player has joined; the judges are fixed at that moment.
func JoinPool(cur realm, poolID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusOpen, "this group bet is not open")
	require(containsAddr(p.Players, caller), "you are not invited to this group bet")
	require(!p.Joined.Has(caller.String()), "you already joined")
	requireSent(p.Stake + p.Bond)
	p.Joined.Set(caller.String(), true)

	if p.Joined.Size() == len(p.Players) {
		p.Status = StatusLive
		t := mustTable(p.TableID)
		var judges []address
		for _, m := range t.Members {
			if !containsAddr(p.Players, m) {
				judges = append(judges, m)
			}
		}
		p.Judges = judges
		totalLocked += int64(len(p.Players)) * (p.Stake + p.Bond)
	}
}

// CancelPool lets the creator call it off before everyone joined.
// Everyone who already joined is refunded in full.
func CancelPool(cur realm, poolID int) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusOpen, "only open group bets can be cancelled")
	require(caller == p.Creator, "only the creator can cancel")
	p.Status = StatusCancelled
	for _, a := range p.Players {
		if p.Joined.Has(a.String()) {
			p.Payouts = append(p.Payouts, Payout{a, p.Stake + p.Bond, "cancelled, refund"})
		}
	}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// ReportPool is how each player reports the finishing order of the paid
// places, as comma-separated nicknames: "Alice,Bob" for 1st and 2nd.
// When every player has reported the same order, the pot pays out.
func ReportPool(cur realm, poolID int, ranking string) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusLive, "this group bet is not waiting for reports")
	require(containsAddr(p.Players, caller), "only players can report")
	require(!p.Reports.Has(caller.String()), "you already reported")
	r := p.canonical(ranking)
	p.Reports.Set(caller.String(), r)

	if p.Reports.Size() == 1 {
		p.FirstReportAt = time.Now()
	}
	if p.Reports.Size() < len(p.Players) {
		return
	}
	if p.allReportsAgree() {
		p.settle(r, nil)
	} else {
		p.openDispute()
	}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// EscalatePool sends the group bet to the judges when some players went
// quiet for longer than the report window.
func EscalatePool(cur realm, poolID int) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusLive, "this group bet is not waiting for reports")
	require(containsAddr(p.Players, caller), "only players can escalate")
	require(p.Reports.Size() > 0, "nobody has reported yet")
	require(time.Now().After(p.FirstReportAt.Add(ReportWindow)), "players still have time to report")
	p.openDispute()
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// VotePool is for judges of a disputed group bet. The order with a strict
// majority of judges wins.
func VotePool(cur realm, poolID int, ranking string) {
	caller := cur.Previous().Address()
	p := mustPool(poolID)
	require(p.Status == StatusDisputed, "this group bet is not in dispute")
	require(containsAddr(p.Judges, caller), "you are not a judge on this group bet")
	require(!p.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(p.Deadline), "voting is closed")
	r := p.canonical(ranking)
	p.Votes.Set(caller.String(), r)

	if countValue(p.Votes, r)*2 > len(p.Judges) {
		var majority []address
		for _, j := range p.Judges {
			if v, ok := p.Votes.Get(j.String()).(string); ok && v == r {
				majority = append(majority, j)
			}
		}
		p.settle(r, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
	}
}

// ExpirePool refunds everyone if the judges missed the deadline.
func ExpirePool(cur realm, poolID int) {
	p := mustPool(poolID)
	require(p.Status == StatusDisputed, "this group bet is not in dispute")
	require(time.Now().After(p.Deadline), "voting is still open")
	p.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), p.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement (bookkeeping only)

func (p *Pool) openDispute() {
	if len(p.Judges) == 0 {
		p.refundAll("no judges at this table")
		return
	}
	p.Status = StatusDisputed
	p.Deadline = time.Now().Add(VoteWindow)
}

func (p *Pool) refundAll(why string) {
	p.Status = StatusRefunded
	p.Payouts = nil
	for _, a := range p.Players {
		p.Payouts = append(p.Payouts, Payout{a, p.Stake + p.Bond, why + ", refund"})
	}
}

func (p *Pool) settle(final string, majority []address) {
	p.Status = StatusSettled
	p.Final = final
	totalSettled++
	t := mustTable(p.TableID)
	n := int64(len(p.Players))
	pot := n * p.Stake
	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = pot / 100
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, by finishing position. Rounding dust goes to 1st place.
	order := p.rankingAddrs(final)
	prize := pot - fee
	rest := int64(0)
	for i := 1; i < len(order); i++ {
		rest += prize * p.Shares[i] / 100
	}
	for i, a := range order {
		amt := prize * p.Shares[i] / 100
		if i == 0 {
			amt = prize - rest
		}
		add(a, amt, placeName(i)+" place")
	}

	// 2. Bonds.
	forfeited := int64(0)
	var honest []address
	for _, a := range p.Players {
		rep, _ := p.Reports.Get(a.String()).(string)
		if !disputed || rep == final {
			add(a, p.Bond, "bond back")
			if disputed {
				honest = append(honest, a)
			}
		} else {
			forfeited += p.Bond
			t.stats(a).DisputesLost++
			liarsCaught++
		}
	}

	// 3. Forfeited bonds: half to honest players, half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liars' bonds", add)
		} else {
			judgePool += forfeited
		}
	}
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
			t.stats(j).Net += received(payouts, j)
		}
	}
	p.Payouts = payouts
	if pot > biggestPot {
		biggestPot = pot
	}
	for _, j := range majority {
		judgesPaid += received(payouts, j)
	}

	// Leaderboard.
	deposit := p.Stake + p.Bond
	for _, a := range p.Players {
		s := t.stats(a)
		s.Net += received(payouts, a) - deposit
		if len(order) > 0 && a == order[0] {
			s.Wins++
		} else if !containsAddr(order, a) {
			s.Losses++
		}
	}
}

// ---------------------------------------------------------------------------
// Rankings

// canonical turns "Alice, bob" into "g1...,g1..." with exactly as many
// entries as there are paid places, all distinct players.
func (p *Pool) canonical(ranking string) string {
	t := mustTable(p.TableID)
	var out []string
	var seen []address
	for _, name := range strings.Split(ranking, ",") {
		if strings.TrimSpace(name) == "" {
			continue
		}
		a := t.resolve(name)
		require(containsAddr(p.Players, a), "everyone in the ranking must be a player")
		require(!containsAddr(seen, a), "a player is ranked twice")
		seen = append(seen, a)
		out = append(out, a.String())
	}
	require(len(out) == len(p.Shares), "rank exactly "+strconv.Itoa(len(p.Shares))+" player(s), best first")
	return strings.Join(out, ",")
}

func (p *Pool) rankingAddrs(r string) []address {
	var out []address
	for _, s := range strings.Split(r, ",") {
		if s != "" {
			out = append(out, address(s))
		}
	}
	return out
}

func (p *Pool) allReportsAgree() bool {
	first := ""
	agree := true
	p.Reports.Iterate("", "", func(_ string, v any) bool {
		if first == "" {
			first = v.(string)
		} else if v.(string) != first {
			agree = false
			return true
		}
		return false
	})
	return agree
}

func parseShares(payout string) []int64 {
	payout = strings.TrimSpace(payout)
	if payout == "" {
		payout = "100"
	}
	var shares []int64
	total := int64(0)
	for _, s := range strings.Split(payout, ",") {
		n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
		require(err == nil && n > 0, `payout must be percentages like "100" or "60,30,10"`)
		shares = append(shares, n)
		total += n
	}
	require(total == 100, "payout percentages must add up to 100")
	for i := 1; i < len(shares); i++ {
		require(shares[i] <= shares[i-1], "payout must not grow for lower places")
	}
	return shares
}

func placeName(i int) string {
	switch i {
	case 0:
		return "1st"
	case 1:
		return "2nd"
	case 2:
		return "3rd"
	}
	return strconv.Itoa(i+1) + "th"
}

func containsAddr(list []address, a address) bool {
	for _, x := range list {
		if x == a {
			return true
		}
	}
	return false
}

func countValue(tree *avl.Tree, want string) int {
	n := 0
	tree.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == want {
			n++
		}
		return false
	})
	return n
}

func mustPool(id int) *Pool {
	v := pools.Get(strconv.Itoa(id))
	if v == nil {
		panic("group bet not found")
	}
	return v.(*Pool)
}

// GetPoolStatus returns a group bet's status.
func GetPoolStatus(poolID int) string { return mustPool(poolID).Status.String() }

package tavernwagers

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// Render shows the realm's pages on gnoweb:
//
//	""         home: how it works + all tables
//	"table/N"  a table: members, leaderboard, bets
//	"bet/N"    a bet: players, reports, votes, payouts, actions
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 2 {
		if _, err := strconv.Atoi(parts[1]); err == nil {
			switch parts[0] {
			case "table":
				if v := tables.Get(parts[1]); v != nil {
					return renderTable(v.(*Table))
				}
				return "# Table not found\n\n[Back home](" + home() + ")"
			case "bet":
				if v := bets.Get(parts[1]); v != nil {
					return renderBet(v.(*Bet))
				}
				return "# Bet not found\n\n[Back home](" + home() + ")"
			case "pool":
				if v := pools.Get(parts[1]); v != nil {
					return renderPool(v.(*Pool))
				}
				return "# Group bet not found\n\n[Back home](" + home() + ")"
			}
		}
	}
	return renderHome()
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# 🍺 Tavern Wagers\n\n")
	sb.WriteString("**Bet on anything with your friends. The money's locked upfront, neutral judges call it, and the winner gets paid automatically. No more \"I'll pay you later.\"**\n\n")
	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Open a table** and invite your friends.\n")
	sb.WriteString("2. **Make a bet** against a friend. Both players lock the same stake + a 10% honesty bond.\n")
	sb.WriteString("3. **Play** (chess, FIFA, D&D, anything).\n")
	sb.WriteString("4. **Both players report the result.** If you agree, you're paid instantly and get your bonds back.\n")
	sb.WriteString("5. **Disagree?** Everyone else at the table becomes a judge. They have no money in it, so they have no reason to lie. A strict majority decides.\n")
	sb.WriteString("6. **Lying costs you.** The player who loses the vote forfeits their bond: half to the honest player, half to the judges. Judges also split a 1% fee for showing up.\n")
	sb.WriteString("7. **No majority before the deadline?** Everyone is refunded in full.\n\n")
	sb.WriteString("The realm keeps nothing. Every coin that goes in comes back out to players and judges.\n\n")
	sb.WriteString("[➕ Open a new table](" + call("CreateTable") + ")\n\n")

	sb.WriteString(count(tables.Size(), "table") + " · " + count(bets.Size()+pools.Size(), "bet") + " · " +
		count(totalSettled, "settled bet") + " · **" + gnot(totalLocked, false) + "** locked all time · " +
		count(liarsCaught, "liar") + " caught 🚩 · biggest pot **" + gnot(biggestPot, false) + "**\n\n")

	sb.WriteString("## Tables\n\n")
	if tables.Size() == 0 {
		sb.WriteString("_No tables yet. Be the first._\n")
		return sb.String()
	}
	sb.WriteString("| Table | Members | Bets | Owner |\n|---|---|---|---|\n")
	shown := 0
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		shown++
		if shown > 30 {
			return true // newest 30 only
		}
		t := v.(*Table)
		sb.WriteString("| [" + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ") | " +
			strconv.Itoa(len(t.Members)) + " | " + strconv.Itoa(len(t.BetIDs)) + " | " + who(t, t.Owner) + " |\n")
		return false
	})
	return sb.String()
}

func renderTable(t *Table) string {
	var sb strings.Builder
	id := strconv.Itoa(t.ID)
	sb.WriteString("[← All tables](" + home() + ")\n\n")
	sb.WriteString("# 🍺 " + escape(t.Name) + "\n\n")
	sb.WriteString("Table #" + id + " · owner " + who(t, t.Owner) + " · " + strconv.Itoa(len(t.Members)) + " members\n\n")
	sb.WriteString("[🎲 New 1v1 bet](" + call("CreateBet", "tableID", id) + ") · ")
	sb.WriteString("[🃏 New group bet](" + call("CreatePool", "tableID", id, "payout", "100", "acceptFewJudges", "false") + ") · ")
	sb.WriteString("[👋 Add member (owner only)](" + call("AddMember", "tableID", id) + ") · ")
	sb.WriteString("[✏️ Change your nickname](" + call("SetNickname", "tableID", id) + ")\n\n")

	// Leaderboard, sorted by net winnings.
	sb.WriteString("## 🏆 Leaderboard\n\n")
	var rows []row
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		rows = append(rows, row{m, s})
	}
	for i := 1; i < len(rows); i++ { // insertion sort, highest net first
		for j := i; j > 0 && rows[j].s.Net > rows[j-1].s.Net; j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	sb.WriteString("| # | Member | Net | W | L | D | Disputes lost | Judged | |\n|---|---|---|---|---|---|---|---|---|\n")
	for i, r := range rows {
		liar := strconv.Itoa(r.s.DisputesLost)
		if r.s.DisputesLost > 0 {
			liar = "🚩 " + liar
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + who(t, r.addr) + " | " + gnot(r.s.Net, true) + " | " +
			strconv.Itoa(r.s.Wins) + " | " + strconv.Itoa(r.s.Losses) + " | " + strconv.Itoa(r.s.Draws) + " | " +
			liar + " | " + strconv.Itoa(r.s.Judged) + " | [🎲 Challenge](" + challenge(t, r.addr) + ") |\n")
	}

	if len(t.PoolIDs) > 0 {
		sb.WriteString("\n## 🃏 Group bets\n\n| Game | Players | Stake | Status |\n|---|---|---|---|\n")
		for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
			p := mustPool(t.PoolIDs[i])
			sb.WriteString("| [" + escape(p.Title) + "](" + page("pool/"+strconv.Itoa(p.ID)) + ") | " +
				strconv.Itoa(len(p.Players)) + " | " + gnot(p.Stake, false) + " | " + poolBadge(t, p) + " |\n")
		}
	}

	sb.WriteString("\n## 🎲 Bets\n\n")
	if len(t.BetIDs) == 0 {
		sb.WriteString("_No bets yet._\n")
		return sb.String()
	}
	sb.WriteString("| Bet | Players | Stake | Status |\n|---|---|---|---|\n")
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- { // newest 30
		b := mustBet(t.BetIDs[i])
		sb.WriteString("| [" + escape(b.Title) + "](" + page("bet/"+strconv.Itoa(b.ID)) + ") | " +
			who(t, b.PlayerA) + " vs " + who(t, b.PlayerB) + " | " + gnot(b.Stake, false) + " | " + statusBadge(t, b) + " |\n")
	}
	return sb.String()
}

func renderBet(b *Bet) string {
	var sb strings.Builder
	id := strconv.Itoa(b.ID)
	t := mustTable(b.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🎲 " + escape(b.Title) + "\n\n")
	sb.WriteString("**Status: " + statusBadge(t, b) + "**\n\n")
	if hint := nextStep(t, b); hint != "" {
		sb.WriteString("> 👉 " + hint + "\n\n")
	}

	sb.WriteString("| | Player A | Player B |\n|---|---|---|\n")
	sb.WriteString("| Who | " + who(t, b.PlayerA) + " | " + who(t, b.PlayerB) + " |\n")
	sb.WriteString("| Stake | " + gnot(b.Stake, false) + " | " + gnot(b.Stake, false) + " |\n")
	sb.WriteString("| Honesty bond | " + gnot(b.Bond, false) + " | " + gnot(b.Bond, false) + " |\n")
	sb.WriteString("| Reported | " + result(t, b, b.ReportA) + " | " + result(t, b, b.ReportB) + " |\n\n")
	sb.WriteString("Pot: **" + gnot(2*b.Stake, false) + "**\n\n")
	aw, bw, dr := headToHead(t, b.PlayerA, b.PlayerB)
	if aw+bw+dr > 0 {
		sb.WriteString("Head to head at this table: " + plain(t, b.PlayerA) + " **" + strconv.Itoa(aw) + "** · " +
			plain(t, b.PlayerB) + " **" + strconv.Itoa(bw) + "** · draws **" + strconv.Itoa(dr) + "**\n\n")
	}
	if b.Status == StatusSettled || b.Status == StatusRefunded {
		loser := b.PlayerA
		if b.Final == ResultA {
			loser = b.PlayerB
		}
		other := b.PlayerB
		if loser == b.PlayerB {
			other = b.PlayerA
		}
		sb.WriteString("[🔁 Run it back](" + callSend("CreateBet", strconv.FormatInt(b.Stake+b.Bond, 10)+"ugnot", "tableID", strconv.Itoa(t.ID),
			"title", rematchTitle(b.Title), "opponentName", nameOrAddr(t, other),
			"stake", strconv.FormatInt(b.Stake, 10)) + ") _(for " + plain(t, loser) + ")_\n\n")
	}

	send := strconv.FormatInt(b.Stake+b.Bond, 10) + "ugnot"
	switch b.Status {
	case StatusOpen:
		sb.WriteString("### Actions\n\n")
		sb.WriteString("- Player B: [✅ Accept and lock " + gnot(b.Stake+b.Bond, false) + "](" +
			callSend("AcceptBet", send, "betID", id) + ")\n")
		sb.WriteString("- Player A: [❌ Cancel and refund](" + call("CancelBet", "betID", id) + ")\n")
	case StatusLive:
		sb.WriteString("### Report the result\n\n")
		sb.WriteString("[" + plain(t, b.PlayerA) + " won](" + call("Report", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[" + plain(t, b.PlayerB) + " won](" + call("Report", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Draw](" + call("Report", "betID", id, "result", ResultDraw) + ")\n\n")
		if (b.ReportA == "") != (b.ReportB == "") {
			when := b.FirstReportAt.Add(ReportWindow)
			sb.WriteString("_One player has reported. The other has until " + when.UTC().Format(time.RFC822) +
				" to answer, then either player can [⚖️ send it to the judges](" + call("Escalate", "betID", id) + ")._\n")
		}
	case StatusDisputed:
		sb.WriteString("### ⚖️ Judges are voting\n\n")
		sb.WriteString("Players disagree. Judges (table members with no money in this bet) decide. ")
		need := len(b.Judges)/2 + 1
		sb.WriteString("A result needs **" + strconv.Itoa(need) + " of " + strconv.Itoa(len(b.Judges)) + "** votes. ")
		sb.WriteString("Voting closes " + b.Deadline.UTC().Format(time.RFC822) + ".\n\n")
		sb.WriteString("Votes so far: " + plain(t, b.PlayerA) + " won **" + strconv.Itoa(b.countVotes(ResultA)) + "** · " + plain(t, b.PlayerB) + " won **" +
			strconv.Itoa(b.countVotes(ResultB)) + "** · Draw **" + strconv.Itoa(b.countVotes(ResultDraw)) + "**\n\n")
		sb.WriteString("Judges: [Vote " + plain(t, b.PlayerA) + " won](" + call("Vote", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[Vote " + plain(t, b.PlayerB) + " won](" + call("Vote", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Vote draw](" + call("Vote", "betID", id, "result", ResultDraw) + ")\n\n")
		sb.WriteString("_No majority by the deadline? Anyone can [refund everyone](" + call("ExpireDispute", "betID", id) + ")._\n")
	}

	if b.Status == StatusOpen {
		preview := t.judgesFor(b.PlayerA, b.PlayerB)
		sb.WriteString("\n### ⚖️ Judges if accepted\n\n")
		if len(preview) == 0 {
			sb.WriteString("_Nobody else is at this table, so a disagreement would be refunded._\n")
		}
		for _, j := range preview {
			sb.WriteString("- " + who(t, j) + "\n")
		}
	}

	if len(b.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_Fixed when the bet was accepted. Only used if the players disagree._\n\n")
		for _, j := range b.Judges {
			vote := "not voted"
			if v, ok := b.Votes.Get(j.String()).(string); ok {
				vote = result(t, b, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}

	if len(b.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, p := range b.Payouts {
			sb.WriteString("| " + who(t, p.To) + " | " + gnot(p.Amount, false) + " | " + p.Why + " |\n")
		}
	}
	return sb.String()
}

type row struct {
	addr address
	s    *Stats
}

func renderPool(p *Pool) string {
	var sb strings.Builder
	id := strconv.Itoa(p.ID)
	t := mustTable(p.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🃏 " + escape(p.Title) + "\n\n")
	sb.WriteString("**Status: " + poolBadge(t, p) + "**\n\n")
	if p.FewJudges {
		sb.WriteString("> ⚠️ This game was started with fewer than 3 judges. If players disagree, very few people decide the result. Play with people you trust.\n\n")
	}
	n := int64(len(p.Players))
	sb.WriteString("Stake **" + gnot(p.Stake, false) + "** each · bond " + gnot(p.Bond, false) + " each · pot **" + gnot(n*p.Stake, false) + "**\n\n")

	sb.WriteString("Payout: ")
	for i, sh := range p.Shares {
		if i > 0 {
			sb.WriteString(" · ")
		}
		sb.WriteString(placeName(i) + " " + strconv.FormatInt(sh, 10) + "%")
	}
	sb.WriteString("\n\n## Players\n\n| Player | Joined | Reported |\n|---|---|---|\n")
	for _, a := range p.Players {
		joined := "⏳"
		if p.Joined.Has(a.String()) {
			joined = "✅"
		}
		rep := "—"
		if v, ok := p.Reports.Get(a.String()).(string); ok {
			rep = rankingText(t, p, v)
		}
		sb.WriteString("| " + who(t, a) + " | " + joined + " | " + rep + " |\n")
	}

	switch p.Status {
	case StatusOpen:
		sb.WriteString("\n[✅ Join and lock " + gnot(p.Stake+p.Bond, false) + "](" +
			callSend("JoinPool", strconv.FormatInt(p.Stake+p.Bond, 10)+"ugnot", "poolID", id) + ") · ")
		sb.WriteString("[❌ Cancel (creator)](" + call("CancelPool", "poolID", id) + ")\n")
	case StatusLive:
		sb.WriteString("\nPlayers: [📝 Report the finishing order](" + call("ReportPool", "poolID", id) + ") ")
		sb.WriteString("_(" + strconv.Itoa(len(p.Shares)) + " name(s), best first, e.g. `" + exampleRanking(t, p) + "`)_\n")
	case StatusDisputed:
		sb.WriteString("\n### ⚖️ Judges are voting\n\nPlayers disagree. Judges: [vote the order](" + call("VotePool", "poolID", id) + ") · ")
		sb.WriteString("voting closes " + p.Deadline.UTC().Format(time.RFC822) + ".\n")
	}

	if len(p.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_The table members who didn't play. Only used if players disagree._\n\n")
		for _, j := range p.Judges {
			vote := "not voted"
			if v, ok := p.Votes.Get(j.String()).(string); ok {
				vote = rankingText(t, p, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}
	if len(p.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, x := range p.Payouts {
			sb.WriteString("| " + who(t, x.To) + " | " + gnot(x.Amount, false) + " | " + x.Why + " |\n")
		}
	}
	return sb.String()
}

func rankingText(t *Table, p *Pool, r string) string {
	var parts []string
	for i, a := range p.rankingAddrs(r) {
		parts = append(parts, placeName(i)+" "+plain(t, a))
	}
	return strings.Join(parts, ", ")
}

func exampleRanking(t *Table, p *Pool) string {
	var names []string
	for i := 0; i < len(p.Shares) && i < len(p.Players); i++ {
		names = append(names, nameOrAddr(t, p.Players[i]))
	}
	return strings.Join(names, ",")
}

func poolBadge(t *Table, p *Pool) string {
	switch p.Status {
	case StatusOpen:
		return "🟡 " + strconv.Itoa(p.Joined.Size()) + "/" + strconv.Itoa(len(p.Players)) + " joined"
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		order := p.rankingAddrs(p.Final)
		if len(order) > 0 {
			return "✅ " + plain(t, order[0]) + " won"
		}
		return "✅ settled"
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return p.Status.String()
}

// nextStep tells visitors what the bet is waiting for.
func nextStep(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "Waiting for " + plain(t, b.PlayerB) + " to accept and lock " + gnot(b.Stake+b.Bond, false) + "."
	case StatusLive:
		switch {
		case b.ReportA == "" && b.ReportB == "":
			return "Game on! After the game, both " + plain(t, b.PlayerA) + " and " + plain(t, b.PlayerB) + " report the result."
		case b.ReportA == "":
			return "Waiting for " + plain(t, b.PlayerA) + " to report."
		default:
			return "Waiting for " + plain(t, b.PlayerB) + " to report."
		}
	case StatusDisputed:
		return "The players disagree. Judges, it's your call."
	}
	return ""
}

// headToHead counts settled results between two players at a table,
// from a's point of view: a's wins, b's wins, draws.
func headToHead(t *Table, a, b address) (int, int, int) {
	aw, bw, dr := 0, 0, 0
	for _, id := range t.BetIDs {
		x := mustBet(id)
		if x.Status != StatusSettled {
			continue
		}
		var winner address
		switch x.Final {
		case ResultA:
			winner = x.PlayerA
		case ResultB:
			winner = x.PlayerB
		}
		pair := (x.PlayerA == a && x.PlayerB == b) || (x.PlayerA == b && x.PlayerB == a)
		if !pair {
			continue
		}
		switch winner {
		case a:
			aw++
		case b:
			bw++
		default:
			dr++
		}
	}
	return aw, bw, dr
}

func rematchTitle(title string) string {
	if !strings.HasPrefix(title, "Rematch: ") {
		title = "Rematch: " + title
	}
	if len(title) > 140 {
		title = title[:140]
	}
	return title
}

func nameOrAddr(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return n
	}
	return a.String()
}

func count(n int, word string) string {
	if n == 1 {
		return "**1** " + word
	}
	return "**" + strconv.Itoa(n) + "** " + word + "s"
}

// challenge links to CreateBet with the table and opponent filled in.
func challenge(t *Table, a address) string {
	return call("CreateBet", "tableID", strconv.Itoa(t.ID), "opponentName", nameOrAddr(t, a))
}

// ---------------------------------------------------------------------------
// Formatting helpers

func statusBadge(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "🟡 waiting for " + plain(t, b.PlayerB)
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		return "✅ settled: " + result(t, b, b.Final)
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return b.Status.String()
}

// result describes a reported/voted result using the players' nicknames.
func result(t *Table, b *Bet, r string) string {
	switch r {
	case ResultA:
		return plain(t, b.PlayerA) + " won"
	case ResultB:
		return plain(t, b.PlayerB) + " won"
	}
	return showReport(r)
}

// plain is a nickname (or short address) without markdown, for link text.
func plain(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return escape(n)
	}
	s := a.String()
	return s[:7] + "…" + s[len(s)-4:]
}

func showReport(r string) string {
	switch r {
	case ResultA:
		return "A won"
	case ResultB:
		return "B won"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64, signed bool) string {
	sign := ""
	if u < 0 {
		sign = "-"
		u = -u
	} else if signed && u > 0 {
		sign = "+"
	}
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		s += "." + strings.TrimRight(f, "0")
	}
	return sign + s + " GNOT"
}

// who shows a member's nickname at a table, falling back to a short address.
func who(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return "**" + escape(n) + "**"
	}
	return short(a)
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:7] + "…" + s[len(s)-4:] + "`"
}

func escape(s string) string {
	r := strings.NewReplacer("|", "\\|", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "\n", " ")
	return r.Replace(s)
}

func prefix() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func home() string           { return prefix() }
func page(sub string) string { return prefix() + ":" + sub }

// call builds a gnoweb transaction link: /r/...$help&func=Fn&k=v
func call(fn string, kv ...string) string {
	return callSend(fn, "", kv...)
}

func callSend(fn, send string, kv ...string) string {
	q := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		q.Add(kv[i], kv[i+1])
	}
	if send != "" {
		q.Add(".send", send)
	}
	link := prefix() + "$help&func=" + fn
	if enc := q.Encode(); enc != "" {
		link += "&" + enc
	}
	return link
}

// Package tavernwagers lets friend groups ("tables") bet on anything with each other.
//
// How it works:
//   - A table is an invite-only group of friends.
//   - Two players lock the same stake into the realm before the game,
//     plus a 10% honesty bond.
//   - After the game, both players report the result. If they agree, the
//     realm pays out instantly and both bonds come back.
//   - If they disagree, every other table member becomes a judge. Judges
//     have no money in the bet, so they have no reason to lie. As soon as
//     a strict majority of judges agree, the bet settles.
//   - A player whose report loses the vote forfeits their bond. Half goes
//     to the honest player, half to the judges who voted with the majority.
//     Majority judges also split a 1% fee from the pot for showing up.
//   - If the judges can't reach a majority before the deadline, everyone
//     is refunded in full.
//
// The realm takes no cut: every coin that goes in comes back out to the
// players and judges.
package tavernwagers

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	ResultA    = "a"    // player A won
	ResultB    = "b"    // player B won
	ResultDraw = "draw" // draw, stakes go back

	MinStake int64 = 10_000 // 0.01 GNOT

	ReportWindow = 24 * time.Hour // how long a player has to answer the other's report
	VoteWindow   = 48 * time.Hour // how long judges have to vote
)

type BetStatus int

const (
	StatusOpen      BetStatus = iota // waiting for player B to accept
	StatusLive                       // both staked, waiting for reports
	StatusDisputed                   // players disagree, judges voting
	StatusSettled                    // paid out
	StatusCancelled                  // cancelled before B accepted
	StatusRefunded                   // judges could not decide, everyone refunded
)

func (s BetStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusLive:
		return "live"
	case StatusDisputed:
		return "disputed"
	case StatusSettled:
		return "settled"
	case StatusCancelled:
		return "cancelled"
	case StatusRefunded:
		return "refunded"
	}
	return "unknown"
}

// Stats is one member's record at a table.
type Stats struct {
	Net          int64 // ugnot won minus ugnot lost
	Wins         int
	Losses       int
	Draws        int
	DisputesLost int // times this player's report lost a judges' vote
	Judged       int // times this member voted with the majority as a judge
}

type Table struct {
	ID      int
	Name    string
	Owner   address
	Members []address
	Stats   *avl.Tree // address -> *Stats
	Names   *avl.Tree // address -> nickname
	BetIDs  []int
	PoolIDs []int
	Created time.Time
}

type Payout struct {
	To     address
	Amount int64
	Why    string
}

type Bet struct {
	ID      int
	TableID int
	Title   string
	PlayerA address
	PlayerB address
	Stake   int64 // per player
	Bond    int64 // per player
	Status  BetStatus

	ReportA       string
	ReportB       string
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> result string
	Deadline time.Time // voting deadline when disputed

	Final   string
	Payouts []Payout
	Created time.Time
}

var (
	tables   avl.Tree // id -> *Table
	bets     avl.Tree // id -> *Bet
	tableSeq int
	betSeq   int

	totalLocked  int64 // ugnot locked in accepted bets, all time
	totalSettled int   // bets settled (paid out to a winner or draw)
	liarsCaught  int   // reports that lost a judges' vote
	biggestPot   int64 // largest pot ever settled, ugnot
	judgesPaid   int64 // ugnot paid to judges, all time
)

// ---------------------------------------------------------------------------
// Tables

// CreateTable opens a new table. The caller becomes its owner and first
// member, shown under the given nickname.
func CreateTable(cur realm, name string, nickname string) int {
	caller := cur.Previous().Address()
	name = strings.TrimSpace(name)
	require(name != "", "table name required")
	require(len(name) <= 64, "table name too long (max 64)")
	require(printable(name), "table name has invalid characters")

	tableSeq++
	t := &Table{
		ID:      tableSeq,
		Name:    name,
		Owner:   caller,
		Members: []address{caller},
		Stats:   avl.NewTree(),
		Names:   avl.NewTree(),
		Created: time.Now(),
	}
	t.setName(caller, nickname)
	tables.Set(strconv.Itoa(t.ID), t)
	return t.ID
}

// AddMember invites a friend to a table under a nickname. Only the table
// owner can do this. Members can change their own nickname later.
func AddMember(cur realm, tableID int, member address, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can add members")
	require(member.IsValid(), "invalid address")
	require(!t.isMember(member), "already a member")
	require(len(t.Members) < 50, "table is full (max 50)")
	t.setName(member, nickname) // validate the nickname before changing anything
	t.Members = append(t.Members, member)
}

// SetNickname changes how you appear at a table.
func SetNickname(cur realm, tableID int, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(t.isMember(caller), "you are not a member of this table")
	t.setName(caller, nickname)
}

// ---------------------------------------------------------------------------
// Bets

// CreateBet proposes a bet against another table member and locks your stake.
// opponent is their nickname at the table (or their g1... address).
// Send exactly stake + 10% bond, e.g. stake 1000000 -> send 1100000ugnot.
// You are player A, the opponent is player B. The judges are fixed when
// the bet is accepted: every other member of the table at that moment.
func CreateBet(cur realm, tableID int, title string, opponentName string, stake int64) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "bet title required")
	require(len(title) <= 140, "bet title too long (max 140)")
	require(printable(title), "bet title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	opponent := t.resolve(opponentName)
	require(opponent != caller, "you can't bet against yourself")
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")

	bond := stake / 10
	requireSent(stake + bond)

	betSeq++
	b := &Bet{
		ID:      betSeq,
		TableID: tableID,
		Title:   title,
		PlayerA: caller,
		PlayerB: opponent,
		Stake:   stake,
		Bond:    bond,
		Status:  StatusOpen,
		Votes:   avl.NewTree(),
		Created: time.Now(),
	}
	bets.Set(strconv.Itoa(b.ID), b)
	t.BetIDs = append(t.BetIDs, b.ID)
	return b.ID
}

// AcceptBet is called by player B to match the stake and bond.
func AcceptBet(cur realm, betID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	require(caller == b.PlayerB, "only the challenged player can accept")
	requireSent(b.Stake + b.Bond)
	b.Status = StatusLive
	b.Judges = mustTable(b.TableID).judgesFor(b.PlayerA, b.PlayerB)
	totalLocked += 2 * (b.Stake + b.Bond)
}

// CancelBet lets player A take the bet back before B accepts it.
func CancelBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "only open bets can be cancelled")
	require(caller == b.PlayerA, "only the player who created the bet can cancel it")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "cancelled, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// Report is how each player says who won: "a", "b" or "draw".
// If both players report the same result, the bet pays out right away.
// If they disagree, it goes to the judges.
func Report(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	result = normalizeResult(result)

	switch caller {
	case b.PlayerA:
		require(b.ReportA == "", "you already reported")
		b.ReportA = result
	case b.PlayerB:
		require(b.ReportB == "", "you already reported")
		b.ReportB = result
	default:
		panic("only the two players can report")
	}

	if b.ReportA == "" || b.ReportB == "" {
		b.FirstReportAt = time.Now()
		return
	}

	if b.ReportA == b.ReportB {
		b.settle(b.ReportA, nil)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
		return
	}

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Escalate sends a bet to the judges when one player reported and the
// other went quiet for longer than the report window.
func Escalate(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	require(caller == b.PlayerA || caller == b.PlayerB, "only the players can escalate")
	require((b.ReportA == "") != (b.ReportB == ""), "escalate needs exactly one report")
	require(time.Now().After(b.FirstReportAt.Add(ReportWindow)), "the other player still has time to report")

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Vote is for judges of a disputed bet: "a", "b" or "draw".
// The bet settles the moment one result has a strict majority of judges.
func Vote(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(b.isJudge(caller), "you are not a judge on this bet")
	require(!b.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(b.Deadline), "voting is closed")
	result = normalizeResult(result)

	b.Votes.Set(caller.String(), result)

	if b.countVotes(result)*2 > len(b.Judges) {
		var majority []address
		for _, j := range b.Judges {
			if v, ok := b.Votes.Get(j.String()).(string); ok && v == result {
				majority = append(majority, j)
			}
		}
		b.settle(result, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// ExpireDispute refunds everyone if the judges failed to reach a majority
// before the deadline. Anyone can call it.
func ExpireDispute(cur realm, betID int) {
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(time.Now().After(b.Deadline), "voting is still open")
	b.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement logic (pure bookkeeping, no coins move here)

// openDispute snapshots the judges. It returns false if the bet had to be
// refunded instead (a table with no possible judges).
func (b *Bet) openDispute() bool {
	if len(b.Judges) == 0 {
		b.refundAll("no judges at this table")
		return false
	}
	b.Status = StatusDisputed
	b.Deadline = time.Now().Add(VoteWindow)
	return true
}

func (b *Bet) refundAll(why string) {
	b.Status = StatusRefunded
	each := b.Stake + b.Bond
	b.Payouts = []Payout{
		{b.PlayerA, each, why + ", refund"},
		{b.PlayerB, each, why + ", refund"},
	}
}

// settle fills in b.Payouts for a final result and updates the leaderboard.
// majority is nil when the players agreed (no judges involved).
func (b *Bet) settle(final string, majority []address) {
	b.Status = StatusSettled
	totalSettled++
	b.Final = final
	pot := 2 * b.Stake

	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = 2 * (b.Stake / 100) // 1% of the pot, always even
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, minus the judges' fee.
	switch final {
	case ResultA:
		add(b.PlayerA, pot-fee, "won the pot")
	case ResultB:
		add(b.PlayerB, pot-fee, "won the pot")
	case ResultDraw:
		add(b.PlayerA, b.Stake-fee/2, "draw, stake back")
		add(b.PlayerB, b.Stake-fee/2, "draw, stake back")
	}

	// 2. Honesty bonds.
	forfeited := int64(0)
	var honest []address
	t := mustTable(b.TableID)
	players := []address{b.PlayerA, b.PlayerB}
	reports := []string{b.ReportA, b.ReportB}
	for i := range players {
		if !disputed || reports[i] == final {
			add(players[i], b.Bond, "bond back")
			if disputed {
				honest = append(honest, players[i])
			}
		} else {
			forfeited += b.Bond
			t.stats(players[i]).DisputesLost++
			liarsCaught++
		}
	}

	// 3. Forfeited bonds: half to the honest player(s), half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liar's bond", add)
		} else {
			judgePool += forfeited
		}
	}

	// 4. Judges who voted with the majority split their pool.
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
		}
	}

	b.Payouts = payouts
	if pot > biggestPot {
		biggestPot = pot
	}
	for _, j := range majority {
		judgesPaid += received(payouts, j)
	}

	// Leaderboard: net result per person, relative to what they put in.
	deposit := b.Stake + b.Bond
	t.stats(b.PlayerA).Net += received(payouts, b.PlayerA) - deposit
	t.stats(b.PlayerB).Net += received(payouts, b.PlayerB) - deposit
	for _, j := range majority {
		t.stats(j).Net += received(payouts, j)
	}
	switch final {
	case ResultA:
		t.stats(b.PlayerA).Wins++
		t.stats(b.PlayerB).Losses++
	case ResultB:
		t.stats(b.PlayerB).Wins++
		t.stats(b.PlayerA).Losses++
	case ResultDraw:
		t.stats(b.PlayerA).Draws++
		t.stats(b.PlayerB).Draws++
	}
}

// split divides amount evenly; the remainder goes to the first recipient so
// no dust is ever stuck in the realm.
func split(to []address, amount int64, why string, add func(address, int64, string)) {
	if len(to) == 0 || amount <= 0 {
		return
	}
	n := int64(len(to))
	each := amount / n
	rest := amount - each*n
	for i, a := range to {
		amt := each
		if i == 0 {
			amt += rest
		}
		add(a, amt, why)
	}
}

func received(payouts []Payout, who address) int64 {
	total := int64(0)
	for _, p := range payouts {
		if p.To == who {
			total += p.Amount
		}
	}
	return total
}

// pay moves the coins. The banker is always created inside the exported
// crossing function, from its own cur.
func pay(bk banker.Banker, from address, payouts []Payout) {
	for _, p := range payouts {
		bk.SendCoins(from, p.To, chain.Coins{{"ugnot", p.Amount}})
	}
}

// ---------------------------------------------------------------------------
// Read-only getters

func GetTableName(tableID int) string { return mustTable(tableID).Name }
func GetBetStatus(betID int) string   { return mustBet(betID).Status.String() }
func GetBetResult(betID int) string   { return mustBet(betID).Final }

func GetNet(tableID int, who address) int64 {
	t := mustTable(tableID)
	if v := t.Stats.Get(who.String()); v != nil {
		return v.(*Stats).Net
	}
	return 0
}

// ---------------------------------------------------------------------------
// Helpers

func (t *Table) isMember(a address) bool {
	for _, m := range t.Members {
		if m == a {
			return true
		}
	}
	return false
}

// setName validates and stores a nickname (unique per table). An empty
// nickname clears it, and the address is shown instead.
func (t *Table) setName(a address, nickname string) {
	nickname = strings.TrimSpace(nickname)
	if nickname == "" {
		t.Names.Remove(a.String())
		return
	}
	require(len(nickname) <= 24, "nickname too long (max 24)")
	for _, r := range nickname {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.'
		require(ok, "nickname can only use letters, numbers, spaces, - _ .")
	}
	lower := strings.ToLower(nickname)
	t.Names.Iterate("", "", func(k string, v any) bool {
		require(k == a.String() || strings.ToLower(v.(string)) != lower, "nickname already taken at this table")
		return false
	})
	t.Names.Set(a.String(), nickname)
}

// Nick returns a member's nickname, or "" if they have none.
func (t *Table) Nick(a address) string {
	if v := t.Names.Get(a.String()); v != nil {
		return v.(string)
	}
	return ""
}

// judgesFor lists every member except the two players.
func (t *Table) judgesFor(a, b address) []address {
	var judges []address
	for _, m := range t.Members {
		if m != a && m != b {
			judges = append(judges, m)
		}
	}
	return judges
}

// resolve finds a member by nickname (case-insensitive) or g1 address.
func (t *Table) resolve(who string) address {
	who = strings.TrimSpace(who)
	if strings.HasPrefix(who, "g1") {
		if a := address(who); a.IsValid() {
			require(t.isMember(a), "opponent is not a member of this table")
			return a
		}
	}
	lower := strings.ToLower(who)
	var found address
	t.Names.Iterate("", "", func(k string, v any) bool {
		if strings.ToLower(v.(string)) == lower {
			found = address(k)
			return true
		}
		return false
	})
	require(found != "" && t.isMember(found), "opponent is not a member of this table")
	return found
}

func (t *Table) stats(a address) *Stats {
	if v := t.Stats.Get(a.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	t.Stats.Set(a.String(), s)
	return s
}

func (b *Bet) isJudge(a address) bool {
	for _, j := range b.Judges {
		if j == a {
			return true
		}
	}
	return false
}

func (b *Bet) countVotes(result string) int {
	n := 0
	b.Votes.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == result {
			n++
		}
		return false
	})
	return n
}

// printable rejects control characters (newlines, tabs, etc.).
func printable(s string) bool {
	for _, r := range s {
		if r < 32 || r == 127 {
			return false
		}
	}
	return true
}

func normalizeResult(r string) string {
	r = strings.ToLower(strings.TrimSpace(r))
	require(r == ResultA || r == ResultB || r == ResultDraw, `result must be "a", "b" or "draw"`)
	return r
}

func requireSent(want int64) {
	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == "ugnot",
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
	require(sent[0].Amount == want,
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
}

func mustTable(id int) *Table {
	v := tables.Get(strconv.Itoa(id))
	if v == nil {
		panic("table not found")
	}
	return v.(*Table)
}

func mustBet(id int) *Bet {
	v := bets.Get(strconv.Itoa(id))
	if v == nil {
		panic("bet not found")
	}
	return v.(*Bet)
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

// Package taproom is a small realm that needs waking: the brew on tap changes
// on a schedule, and nothing in the realm can make that happen by itself.
//
// Its keeper opens it once, which posts one Lamplighter job. Whoever runs
// that job changes the tap and is paid by the registry.
package taproom

import (
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

const (
	// rotateEvery is the number of seconds each brew stays on tap.
	rotateEvery int64 = 300

	// reward is the ugnot the registry pays for each rotation.
	reward int64 = 50000

	// keeper alone can open and close the taproom. It is written here rather
	// than taken from whoever deployed the realm, so that it does not depend
	// on how the package was published or enabled.
	keeper address = "g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx"
)

var (
	brews = []string{
		"Gnomish Amber",
		"Deep Root Stout",
		"Mushroom Mead",
		"Lantern Lager",
		"Tinker's Pale",
	}

	onTap     int
	rotations int64
	since     int64

	// jobID is the taproom's job in the registry, 0 until the keeper opens
	// the taproom. The registry numbers jobs from 1.
	jobID  uint64
	closed bool
)

// Open posts the taproom's job: the first change of brew one interval from
// now, then one every interval. Only the keeper can call it, and only once.
// The keeper's transaction pays the storage deposit for the job.
func Open(cur realm) {
	if cur.Previous().Address() != keeper {
		panic("only the keeper can open the taproom")
	}
	if closed {
		panic("the taproom is closed for good")
	}
	if jobID != 0 {
		panic("the taproom is already open")
	}
	since = time.Now().Unix()
	jobID = registry.Register(cross(cur), "Taproom: change the brew on tap",
		since+rotateEvery, rotateEvery, reward, rotate)
}

// rotate is the callback the registry holds.
//
// The registry runs any callback for anyone, so "the registry called me" is
// not enough: another realm could post a job of its own that points here. The
// job id is what ties a call to the schedule this realm asked for.
func rotate(cur realm, job uint64) error {
	if cur.Previous().PkgPath() != registry.Path() || job != jobID {
		return errors.New("only the taproom's own lamplighter job may change the tap")
	}
	onTap = (onTap + 1) % len(brews)
	rotations++
	since = time.Now().Unix()
	return nil
}

// Close stops the rotation for good and returns the oil the job still holds
// to the keeper. Only the keeper can call it.
func Close(cur realm) {
	if cur.Previous().Address() != keeper {
		panic("only the keeper can close the taproom")
	}
	if closed {
		panic("the taproom is already closed")
	}
	if jobID == 0 {
		panic("the taproom is not open")
	}
	closed = true
	registry.Cancel(cross(cur), jobID, keeper)
}

// OnTap returns the brew currently on tap.
func OnTap() string { return brews[onTap] }

// Rotations returns how many times the tap has been changed.
func Rotations() int64 { return rotations }

// JobID returns the id of this realm's job in the registry, or 0 before the
// taproom opens.
func JobID() uint64 { return jobID }

// Keeper returns the account that can close the taproom.
func Keeper() address { return keeper }

func Render(_ string) string {
	job := strconv.FormatUint(jobID, 10)
	registryURL := strings.TrimPrefix(registry.Path(), "gno.land")
	jobURL := registryURL + ":job/" + job
	now := time.Now().Unix()

	var b strings.Builder
	b.WriteString("# The Taproom\n\n")
	b.WriteString("## On tap: " + OnTap() + "\n\n")
	if jobID != 0 {
		b.WriteString("Poured since " + time.Unix(since, 0).UTC().Format("2006-01-02 15:04:05") +
			" UTC. The tap has been changed " + strconv.FormatInt(rotations, 10) + " times.\n\n")
	}

	switch {
	case jobID == 0:
		b.WriteString("The brew should change every " + strconv.FormatInt(rotateEvery/60, 10) +
			" minutes, but a realm cannot wake itself. The taproom has not opened yet: when its keeper opens it, " +
			"it posts that work as a Lamplighter job, and whoever runs the job changes the tap and is paid for it.\n\n")
	case closed:
		b.WriteString("The taproom is closed: its keeper stopped the rotation.\n\n")
	default:
		b.WriteString("The brew should change every " + strconv.FormatInt(rotateEvery/60, 10) +
			" minutes, but a realm cannot wake itself. So the taproom posted the work as [Lamplighter job " +
			job + "](" + jobURL + "): whoever runs it changes the tap and is paid " +
			strconv.FormatInt(reward, 10) + " ugnot for it.\n\n")

		switch {
		case registry.IsDue(jobID):
			b.WriteString("**The next change is due now.** [Run the job](" + jobURL + ") and it is yours.\n\n")
		case registry.Balance(jobID) < reward:
			b.WriteString("**The job is out of oil**, so nobody will change the tap. [Add oil](" +
				txlink.Realm(registry.Path()).NewLink("Fund").AddArgs("id", job).SetSend("1000000ugnot").URL() + ")\n\n")
		default:
			b.WriteString("Next change in " + strconv.FormatInt(registry.NextDue(jobID)-now, 10) + " seconds.\n\n")
		}
	}

	b.WriteString("| Brew | |\n|---|---|\n")
	for i, name := range brews {
		mark := ""
		if i == onTap {
			mark = "on tap"
		}
		b.WriteString("| " + name + " | " + mark + " |\n")
	}
	return b.String()
}

package taproom

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

var (
	registryAddr = chain.PackageAddress(registry.Path())
	patron       = testutils.TestAddress("patron")
	lighter      = testutils.TestAddress("lighter")
)

func ugnotOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, registry.Denom)
}

// restock gives the registry back the coins the taproom's job holds. The test
// runtime starts every test function with empty balances but keeps realm
// state, so the oil an earlier test left in the job has to be issued again.
func restock() {
	if left := registry.Balance(JobID()); left > 0 {
		testing.IssueCoins(registryAddr, chain.Coins{{registry.Denom, left}})
	}
}

// Nothing is posted until the keeper opens the taproom, and only the keeper
// can, once.
func TestOnlyTheKeeperOpens(cur realm, t *testing.T) {
	uassert.Equal(t, uint64(0), JobID())
	uassert.True(t, strings.Contains(Render(""), "The taproom has not opened yet"))
	uassert.False(t, strings.Contains(Render(""), "/lamplighter/registry/v2:job/"))

	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.AbortsWithMessage(t, cur, "only the keeper can open the taproom", func() { Open(cross(cur)) })
	testing.SetRealm(testing.NewUserRealm(keeper))
	uassert.AbortsWithMessage(t, cur, "the taproom is not open", func() { Close(cross(cur)) })
	uassert.Equal(t, uint64(0), JobID())

	Open(cross(cur))
	uassert.True(t, JobID() != 0)
	uassert.True(t, registry.Exists(JobID()))
	uassert.Equal(t, registry.NextDue(JobID()), since+rotateEvery)
	uassert.AbortsWithMessage(t, cur, "the taproom is already open", func() { Open(cross(cur)) })
}

// The whole point of the project in one test: this realm registered a
// callback with another realm, and a stranger calling that other realm
// changes this realm's state and is paid for it.
func TestStrangerRotatesTheTap(cur realm, t *testing.T) {
	uassert.Equal(t, "Gnomish Amber", OnTap())
	uassert.Equal(t, int64(0), Rotations())
	uassert.True(t, strings.Contains(Render(""), "The job is out of oil"))

	// A patron funds three rotations.
	oil := chain.Coins{{registry.Denom, 3 * reward}}
	testing.IssueCoins(registryAddr, oil)
	testing.SetRealm(testing.NewUserRealm(patron))
	testing.SetOriginSend(oil)
	registry.Fund(cross(cur), JobID())
	testing.SetOriginSend(nil)
	uassert.True(t, strings.Contains(Render(""), "Next change in 300 seconds"))

	// Too early.
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.False(t, registry.IsDue(JobID()))
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() {
		registry.Exec(cross(cur), JobID())
	})

	// 61 blocks of 5s is 305s, past the 300s rotation.
	testing.SkipHeights(61)
	uassert.True(t, registry.IsDue(JobID()))
	uassert.True(t, strings.Contains(Render(""), "The next change is due now"))

	before := ugnotOf(lighter)
	testing.SetRealm(testing.NewUserRealm(lighter))
	registry.Exec(cross(cur), JobID())

	uassert.Equal(t, "Deep Root Stout", OnTap())
	uassert.Equal(t, int64(1), Rotations())
	uassert.Equal(t, before+reward, ugnotOf(lighter))

	// Same slot again is refused; the next slot works.
	uassert.AbortsWithMessage(t, cur, "job is not due yet", func() {
		registry.Exec(cross(cur), JobID())
	})
	testing.SkipHeights(60)
	testing.SetRealm(testing.NewUserRealm(lighter))
	registry.Exec(cross(cur), JobID())
	uassert.Equal(t, "Mushroom Mead", OnTap())
	uassert.Equal(t, int64(2), Rotations())
}

// Nobody but the registry, running the taproom's own job, can reach the callback.
func TestRotateRefusesOtherCallers(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.True(t, rotate(cross(cur), JobID()) != nil, "a user")

	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/impostor"))
	uassert.True(t, rotate(cross(cur), JobID()) != nil, "another realm")
}

func TestRender(t *testing.T) {
	out := Render("")
	uassert.True(t, strings.Contains(out, "# The Taproom"))
	uassert.True(t, strings.Contains(out, "## On tap: "+OnTap()))
	uassert.True(t, strings.Contains(out, "/lamplighter/registry/v2:job/"))
}

// Close ends the job the tests above use.
func TestOnlyTheKeeperCloses(cur realm, t *testing.T) {
	restock()

	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.AbortsWithMessage(t, cur, "only the keeper can close the taproom", func() { Close(cross(cur)) })

	left := registry.Balance(JobID())
	uassert.True(t, left > 0)
	before := ugnotOf(keeper)

	testing.SetRealm(testing.NewUserRealm(keeper))
	Close(cross(cur))
	uassert.Equal(t, before+left, ugnotOf(keeper), "the unspent oil comes back")
	uassert.False(t, registry.Exists(JobID()))
	uassert.True(t, strings.Contains(Render(""), "The taproom is closed"))

	uassert.AbortsWithMessage(t, cur, "the taproom is already closed", func() { Close(cross(cur)) })
	uassert.AbortsWithMessage(t, cur, "the taproom is closed for good", func() { Open(cross(cur)) })
}

// The registry runs any callback for anyone. Another realm that gets hold of
// this one's callback and posts it as a job of its own, on its own schedule,
// must get nowhere: the job id is not the taproom's.
//
// This test is last because the refused run aborts mid-way. On chain that
// reverts the transaction; the test runtime keeps the registry's lock set.
func TestAnotherRealmCannotScheduleTheTap(cur realm, t *testing.T) {
	restock()
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/test/attacker"))
	hijack := registry.Register(cross(cur), "hijack", 0, 10, registry.MinReward, rotate)
	uassert.True(t, hijack != JobID())

	testing.IssueCoins(registryAddr, chain.Coins{{registry.Denom, 10 * registry.MinReward}})
	registry.Credit(cross(cur), hijack, 10*registry.MinReward)
	uassert.True(t, registry.IsDue(hijack))

	before := Rotations()
	testing.SetRealm(testing.NewUserRealm(lighter))
	uassert.AbortsWithMessage(t, cur,
		"job failed: only the taproom's own lamplighter job may change the tap",
		func() { registry.Exec(cross(cur), hijack) })
	uassert.Equal(t, before, Rotations())
}

// Package bnprobe is a deployment probe for the bn254 precompiles. It exists so
// a package that imports a crypto stdlib can be submitted and its approval
// status observed; it holds no state and verifies nothing.
package bnprobe

import "crypto/bn254"

// AddInfinity returns the precompile's answer for the identity added to itself.
func AddInfinity() []byte {
	return bn254.G1Add(make([]byte, bn254.G1AddInputSize))
}

// Package plainprobe is a deployment probe that imports no crypto stdlib, so its
// approval status can be compared with bnprobe's.
package plainprobe

import "strings"

// Upper returns s in upper case.
func Upper(s string) string {
	return strings.ToUpper(s)
}

// Package shaprobe is a deployment probe importing an old crypto stdlib, so its
// approval status can be compared with bnprobe's.
package shaprobe

import "crypto/solsha3"

// Sum returns the sha3 sum of b.
func Sum(b []byte) []byte {
	return solsha3.Sum256(b)[:]
}
